insert into public.worlds (id, learning_level_id, title, description, theme_key, display_order, is_published, translations) values
  ('6335c2b2-e835-4119-b1d4-f67868c432df', '00000000-0000-4000-8000-000000000001', 'Number Forest', 'Count, compare and explore numbers among the trees.', 'forest', 1, true, '{"my":{"title":"ကိန်းဂဏန်းတော","description":"သစ်ပင်တွေကြားမှာ ဂဏန်းတွေကို ရေတွက်၊ နှိုင်းယှဉ်ပြီး စူးစမ်းပါ။"},"th":{"title":"ป่าตัวเลข","description":"นับ เปรียบเทียบ และสำรวจตัวเลขท่ามกลางต้นไม้"}}'::jsonb),
