  ('36807931-54be-4146-983f-dbc3c861e1a8', '00000000-0000-4000-8000-000000000002', 'Multiplication Mountain', 'Climb with place value and times tables.', 'mountain', 1, true, '{"my":{"title":"အမြှောက်တောင်","description":"နေရာတန်ဖိုးနဲ့ အမြှောက်ဇယားတွေနဲ့ တောင်တက်ပါ။"},"th":{"title":"ภูเขาการคูณ","description":"ปีนเขาด้วยค่าประจำหลักและสูตรคูณ"}}'::jsonb),
  ('0a7a6b88-cff2-460d-a3fa-ac2e658a94a3', '00000000-0000-4000-8000-000000000002', 'Fraction Ocean', 'Dive into sharing, division and fractions.', 'ocean', 2, true, '{"my":{"title":"အပိုင်းကိန်းပင်လယ်","description":"ခွဲဝေခြင်း၊ စားခြင်းနဲ့ အပိုင်းကိန်းတွေထဲ ငုပ်ဆင်းပါ။"},"th":{"title":"มหาสมุทรเศษส่วน","description":"ดำดิ่งสู่การแบ่ง การหาร และเศษส่วน"}}'::jsonb),
  ('8d577cb0-c366-47b1-8c3a-f01a5e6fe003', '00000000-0000-4000-8000-000000000002', 'Clockwork City', 'Tell the time, count money and explore shapes.', 'city', 3, true, '{"my":{"title":"နာရီမြို့","description":"အချိန်ကြည့်၊ ငွေရေပြီး ပုံသဏ္ဌာန်တွေကို စူးစမ်းပါ။"},"th":{"title":"เมืองนาฬิกา","description":"บอกเวลา นับเงิน และสำรวจรูปทรง"}}'::jsonb),
  ('4d356a8b-10ed-4102-8e65-25e50d1d2574', '00000000-0000-4000-8000-000000000003', 'Decimal Lagoon', 'Fractions, decimals, percentages and ratios.', 'lagoon', 1, true, '{"my":{"title":"ဒသမ ကန်ရေပြင်","description":"အပိုင်းကိန်း၊ ဒသမကိန်း၊ ရာခိုင်နှုန်းနဲ့ အချိုး။"},"th":{"title":"ทะเลสาบทศนิยม","description":"เศษส่วน ทศนิยม ร้อยละ และอัตราส่วน"}}'::jsonb),
  ('349cfa46-3361-41b9-9363-d55811932af3', '00000000-0000-4000-8000-000000000003', 'Integer Icefields', 'Below zero and into algebra.', 'ice', 2, true, '{"my":{"title":"ကိန်းပြည့် ရေခဲပြင်","description":"သုညအောက်ကို ဆင်းပြီး အက္ခရာသင်္ချာထဲ ဝင်ပါ။"},"th":{"title":"ทุ่งน้ำแข็งจำนวนเต็ม","description":"ลงไปต่ำกว่าศูนย์และเข้าสู่พีชคณิต"}}'::jsonb),
  ('95b4708c-510b-4e73-8517-245e834662dd', '00000000-0000-4000-8000-000000000003', 'Geometry Galaxy', 'Perimeter and area among the stars.', 'galaxy', 3, true, '{"my":{"title":"ဂျီသြမေတြီ နဂါးငွေ့တန်း","description":"ကြယ်တွေကြားမှာ ပတ်လည်အနားနဲ့ ဧရိယာ။"},"th":{"title":"กาแล็กซีเรขาคณิต","description":"ความยาวรอบรูปและพื้นที่ท่ามกลางดวงดาว"}}'::jsonb)
insert into public.topics (id, learning_level_id, title, description, display_order, is_published, translations) values
  ('874259d3-0f0a-4ef0-acc8-533d5b02d0e2', '00000000-0000-4000-8000-000000000001', 'Counting', 'Counting objects and reading numbers to 20.', 1, true, '{"my":{"title":"ရေတွက်ခြင်း","description":"20 အထိ အရာဝတ္ထုတွေ ရေတွက်ပြီး ဂဏန်းတွေ ဖတ်ခြင်း။"},"th":{"title":"การนับ","description":"นับสิ่งของและอ่านตัวเลขถึง 20"}}'::jsonb),
  ('7aea290e-55e8-466b-8cab-2b2426cd76d1', '00000000-0000-4000-8000-000000000001', 'Comparing Numbers', 'More, fewer, greater than and less than.', 2, true, '{"my":{"title":"ကိန်းဂဏန်း နှိုင်းယှဉ်ခြင်း","description":"ပိုများ၊ ပိုနည်း၊ ထက်ကြီး၊ ထက်ငယ်။"},"th":{"title":"การเปรียบเทียบจำนวน","description":"มากกว่า น้อยกว่า"}}'::jsonb),
  ('d3c30eae-92d4-4f1d-9616-18dc47b95b7b', '00000000-0000-4000-8000-000000000001', 'Addition', 'Adding numbers to 20.', 3, true, '{"my":{"title":"ပေါင်းခြင်း","description":"20 အထိ ဂဏန်းတွေ ပေါင်းခြင်း။"},"th":{"title":"การบวก","description":"บวกจำนวนไม่เกิน 20"}}'::jsonb),
  ('5e571634-d6d8-441d-b466-29fe39980c47', '00000000-0000-4000-8000-000000000001', 'Subtraction', 'Taking away and counting back.', 4, true, '{"my":{"title":"နုတ်ခြင်း","description":"ယူလိုက်ခြင်းနဲ့ နောက်ပြန်ရေခြင်း။"},"th":{"title":"การลบ","description":"เอาออกและนับถอยหลัง"}}'::jsonb),
  ('de4c4772-cf46-4127-bfc4-943022a5eb05', '00000000-0000-4000-8000-000000000001', 'Shapes, Patterns and Measuring', 'Naming shapes, continuing patterns and measuring length.', 5, true, '{"my":{"title":"ပုံသဏ္ဌာန်၊ ပုံစံနှင့် တိုင်းတာခြင်း","description":"ပုံသဏ္ဌာန် အမည်ပေးခြင်း၊ ပုံစံ ဆက်ခြင်းနဲ့ အလျား တိုင်းခြင်း။"},"th":{"title":"รูปทรง แบบรูป และการวัด","description":"บอกชื่อรูปทรง ต่อแบบรูป และวัดความยาว"}}'::jsonb),
  ('f9f21cc0-fb06-4319-ace0-42a6333593ef', '00000000-0000-4000-8000-000000000002', 'Place Value', 'Hundreds, tens and ones, digit values and rounding.', 1, true, '{"my":{"title":"နေရာတန်ဖိုး","description":"ရာ၊ ဆယ်၊ ခု၊ ဂဏန်းတန်ဖိုးနဲ့ ခန့်မှန်းခြင်း။"},"th":{"title":"ค่าประจำหลัก","description":"หลักร้อย สิบ หน่วย ค่าของเลขโดด และการปัดเศษ"}}'::jsonb),
  ('cd2b3b33-e26d-4530-8a0c-3251e1089e7e', '00000000-0000-4000-8000-000000000002', 'Multiplication', 'Equal groups, arrays, times tables and word problems.', 2, true, '{"my":{"title":"မြှောက်ခြင်း","description":"အုပ်စုညီ၊ အတန်းအစီ၊ အမြှောက်ဇယားနဲ့ ပုစ္ဆာများ။"},"th":{"title":"การคูณ","description":"กลุ่มที่เท่ากัน แถวลำดับ สูตรคูณ และโจทย์ปัญหา"}}'::jsonb),
  ('88aea126-fc96-4fa5-9b86-86a01ff45257', '00000000-0000-4000-8000-000000000002', 'Division', 'Sharing equally, division facts and remainders.', 3, true, '{"my":{"title":"စားခြင်း","description":"ညီညီမျှမျှ ခွဲဝေခြင်း၊ အစားဖော်မြူလာနဲ့ အကြွင်း။"},"th":{"title":"การหาร","description":"การแบ่งเท่า ๆ กัน การหารตามสูตรคูณ และเศษ"}}'::jsonb),
  ('a8925bd0-a9a5-4059-a5ec-4c4e3e1183df', '00000000-0000-4000-8000-000000000002', 'Fractions', 'Parts of a whole, fractions of amounts, comparing fractions.', 4, true, '{"my":{"title":"အပိုင်းကိန်း","description":"တစ်ခုလုံး၏ အစိတ်အပိုင်း၊ ပမာဏ၏ အပိုင်းကိန်းနဲ့ အပိုင်းကိန်း နှိုင်းယှဉ်ခြင်း။"},"th":{"title":"เศษส่วน","description":"ส่วนหนึ่งของทั้งหมด เศษส่วนของจำนวน และการเปรียบเทียบเศษส่วน"}}'::jsonb),
  ('30449cbc-fce1-4f01-a0de-33d62b45dd53', '00000000-0000-4000-8000-000000000002', 'Time, Money and Shapes', 'Reading clocks, counting money and basic geometry.', 5, true, '{"my":{"title":"အချိန်၊ ငွေနှင့် ပုံသဏ္ဌာန်","description":"နာရီ ဖတ်ခြင်း၊ ငွေ ရေတွက်ခြင်းနဲ့ အခြေခံ ဂျီသြမေတြီ။"},"th":{"title":"เวลา เงิน และรูปทรง","description":"อ่านนาฬิกา นับเงิน และเรขาคณิตพื้นฐาน"}}'::jsonb),
  ('9f308b1e-9bb2-48f9-acd4-e1d041806b83', '00000000-0000-4000-8000-000000000003', 'Fractions and Decimals', 'Converting, adding fractions and calculating with decimals.', 1, true, '{"my":{"title":"အပိုင်းကိန်းနှင့် ဒသမကိန်း","description":"ပြောင်းလဲခြင်း၊ အပိုင်းကိန်း ပေါင်းခြင်းနဲ့ ဒသမကိန်း တွက်ချက်ခြင်း။"},"th":{"title":"เศษส่วนและทศนิยม","description":"การแปลง การบวกเศษส่วน และการคำนวณทศนิยม"}}'::jsonb),
  ('edb4ec1c-1a07-42b7-a3c7-2e2e57389ec1', '00000000-0000-4000-8000-000000000003', 'Percentages and Ratios', 'Understanding percent, finding percentages and working with ratios.', 2, true, '{"my":{"title":"ရာခိုင်နှုန်းနှင့် အချိုး","description":"ရာခိုင်နှုန်းကို နားလည်ခြင်း၊ ရာခိုင်နှုန်း ရှာခြင်းနဲ့ အချိုးဖြင့် တွက်ခြင်း။"},"th":{"title":"ร้อยละและอัตราส่วน","description":"เข้าใจร้อยละ หาร้อยละ และใช้อัตราส่วน"}}'::jsonb),
  ('27e47ed0-dcb8-4f5f-9708-354eab2063cd', '00000000-0000-4000-8000-000000000003', 'Negative Numbers', 'Ordering, adding and subtracting numbers below zero.', 3, true, '{"my":{"title":"အနုတ်ကိန်း","description":"သုညအောက် ဂဏန်းတွေကို စီ၊ ပေါင်း၊ နုတ်ခြင်း။"},"th":{"title":"จำนวนลบ","description":"เรียงลำดับ บวก และลบจำนวนที่ต่ำกว่าศูนย์"}}'::jsonb),
  ('7bc79dc7-9fea-4524-a7ad-34c5ae012802', '00000000-0000-4000-8000-000000000003', 'Area and Perimeter', 'Perimeter, area of rectangles and triangles.', 4, true, '{"my":{"title":"ဧရိယာနှင့် ပတ်လည်အနား","description":"ပတ်လည်အနား၊ ထောင့်မှန်စတုဂံနဲ့ တြိဂံ ဧရိယာ။"},"th":{"title":"พื้นที่และความยาวรอบรูป","description":"ความยาวรอบรูป พื้นที่ของสี่เหลี่ยมผืนผ้าและสามเหลี่ยม"}}'::jsonb),
  ('43bb5e40-227c-4861-9891-3fa243f34733', '00000000-0000-4000-8000-000000000003', 'Algebra and Problem Solving', 'Expressions, equations and multi-step word problems.', 5, true, '{"my":{"title":"အက္ခရာသင်္ချာနှင့် ပြဿနာဖြေရှင်းခြင်း","description":"ကိန်းတန်း၊ ညီမျှခြင်းနဲ့ အဆင့်များစွာပါ ပုစ္ဆာများ။"},"th":{"title":"พีชคณิตและการแก้ปัญหา","description":"นิพจน์ สมการ และโจทย์ปัญหาหลายขั้นตอน"}}'::jsonb)
insert into public.lessons (id, world_id, topic_id, title, description, learning_objective, difficulty, estimated_minutes, display_order, is_published, translations) values
  ('dc34b71a-d6e5-4a61-9ecb-9ec077dc9567', '6335c2b2-e835-4119-b1d4-f67868c432df', '874259d3-0f0a-4ef0-acc8-533d5b02d0e2', 'Count to 10', 'Count groups of things up to 10.', 'I can count up to 10 objects.', 1, 5, 1, true, '{"my":{"title":"10 အထိ ရေတွက်ကြစို့","description":"10 အထိ အရာဝတ္ထု အုပ်စုတွေကို ရေတွက်ပါ။","learning_objective":"အရာဝတ္ထု 10 ခုအထိ ရေတွက်နိုင်တယ်။"},"th":{"title":"นับถึง 10","description":"นับกลุ่มสิ่งของไม่เกิน 10","learning_objective":"ฉันนับสิ่งของได้ถึง 10 ชิ้น"}}'::jsonb),
  ('6466b95c-5236-41fb-96f6-ee8a086d78a9', '6335c2b2-e835-4119-b1d4-f67868c432df', '874259d3-0f0a-4ef0-acc8-533d5b02d0e2', 'Numbers to 20', 'Teen numbers are one ten and some ones.', 'I can read and count numbers from 11 to 20.', 1, 6, 2, true, '{"my":{"title":"20 အထိ ဂဏန်းများ","description":"11 မှ 19 ဂဏန်းတွေက ဆယ် 1 ခုနဲ့ ခု အချို့ပါ။","learning_objective":"11 မှ 20 အထိ ဂဏန်းတွေကို ဖတ်ပြီး ရေတွက်နိုင်တယ်။"},"th":{"title":"จำนวนถึง 20","description":"จำนวน 11 ถึง 19 คือ 1 สิบกับหน่วยอีกจำนวนหนึ่ง","learning_objective":"ฉันอ่านและนับจำนวน 11 ถึง 20 ได้"}}'::jsonb),
  ('6053143c-ae0e-46dd-9e21-bd3ebcc98f37', '6335c2b2-e835-4119-b1d4-f67868c432df', '874259d3-0f0a-4ef0-acc8-533d5b02d0e2', 'Counting on and back', 'Count forwards and backwards on a number line.', 'I can count on and count back from any number to 20.', 2, 6, 3, true, '{"my":{"title":"ရှေ့ဆက်ရေခြင်းနဲ့ နောက်ပြန်ရေခြင်း","description":"ကိန်းမျဉ်းပေါ်မှာ ရှေ့ကိုရော နောက်ကိုရော ရေပါ။","learning_objective":"20 အထိ ဘယ်ဂဏန်းကနေမဆို ရှေ့ဆက်ရေ၊ နောက်ပြန်ရေ နိုင်တယ်။"},"th":{"title":"นับต่อและนับถอยหลัง","description":"นับไปข้างหน้าและถอยหลังบนเส้นจำนวน","learning_objective":"ฉันนับต่อและนับถอยหลังจากจำนวนใดก็ได้ไม่เกิน 20"}}'::jsonb),
  ('fc8aee44-02c6-402f-a98f-8b0ebfb8b981', '6335c2b2-e835-4119-b1d4-f67868c432df', '7aea290e-55e8-466b-8cab-2b2426cd76d1', 'More or fewer', 'Compare two groups to find which has more.', 'I can tell which group has more and which has fewer.', 1, 5, 4, true, '{"my":{"title":"ပိုများလား ပိုနည်းလား","description":"အုပ်စုနှစ်စုကို နှိုင်းယှဉ်ပြီး ဘယ်ဟာ ပိုများလဲ ရှာပါ။","learning_objective":"ဘယ်အုပ်စုက ပိုများပြီး ဘယ်အုပ်စုက ပိုနည်းလဲ ပြောနိုင်တယ်။"},"th":{"title":"มากกว่าหรือน้อยกว่า","description":"เปรียบเทียบสองกลุ่มเพื่อหาว่ากลุ่มใดมากกว่า","learning_objective":"ฉันบอกได้ว่ากลุ่มใดมากกว่าและกลุ่มใดน้อยกว่า"}}'::jsonb),
  ('408e95f1-7968-453a-9794-7e1b52677f44', '6335c2b2-e835-4119-b1d4-f67868c432df', '7aea290e-55e8-466b-8cab-2b2426cd76d1', 'Greater than, less than', 'Use <, > and = with numbers to 50.', 'I can use <, > and = to compare numbers.', 2, 6, 5, true, '{"my":{"title":"ထက်ကြီးသည်၊ ထက်ငယ်သည်","description":"50 အထိ ဂဏန်းတွေနဲ့ <၊ > နဲ့ = ကို သုံးပါ။","learning_objective":"ဂဏန်းတွေ နှိုင်းယှဉ်ဖို့ <၊ > နဲ့ = ကို သုံးနိုင်တယ်။"},"th":{"title":"มากกว่า น้อยกว่า","description":"ใช้ <, > และ = กับจำนวนไม่เกิน 50","learning_objective":"ฉันใช้ <, > และ = เปรียบเทียบจำนวนได้"}}'::jsonb),
  ('c48ad5f6-a514-4bf9-a5af-92787ce41a43', '6335c2b2-e835-4119-b1d4-f67868c432df', '7aea290e-55e8-466b-8cab-2b2426cd76d1', 'Putting numbers in order', 'Find the smallest and biggest numbers.', 'I can put numbers in order from smallest to biggest.', 2, 6, 6, true, '{"my":{"title":"ဂဏန်းတွေကို အစဉ်လိုက် စီခြင်း","description":"အငယ်ဆုံးနဲ့ အကြီးဆုံး ဂဏန်းတွေကို ရှာပါ။","learning_objective":"ဂဏန်းတွေကို အငယ်ဆုံးမှ အကြီးဆုံးသို့ စီနိုင်တယ်။"},"th":{"title":"เรียงลำดับจำนวน","description":"หาจำนวนที่น้อยที่สุดและมากที่สุด","learning_objective":"ฉันเรียงจำนวนจากน้อยไปมากได้"}}'::jsonb),
  ('4fc0c1b3-fe5d-4faa-9218-6c29d9e76f88', 'dc9b91ec-7788-48e5-bb83-0d6a0392d583', 'd3c30eae-92d4-4f1d-9616-18dc47b95b7b', 'Adding with objects', 'Put two groups together and count them all.', 'I can add two groups to find how many altogether.', 1, 5, 1, true, '{"my":{"title":"အရာဝတ္ထုတွေနဲ့ ပေါင်းခြင်း","description":"အုပ်စုနှစ်စုကို ပေါင်းပြီး အားလုံးကို ရေပါ။","learning_objective":"အုပ်စုနှစ်စုကို ပေါင်းပြီး စုစုပေါင်း ဘယ်နှခု ရှိလဲ ရှာနိုင်တယ်။"},"th":{"title":"บวกด้วยสิ่งของ","description":"รวมสองกลุ่มเข้าด้วยกันแล้วนับทั้งหมด","learning_objective":"ฉันบวกสองกลุ่มเพื่อหาว่ามีทั้งหมดเท่าไร"}}'::jsonb),
  ('2ec58d61-ed6e-4d1a-b8b2-f957ef92b988', 'dc9b91ec-7788-48e5-bb83-0d6a0392d583', 'd3c30eae-92d4-4f1d-9616-18dc47b95b7b', 'Add on a number line', 'Jump forward on a number line to add.', 'I can add numbers to 20 using a number line.', 2, 6, 2, true, '{"my":{"title":"ကိန်းမျဉ်းပေါ်မှာ ပေါင်းခြင်း","description":"ပေါင်းဖို့ ကိန်းမျဉ်းပေါ်မှာ ရှေ့ကို ခုန်ပါ။","learning_objective":"ကိန်းမျဉ်းကို သုံးပြီး 20 အထိ ဂဏန်းတွေ ပေါင်းနိုင်တယ်။"},"th":{"title":"บวกบนเส้นจำนวน","description":"กระโดดไปข้างหน้าบนเส้นจำนวนเพื่อบวก","learning_objective":"ฉันบวกจำนวนไม่เกิน 20 โดยใช้เส้นจำนวนได้"}}'::jsonb),
  ('716be184-5ca4-403d-ba9b-d31eb16bdc47', 'dc9b91ec-7788-48e5-bb83-0d6a0392d583', 'd3c30eae-92d4-4f1d-9616-18dc47b95b7b', 'Missing numbers', 'Find the number that makes an addition true.', 'I can find a missing number in an addition.', 3, 7, 3, true, '{"my":{"title":"ပျောက်နေသော ဂဏန်းများ","description":"ပေါင်းခြင်းကို မှန်စေတဲ့ ဂဏန်းကို ရှာပါ။","learning_objective":"ပေါင်းခြင်းထဲက ပျောက်နေတဲ့ ဂဏန်းကို ရှာနိုင်တယ်။"},"th":{"title":"จำนวนที่หายไป","description":"หาจำนวนที่ทำให้การบวกถูกต้อง","learning_objective":"ฉันหาจำนวนที่หายไปในการบวกได้"}}'::jsonb),
  ('565b7100-bb4d-4b0b-972e-db26e0380799', 'dc9b91ec-7788-48e5-bb83-0d6a0392d583', '5e571634-d6d8-441d-b466-29fe39980c47', 'Taking away', 'Take some away and count what is left.', 'I can take away to find how many are left.', 1, 5, 4, true, '{"my":{"title":"ယူလိုက်ခြင်း","description":"တချို့ကို ယူလိုက်ပြီး ကျန်တာကို ရေပါ။","learning_objective":"ယူလိုက်ပြီး ဘယ်နှခု ကျန်လဲ ရှာနိုင်တယ်။"},"th":{"title":"การเอาออก","description":"เอาบางส่วนออก แล้วนับส่วนที่เหลือ","learning_objective":"ฉันเอาออกเพื่อหาว่าเหลือเท่าไร"}}'::jsonb),
  ('17caf138-c0ba-4da9-9cca-33d27b3c5543', 'dc9b91ec-7788-48e5-bb83-0d6a0392d583', '5e571634-d6d8-441d-b466-29fe39980c47', 'Count back to subtract', 'Jump back on a number line to subtract.', 'I can subtract numbers within 20 by counting back.', 2, 6, 5, true, '{"my":{"title":"နုတ်ဖို့ နောက်ပြန်ရေပါ","description":"နုတ်ဖို့ ကိန်းမျဉ်းပေါ်မှာ နောက်ကို ခုန်ပါ။","learning_objective":"နောက်ပြန်ရေပြီး 20 အတွင်း ဂဏန်းတွေ နုတ်နိုင်တယ်။"},"th":{"title":"นับถอยหลังเพื่อลบ","description":"กระโดดถอยหลังบนเส้นจำนวนเพื่อลบ","learning_objective":"ฉันลบจำนวนไม่เกิน 20 โดยการนับถอยหลังได้"}}'::jsonb),
  ('cdf411b2-d840-4c63-95a4-f150f50b9571', 'dc9b91ec-7788-48e5-bb83-0d6a0392d583', '5e571634-d6d8-441d-b466-29fe39980c47', 'Number stories', 'Decide whether to add or subtract in a story.', 'I can choose to add or subtract to solve a story problem.', 3, 7, 6, true, '{"my":{"title":"ဂဏန်း ပုံပြင်များ","description":"ပုံပြင်ထဲမှာ ပေါင်းမလား နုတ်မလား ဆုံးဖြတ်ပါ။","learning_objective":"ပုံပြင်ပုစ္ဆာ ဖြေရှင်းဖို့ ပေါင်းမလား နုတ်မလား ရွေးနိုင်တယ်။"},"th":{"title":"เรื่องราวตัวเลข","description":"ตัดสินใจว่าจะบวกหรือลบในเรื่องราว","learning_objective":"ฉันเลือกบวกหรือลบเพื่อแก้โจทย์ปัญหาได้"}}'::jsonb),
  ('3f3c3d29-ae1f-4416-bf29-d4034d6cfae0', 'dcc7c424-6870-40c5-8728-692e05532f0f', 'de4c4772-cf46-4127-bfc4-943022a5eb05', 'Name the shape', 'Know circles, triangles, squares and more.', 'I can name common 2D shapes and count their sides.', 1, 5, 1, true, '{"my":{"title":"ပုံသဏ္ဌာန်ကို အမည်ပေးပါ","description":"စက်ဝိုင်း၊ တြိဂံ၊ စတုရန်းနဲ့ အခြားပုံတွေကို သိပါ။","learning_objective":"အသုံးများတဲ့ 2D ပုံသဏ္ဌာန်တွေကို အမည်ပေးပြီး အနားတွေကို ရေတွက်နိုင်တယ်။"},"th":{"title":"บอกชื่อรูปทรง","description":"รู้จักวงกลม สามเหลี่ยม สี่เหลี่ยมจัตุรัส และอื่น ๆ","learning_objective":"ฉันบอกชื่อรูปสองมิติที่พบบ่อยและนับด้านได้"}}'::jsonb),
  ('27400d50-b0da-48c1-8cbb-a6ae0dd8ff5f', 'dcc7c424-6870-40c5-8728-692e05532f0f', 'de4c4772-cf46-4127-bfc4-943022a5eb05', 'Patterns', 'Continue shape and number patterns.', 'I can find what comes next in a pattern.', 2, 6, 2, true, '{"my":{"title":"ပုံစံများ","description":"ပုံသဏ္ဌာန်နဲ့ ဂဏန်း ပုံစံတွေကို ဆက်ပါ။","learning_objective":"ပုံစံတစ်ခုမှာ နောက်ထပ် ဘာလာမလဲ ရှာနိုင်တယ်။"},"th":{"title":"แบบรูป","description":"ต่อแบบรูปของรูปทรงและตัวเลข","learning_objective":"ฉันหาได้ว่าอะไรมาต่อไปในแบบรูป"}}'::jsonb),
  ('4d838ba2-d971-4609-8241-af6815c99ebf', 'dcc7c424-6870-40c5-8728-692e05532f0f', 'de4c4772-cf46-4127-bfc4-943022a5eb05', 'Measuring length', 'Use a ruler to measure in centimetres.', 'I can measure and compare lengths in centimetres.', 2, 6, 3, true, '{"my":{"title":"အလျား တိုင်းတာခြင်း","description":"စင်တီမီတာနဲ့ တိုင်းဖို့ ပေတံကို သုံးပါ။","learning_objective":"အလျားတွေကို စင်တီမီတာနဲ့ တိုင်းပြီး နှိုင်းယှဉ်နိုင်တယ်။"},"th":{"title":"การวัดความยาว","description":"ใช้ไม้บรรทัดวัดเป็นเซนติเมตร","learning_objective":"ฉันวัดและเปรียบเทียบความยาวเป็นเซนติเมตรได้"}}'::jsonb),
  ('1fa81736-0a83-4d8b-8c29-a94c0dbfaa51', '36807931-54be-4146-983f-dbc3c861e1a8', 'f9f21cc0-fb06-4319-ace0-42a6333593ef', 'Hundreds, tens and ones', 'Build 3-digit numbers from blocks.', 'I can read and make 3-digit numbers.', 1, 6, 1, true, '{"my":{"title":"ရာ၊ ဆယ်နှင့် ခု","description":"တုံးတွေကနေ ဂဏန်း 3 လုံးပါ ကိန်းတွေ တည်ဆောက်ပါ။","learning_objective":"ဂဏန်း 3 လုံးပါ ကိန်းတွေကို ဖတ်ပြီး ဖွဲ့နိုင်တယ်။"},"th":{"title":"หลักร้อย สิบ และหน่วย","description":"สร้างจำนวนสามหลักจากบล็อก","learning_objective":"ฉันอ่านและสร้างจำนวนสามหลักได้"}}'::jsonb),
  ('7a740449-3406-49aa-ad95-056bbbd042b4', '36807931-54be-4146-983f-dbc3c861e1a8', 'f9f21cc0-fb06-4319-ace0-42a6333593ef', 'What is a digit worth?', 'Find the value of each digit up to thousands.', 'I can say the value of any digit in a 4-digit number.', 2, 6, 2, true, '{"my":{"title":"ဂဏန်းတစ်လုံးက ဘယ်လောက် တန်လဲ","description":"ထောင်အထိ ဂဏန်းတစ်လုံးစီရဲ့ တန်ဖိုးကို ရှာပါ။","learning_objective":"ဂဏန်း 4 လုံးပါ ကိန်းထဲက ဘယ်ဂဏန်းရဲ့ တန်ဖိုးကိုမဆို ပြောနိုင်တယ်။"},"th":{"title":"เลขโดดมีค่าเท่าไร","description":"หาค่าของเลขโดดแต่ละตัวจนถึงหลักพัน","learning_objective":"ฉันบอกค่าของเลขโดดใดก็ได้ในจำนวนสี่หลัก"}}'::jsonb),
  ('dbdef370-8ba4-4321-9569-a27ae1e28923', '36807931-54be-4146-983f-dbc3c861e1a8', 'f9f21cc0-fb06-4319-ace0-42a6333593ef', 'Rounding', 'Round to the nearest 10 and 100.', 'I can round numbers to the nearest 10 or 100.', 3, 7, 3, true, '{"my":{"title":"ခန့်မှန်းပြောင်းခြင်း","description":"အနီးစပ်ဆုံး 10 နဲ့ 100 ပြည့်ကိန်းသို့ ပြောင်းပါ။","learning_objective":"ဂဏန်းတွေကို အနီးစပ်ဆုံး 10 ဒါမှမဟုတ် 100 ပြည့်ကိန်းသို့ ပြောင်းနိုင်တယ်။"},"th":{"title":"การปัดเศษ","description":"ปัดเป็นจำนวนเต็มสิบและเต็มร้อยที่ใกล้ที่สุด","learning_objective":"ฉันปัดจำนวนเป็นจำนวนเต็มสิบหรือเต็มร้อยที่ใกล้ที่สุดได้"}}'::jsonb),
