  ('2c007681-ba89-4b7c-a776-b5c7776dd8ea', '4d356a8b-10ed-4102-8e65-25e50d1d2574', '9f308b1e-9bb2-48f9-acd4-e1d041806b83', 'Calculating with decimals', 'Add, subtract, and multiply or divide by 10 and 100.', 'I can add and subtract decimals and multiply or divide them by 10 and 100.', 3, 8, 3, true, '{"my":{"title":"ဒသမကိန်းဖြင့် တွက်ချက်ခြင်း","description":"ပေါင်း၊ နုတ်ပြီး 10 နဲ့ 100 ဖြင့် မြှောက်ခြင်း ဒါမှမဟုတ် စားခြင်း။","learning_objective":"ဒသမကိန်းတွေကို ပေါင်း၊ နုတ်ပြီး 10 နဲ့ 100 ဖြင့် မြှောက် ဒါမှမဟုတ် စား နိုင်တယ်။"},"th":{"title":"การคำนวณทศนิยม","description":"บวก ลบ และคูณหรือหารด้วย 10 และ 100","learning_objective":"ฉันบวกและลบทศนิยม และคูณหรือหารด้วย 10 และ 100 ได้"}}'::jsonb),
  ('b9edd62a-4e92-41ad-aac1-f5400c17ed3b', '4d356a8b-10ed-4102-8e65-25e50d1d2574', 'edb4ec1c-1a07-42b7-a3c7-2e2e57389ec1', 'What is a percentage?', 'Percent means "out of 100".', 'I can understand percentages as parts of 100.', 1, 6, 4, true, '{"my":{"title":"ရာခိုင်နှုန်းဆိုတာ ဘာလဲ","description":"ရာခိုင်နှုန်းဆိုတာ \"100 ထဲက\" ပါ။","learning_objective":"ရာခိုင်နှုန်းကို 100 ရဲ့ အစိတ်အပိုင်းအဖြစ် နားလည်တယ်။"},"th":{"title":"ร้อยละคืออะไร","description":"เปอร์เซ็นต์หมายถึง \"จาก 100\"","learning_objective":"ฉันเข้าใจร้อยละว่าเป็นส่วนของ 100"}}'::jsonb),
  ('498ca0eb-c600-4ae8-8c1f-e1a16a46adfe', '4d356a8b-10ed-4102-8e65-25e50d1d2574', 'edb4ec1c-1a07-42b7-a3c7-2e2e57389ec1', 'Percentages of amounts', 'Find 10%, 25%, 50% and more of a number.', 'I can find a percentage of an amount.', 2, 7, 5, true, '{"my":{"title":"ပမာဏ၏ ရာခိုင်နှုန်း","description":"ဂဏန်းတစ်ခုရဲ့ 10%၊ 25%၊ 50% နဲ့ အခြားဟာတွေကို ရှာပါ။","learning_objective":"ပမာဏတစ်ခုရဲ့ ရာခိုင်နှုန်းကို ရှာနိုင်တယ်။"},"th":{"title":"ร้อยละของจำนวน","description":"หา 10%, 25%, 50% และอื่น ๆ ของจำนวน","learning_objective":"ฉันหาร้อยละของจำนวนได้"}}'::jsonb),
  ('014c4da5-d493-4074-96de-b39782b99fd6', '4d356a8b-10ed-4102-8e65-25e50d1d2574', 'edb4ec1c-1a07-42b7-a3c7-2e2e57389ec1', 'Ratios', 'Simplify ratios and share in a ratio.', 'I can simplify a ratio and share an amount in a given ratio.', 3, 8, 6, true, '{"my":{"title":"အချိုးများ","description":"အချိုးတွေကို ရိုးရှင်းအောင်လုပ်ပြီး အချိုးအလိုက် ခွဲဝေပါ။","learning_objective":"အချိုးကို ရိုးရှင်းအောင် လုပ်ပြီး ပေးထားတဲ့ အချိုးအတိုင်း ပမာဏကို ခွဲဝေနိုင်တယ်။"},"th":{"title":"อัตราส่วน","description":"ทำอัตราส่วนให้เป็นอย่างต่ำและแบ่งตามอัตราส่วน","learning_objective":"ฉันทำอัตราส่วนให้เป็นอย่างต่ำและแบ่งจำนวนตามอัตราส่วนที่กำหนดได้"}}'::jsonb),
  ('e922268c-0682-478b-9d81-68ae70200c8d', '349cfa46-3361-41b9-9363-d55811932af3', '27e47ed0-dcb8-4f5f-9708-354eab2063cd', 'Below zero', 'Place and compare negative numbers.', 'I can order and compare negative numbers.', 1, 6, 1, true, '{"my":{"title":"သုညအောက်","description":"အနုတ်ကိန်းတွေကို နေရာချပြီး နှိုင်းယှဉ်ပါ။","learning_objective":"အနုတ်ကိန်းတွေကို စီပြီး နှိုင်းယှဉ်နိုင်တယ်။"},"th":{"title":"ต่ำกว่าศูนย์","description":"วางตำแหน่งและเปรียบเทียบจำนวนลบ","learning_objective":"ฉันเรียงลำดับและเปรียบเทียบจำนวนลบได้"}}'::jsonb),
  ('c7b1bd5e-f206-4953-afd2-8a840eb9c009', '349cfa46-3361-41b9-9363-d55811932af3', '27e47ed0-dcb8-4f5f-9708-354eab2063cd', 'Adding and subtracting negatives', 'Move along the number line across zero.', 'I can add and subtract with negative numbers.', 2, 8, 2, true, '{"my":{"title":"အနုတ်ကိန်း ပေါင်းခြင်းနှင့် နုတ်ခြင်း","description":"သုညကို ဖြတ်ပြီး ကိန်းမျဉ်းတစ်လျှောက် ရွှေ့ပါ။","learning_objective":"အနုတ်ကိန်းတွေနဲ့ ပေါင်းနိုင်၊ နုတ်နိုင်တယ်။"},"th":{"title":"การบวกและลบจำนวนลบ","description":"เลื่อนไปตามเส้นจำนวนข้ามศูนย์","learning_objective":"ฉันบวกและลบจำนวนลบได้"}}'::jsonb),
  ('684bf745-e1dd-47ae-9dd8-a6f712cb4d48', '349cfa46-3361-41b9-9363-d55811932af3', '27e47ed0-dcb8-4f5f-9708-354eab2063cd', 'Temperature problems', 'Solve real problems with temperatures below zero.', 'I can solve word problems involving negative numbers.', 3, 8, 3, true, '{"my":{"title":"အပူချိန် ပုစ္ဆာများ","description":"သုညအောက် အပူချိန်တွေနဲ့ လက်တွေ့ ပုစ္ဆာတွေကို ဖြေရှင်းပါ။","learning_objective":"အနုတ်ကိန်းပါတဲ့ ပုစ္ဆာတွေကို ဖြေရှင်းနိုင်တယ်။"},"th":{"title":"โจทย์อุณหภูมิ","description":"แก้ปัญหาจริงเกี่ยวกับอุณหภูมิที่ต่ำกว่าศูนย์","learning_objective":"ฉันแก้โจทย์ปัญหาที่มีจำนวนลบได้"}}'::jsonb),
  ('f60ed9e4-4a14-412f-861e-d27eb1b3f6a9', '95b4708c-510b-4e73-8517-245e834662dd', '7bc79dc7-9fea-4524-a7ad-34c5ae012802', 'Perimeter', 'Find the distance around rectangles and squares.', 'I can calculate the perimeter of rectangles and squares.', 1, 6, 1, true, '{"my":{"title":"ပတ်လည်အနား","description":"ထောင့်မှန်စတုဂံနဲ့ စတုရန်းတွေကို ပတ်တဲ့ အကွာအဝေးကို ရှာပါ။","learning_objective":"ထောင့်မှန်စတုဂံနဲ့ စတုရန်းတွေရဲ့ ပတ်လည်အနားကို တွက်နိုင်တယ်။"},"th":{"title":"ความยาวรอบรูป","description":"หาระยะรอบสี่เหลี่ยมผืนผ้าและสี่เหลี่ยมจัตุรัส","learning_objective":"ฉันคำนวณความยาวรอบรูปของสี่เหลี่ยมผืนผ้าและสี่เหลี่ยมจัตุรัสได้"}}'::jsonb),
  ('111e6d59-4819-412a-8d07-1f638046fd2c', '95b4708c-510b-4e73-8517-245e834662dd', '7bc79dc7-9fea-4524-a7ad-34c5ae012802', 'Area of rectangles', 'Count squares, then multiply length by width.', 'I can calculate the area of a rectangle.', 2, 7, 2, true, '{"my":{"title":"ထောင့်မှန်စတုဂံ၏ ဧရိယာ","description":"အကွက်တွေကို ရေပြီး အလျားကို အနံနဲ့ မြှောက်ပါ။","learning_objective":"ထောင့်မှန်စတုဂံရဲ့ ဧရိယာကို တွက်နိုင်တယ်။"},"th":{"title":"พื้นที่สี่เหลี่ยมผืนผ้า","description":"นับช่องสี่เหลี่ยม แล้วคูณความยาวกับความกว้าง","learning_objective":"ฉันคำนวณพื้นที่ของสี่เหลี่ยมผืนผ้าได้"}}'::jsonb),
  ('8744379c-ed0a-436d-bfb0-dfce89ad5c57', '95b4708c-510b-4e73-8517-245e834662dd', '7bc79dc7-9fea-4524-a7ad-34c5ae012802', 'Area of triangles', 'A triangle is half a rectangle.', 'I can calculate the area of a triangle.', 3, 8, 3, true, '{"my":{"title":"တြိဂံ၏ ဧရိယာ","description":"တြိဂံက ထောင့်မှန်စတုဂံရဲ့ တစ်ဝက်ပါ။","learning_objective":"တြိဂံရဲ့ ဧရိယာကို တွက်နိုင်တယ်။"},"th":{"title":"พื้นที่สามเหลี่ยม","description":"สามเหลี่ยมคือครึ่งหนึ่งของสี่เหลี่ยมผืนผ้า","learning_objective":"ฉันคำนวณพื้นที่ของสามเหลี่ยมได้"}}'::jsonb),
  ('327c2d58-9405-4fbf-aada-190aa131e319', '349cfa46-3361-41b9-9363-d55811932af3', '43bb5e40-227c-4861-9891-3fa243f34733', 'Letters for numbers', 'Substitute values into expressions.', 'I can work out the value of an expression when I know the letter.', 1, 7, 4, true, '{"my":{"title":"ဂဏန်းအစား အက္ခရာများ","description":"ကိန်းတန်းတွေထဲ တန်ဖိုးတွေ အစားထိုးပါ။","learning_objective":"အက္ခရာရဲ့ တန်ဖိုး သိရင် ကိန်းတန်းရဲ့ တန်ဖိုးကို တွက်နိုင်တယ်။"},"th":{"title":"ตัวอักษรแทนจำนวน","description":"แทนค่าลงในนิพจน์","learning_objective":"ฉันหาค่าของนิพจน์ได้เมื่อรู้ค่าของตัวอักษร"}}'::jsonb),
  ('ee175789-43e1-4c82-918a-4b0346c8d77c', '349cfa46-3361-41b9-9363-d55811932af3', '43bb5e40-227c-4861-9891-3fa243f34733', 'Solving equations', 'Find the unknown by doing the opposite operation.', 'I can solve one-step and two-step equations.', 2, 8, 5, true, '{"my":{"title":"ညီမျှခြင်း ဖြေရှင်းခြင်း","description":"ဆန့်ကျင်ဘက် တွက်နည်းကို လုပ်ပြီး မသိကိန်းကို ရှာပါ။","learning_objective":"တစ်ဆင့်နဲ့ နှစ်ဆင့် ညီမျှခြင်းတွေကို ဖြေရှင်းနိုင်တယ်။"},"th":{"title":"การแก้สมการ","description":"หาตัวที่ไม่รู้ค่าโดยใช้การดำเนินการตรงข้าม","learning_objective":"ฉันแก้สมการขั้นตอนเดียวและสองขั้นตอนได้"}}'::jsonb),
  ('a71c0567-02dd-4d66-8368-3db11a369328', '349cfa46-3361-41b9-9363-d55811932af3', '43bb5e40-227c-4861-9891-3fa243f34733', 'Multi-step problems', 'Break bigger problems into steps.', 'I can solve word problems that need more than one step.', 3, 9, 6, true, '{"my":{"title":"အဆင့်များစွာပါ ပုစ္ဆာများ","description":"ကြီးတဲ့ ပုစ္ဆာတွေကို အဆင့်တွေအဖြစ် ခွဲပါ။","learning_objective":"အဆင့် တစ်ဆင့်ထက်ပို လိုတဲ့ ပုစ္ဆာတွေကို ဖြေရှင်းနိုင်တယ်။"},"th":{"title":"โจทย์หลายขั้นตอน","description":"แบ่งโจทย์ใหญ่เป็นขั้นตอน","learning_objective":"ฉันแก้โจทย์ปัญหาที่ต้องใช้มากกว่าหนึ่งขั้นตอนได้"}}'::jsonb)
insert into public.lesson_sections (id, lesson_id, section_type, title, content_json, display_order, translations) values
  ('3284c3ef-da35-43b6-9b9a-50ed5aba685c', 'dc34b71a-d6e5-4a61-9ecb-9ec077dc9567', 'introduction', 'Let''s learn', '{"kind":"introduction","text":"Counting tells us how many. Touch each thing once and say one number for it.","visual":{"kind":"objects","object":"apple","groups":[5]}}'::jsonb, 1, '{"my":{"title":"သင်ယူကြစို့","content":{"kind":"introduction","text":"ရေတွက်ခြင်းက ဘယ်နှခု ရှိလဲ ပြောပြတယ်။ အရာတစ်ခုကို တစ်ကြိမ်ထိပြီး ဂဏန်းတစ်ခု ပြောပါ။","visual":{"kind":"objects","object":"apple","groups":[5]}}},"th":{"title":"มาเรียนกัน","content":{"kind":"introduction","text":"การนับบอกเราว่ามีเท่าไร แตะแต่ละชิ้นครั้งเดียวและพูดตัวเลขหนึ่งตัว","visual":{"kind":"objects","object":"apple","groups":[5]}}}}'::jsonb),
  ('3184c25c-db35-4549-9a9a-4f5a5bba69ef', 'dc34b71a-d6e5-4a61-9ecb-9ec077dc9567', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"How many stars are there?","steps":["Point to the first star and say 1.","Keep going: 2, 3, 4.","The last number you say is how many: 4 stars."],"visual":{"kind":"objects","object":"star","groups":[4]}}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"ကြယ် ဘယ်နှပွင့် ရှိလဲ။","steps":["ပထမကြယ်ကို ထိုးပြပြီး 1 လို့ ပြောပါ။","ဆက်ရေပါ - 2၊ 3၊ 4။","နောက်ဆုံးပြောတဲ့ ဂဏန်းက အရေအတွက်ပါ - ကြယ် 4 ပွင့်။"],"visual":{"kind":"objects","object":"star","groups":[4]}}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"มีดาวกี่ดวง","steps":["ชี้ดาวดวงแรกแล้วพูดว่า 1","นับต่อ: 2, 3, 4","ตัวเลขสุดท้ายที่พูดคือจำนวนทั้งหมด: ดาว 4 ดวง"],"visual":{"kind":"objects","object":"star","groups":[4]}}}}'::jsonb),
  ('3484c715-d835-4090-999a-4dc75cba6b82', 'dc34b71a-d6e5-4a61-9ecb-9ec077dc9567', 'practice', 'Your turn', '{"kind":"practice","text":"Try 5 questions. You get two tries at each one."}'::jsonb, 3, '{"my":{"title":"သင့်အလှည့်","content":{"kind":"practice","text":"မေးခွန်း 5 ခု ဖြေကြည့်ပါ။ တစ်ခုစီကို နှစ်ကြိမ် ဖြေနိုင်တယ်။"}},"th":{"title":"ถึงตาเธอแล้ว","content":{"kind":"practice","text":"ลองทำ 5 ข้อ แต่ละข้อตอบได้สองครั้ง"}}}'::jsonb),
  ('3384c582-d935-4223-989a-4c345dba6d15', 'dc34b71a-d6e5-4a61-9ecb-9ec077dc9567', 'summary', 'Remember', '{"kind":"summary","points":["Count each thing once.","The last number you say tells you how many."]}'::jsonb, 4, '{"my":{"title":"မှတ်ထားပါ","content":{"kind":"summary","points":["အရာတစ်ခုကို တစ်ကြိမ်သာ ရေပါ။","နောက်ဆုံးပြောတဲ့ ဂဏန်းက ဘယ်နှခု ရှိလဲ ပြောပြတယ်။"]}},"th":{"title":"จำไว้นะ","content":{"kind":"summary","points":["นับแต่ละชิ้นครั้งเดียว","ตัวเลขสุดท้ายที่พูดบอกว่ามีเท่าไร"]}}}'::jsonb),
  ('2b1c51b5-68de-49ec-9f0e-0f937dbafc22', '6466b95c-5236-41fb-96f6-ee8a086d78a9', 'introduction', 'Let''s learn', '{"kind":"introduction","text":"Numbers from 11 to 19 are 1 ten and some ones. 20 is 2 tens.","visual":{"kind":"objects","object":"block","groups":[10,3]}}'::jsonb, 1, '{"my":{"title":"သင်ယူကြစို့","content":{"kind":"introduction","text":"11 မှ 19 အထိ ဂဏန်းတွေက ဆယ် 1 ခုနဲ့ ခု အချို့ ဖြစ်တယ်။ 20 က ဆယ် 2 ခုပါ။","visual":{"kind":"objects","object":"block","groups":[10,3]}}},"th":{"title":"มาเรียนกัน","content":{"kind":"introduction","text":"จำนวน 11 ถึง 19 คือ 1 สิบกับหน่วยอีกจำนวนหนึ่ง 20 คือ 2 สิบ","visual":{"kind":"objects","object":"block","groups":[10,3]}}}}'::jsonb),
  ('2a1c5022-69de-4b7f-9e0e-0e007ebafdb5', '6466b95c-5236-41fb-96f6-ee8a086d78a9', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"What number is 1 ten and 4 ones?","steps":["1 ten is 10.","4 ones is 4.","10 and 4 make 14."],"visual":{"kind":"objects","object":"block","groups":[10,4]}}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"ဆယ် 1 ခုနဲ့ ခု 4 ခုက ဘယ်ဂဏန်းလဲ။","steps":["ဆယ် 1 ခုက 10 ပါ။","ခု 4 ခုက 4 ပါ။","10 နဲ့ 4 ပေါင်းရင် 14 ဖြစ်တယ်။"],"visual":{"kind":"objects","object":"block","groups":[10,4]}}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"1 สิบ กับ 4 หน่วย คือจำนวนใด","steps":["1 สิบคือ 10","4 หน่วยคือ 4","10 กับ 4 รวมเป็น 14"],"visual":{"kind":"objects","object":"block","groups":[10,4]}}}}'::jsonb),
