  ('3ce78124-e846-4441-990e-29468403395b', 'c48ad5f6-a514-4bf9-a5af-92787ce41a43', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"Put 12, 8 and 15 in order.","steps":["8 has no tens, so it is the smallest.","12 and 15 both have 1 ten. 2 ones is less than 5 ones.","In order: 8, 12, 15."]}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"12၊ 8 နဲ့ 15 ကို အစဉ်လိုက် စီပါ။","steps":["8 မှာ ဆယ် မရှိလို့ အငယ်ဆုံးပါ။","12 နဲ့ 15 နှစ်ခုလုံးမှာ ဆယ် 1 ခု ရှိတယ်။ ခု 2 ခုက ခု 5 ခုထက် ငယ်တယ်။","အစဉ်လိုက် - 8၊ 12၊ 15။"]}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"เรียง 12, 8 และ 15 ตามลำดับ","steps":["8 ไม่มีหลักสิบ จึงน้อยที่สุด","12 และ 15 มี 1 สิบเหมือนกัน 2 หน่วยน้อยกว่า 5 หน่วย","เรียงลำดับได้: 8, 12, 15"]}}}'::jsonb),
