  ('94f540cc-10a1-4ca5-b6fc-bbf6cc4c23f7', '7a740449-3406-49aa-ad95-056bbbd042b4', 'introduction', 'Let''s learn', '{"kind":"introduction","text":"The same digit can be worth different amounts. It depends on its place."}'::jsonb, 1, '{"my":{"title":"သင်ယူကြစို့","content":{"kind":"introduction","text":"တူညီတဲ့ ဂဏန်းတစ်လုံးက တန်ဖိုး မတူနိုင်တယ်။ သူ့နေရာပေါ် မူတည်တယ်။"}},"th":{"title":"มาเรียนกัน","content":{"kind":"introduction","text":"เลขโดดตัวเดียวกันอาจมีค่าต่างกัน ขึ้นอยู่กับหลักที่อยู่"}}}'::jsonb),
  ('95f5425f-0fa1-4b12-b7fc-bd89cb4c2264', '7a740449-3406-49aa-ad95-056bbbd042b4', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"What is the 5 worth in 2,538?","steps":["Name the places from the right: ones, tens, hundreds, thousands.","The 5 is in the hundreds place.","So it is worth 500."]}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"2,538 ထဲက 5 က ဘယ်လောက် တန်လဲ။","steps":["ညာဘက်ကနေ နေရာတွေကို အမည်ပေးပါ - ခု၊ ဆယ်၊ ရာ၊ ထောင်။","5 က ရာလီ နေရာမှာ ရှိတယ်။","ဒါကြောင့် 500 တန်တယ်။"]}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"เลข 5 ใน 2,538 มีค่าเท่าไร","steps":["เรียกชื่อหลักจากขวา: หน่วย สิบ ร้อย พัน","เลข 5 อยู่ในหลักร้อย","จึงมีค่า 500"]}}}'::jsonb),
  ('96f543f2-0ea1-497f-b4fc-b8d0ce4c271d', '7a740449-3406-49aa-ad95-056bbbd042b4', 'practice', 'Your turn', '{"kind":"practice","text":"Try 5 questions. You get two tries at each one."}'::jsonb, 3, '{"my":{"title":"သင့်အလှည့်","content":{"kind":"practice","text":"မေးခွန်း 5 ခု ဖြေကြည့်ပါ။ တစ်ခုစီကို နှစ်ကြိမ် ဖြေနိုင်တယ်။"}},"th":{"title":"ถึงตาเธอแล้ว","content":{"kind":"practice","text":"ลองทำ 5 ข้อ แต่ละข้อตอบได้สองครั้ง"}}}'::jsonb),
  ('97f54585-0da1-47ec-b5fc-ba63cd4c258a', '7a740449-3406-49aa-ad95-056bbbd042b4', 'summary', 'Remember', '{"kind":"summary","points":["Ones, tens, hundreds, thousands — from the right.","Each place is 10 times bigger than the one to its right."]}'::jsonb, 4, '{"my":{"title":"မှတ်ထားပါ","content":{"kind":"summary","points":["ညာဘက်ကနေ - ခု၊ ဆယ်၊ ရာ၊ ထောင်။","နေရာတစ်ခုစီက သူ့ညာဘက် နေရာထက် 10 ဆ ကြီးတယ်။"]}},"th":{"title":"จำไว้นะ","content":{"kind":"summary","points":["หน่วย สิบ ร้อย พัน จากขวา","แต่ละหลักมีค่าเป็น 10 เท่าของหลักทางขวา"]}}}'::jsonb),
  ('28082f47-6c96-4924-ba36-18894f97483e', 'dbdef370-8ba4-4321-9569-a27ae1e28923', 'introduction', 'Let''s learn', '{"kind":"introduction","text":"Rounding finds the nearest \"friendly\" number. Halfway or more rounds up.","visual":{"kind":"number_line","min":40,"max":50,"step":1,"highlight":[47]}}'::jsonb, 1, '{"my":{"title":"သင်ယူကြစို့","content":{"kind":"introduction","text":"ခန့်မှန်းပြောင်းခြင်းက အနီးဆုံး \"လွယ်ကူတဲ့\" ဂဏန်းကို ရှာတယ်။ တစ်ဝက် ဒါမှမဟုတ် ပိုရင် အပေါ်ကို ပြောင်းပါ။","visual":{"kind":"number_line","min":40,"max":50,"step":1,"highlight":[47]}}},"th":{"title":"มาเรียนกัน","content":{"kind":"introduction","text":"การปัดเศษคือการหาจำนวนที่ \"ง่าย\" ที่ใกล้ที่สุด ครึ่งหนึ่งขึ้นไปให้ปัดขึ้น","visual":{"kind":"number_line","min":40,"max":50,"step":1,"highlight":[47]}}}}'::jsonb),
  ('27082db4-6d96-4ab7-b936-16f6509749d1', 'dbdef370-8ba4-4321-9569-a27ae1e28923', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"Round 47 to the nearest 10.","steps":["47 is between 40 and 50.","The ones digit is 7, which is 5 or more.","So 47 rounds up to 50."],"visual":{"kind":"number_line","min":40,"max":50,"step":1,"highlight":[47]}}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"47 ကို အနီးစပ်ဆုံး 10 ပြည့်ကိန်းသို့ ပြောင်းပါ။","steps":["47 က 40 နဲ့ 50 ကြားမှာ ရှိတယ်။","ခုလီ ဂဏန်းက 7 ဖြစ်ပြီး 5 နဲ့ အထက်ပါ။","ဒါကြောင့် 47 က 50 သို့ အပေါ်ကို ပြောင်းတယ်။"],"visual":{"kind":"number_line","min":40,"max":50,"step":1,"highlight":[47]}}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"ปัด 47 เป็นจำนวนเต็มสิบที่ใกล้ที่สุด","steps":["47 อยู่ระหว่าง 40 กับ 50","เลขหลักหน่วยคือ 7 ซึ่งมากกว่าหรือเท่ากับ 5","ดังนั้น 47 ปัดขึ้นเป็น 50"],"visual":{"kind":"number_line","min":40,"max":50,"step":1,"highlight":[47]}}}}'::jsonb),
  ('2a08326d-6e96-4c4a-b836-15634d974518', 'dbdef370-8ba4-4321-9569-a27ae1e28923', 'practice', 'Your turn', '{"kind":"practice","text":"Try 5 questions. You get two tries at each one."}'::jsonb, 3, '{"my":{"title":"သင့်အလှည့်","content":{"kind":"practice","text":"မေးခွန်း 5 ခု ဖြေကြည့်ပါ။ တစ်ခုစီကို နှစ်ကြိမ် ဖြေနိုင်တယ်။"}},"th":{"title":"ถึงตาเธอแล้ว","content":{"kind":"practice","text":"ลองทำ 5 ข้อ แต่ละข้อตอบได้สองครั้ง"}}}'::jsonb),
  ('290830da-6f96-4ddd-b736-13d04e9746ab', 'dbdef370-8ba4-4321-9569-a27ae1e28923', 'summary', 'Remember', '{"kind":"summary","points":["5 or more: round up.","Less than 5: round down."]}'::jsonb, 4, '{"my":{"title":"မှတ်ထားပါ","content":{"kind":"summary","points":["5 နဲ့ အထက် - အပေါ်ကို ပြောင်းပါ။","5 ထက်ငယ်ရင် - အောက်ကို ပြောင်းပါ။"]}},"th":{"title":"จำไว้นะ","content":{"kind":"summary","points":["5 ขึ้นไป: ปัดขึ้น","น้อยกว่า 5: ปัดลง"]}}}'::jsonb),
  ('0774f2b5-f024-481a-a073-f437f71f56f4', 'ca0a26ea-52fd-4fc3-9d54-ef6cce146a1d', 'introduction', 'Let''s learn', '{"kind":"introduction","text":"Multiplying is adding equal groups quickly. An array shows equal rows.","visual":{"kind":"array","rows":3,"cols":4,"object":"star"}}'::jsonb, 1, '{"my":{"title":"သင်ယူကြစို့","content":{"kind":"introduction","text":"မြှောက်ခြင်းက အုပ်စုညီတွေကို မြန်မြန် ပေါင်းခြင်းပါ။ အတန်းအစီက ညီတဲ့ အတန်းတွေကို ပြတယ်။","visual":{"kind":"array","rows":3,"cols":4,"object":"star"}}},"th":{"title":"มาเรียนกัน","content":{"kind":"introduction","text":"การคูณคือการบวกกลุ่มที่เท่ากันอย่างรวดเร็ว แถวลำดับแสดงแถวที่เท่ากัน","visual":{"kind":"array","rows":3,"cols":4,"object":"star"}}}}'::jsonb),
  ('0674f122-f124-49ad-9f73-f2a4f81f5887', 'ca0a26ea-52fd-4fc3-9d54-ef6cce146a1d', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"How many stars in 3 rows of 4?","steps":["There are 3 rows with 4 in each.","Count in 4s: 4, 8, 12.","So 3 × 4 = 12."],"visual":{"kind":"array","rows":3,"cols":4,"object":"star"}}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"4 ပွင့်စီပါတဲ့ အတန်း 3 တန်းမှာ ကြယ် ဘယ်နှပွင့် ရှိလဲ။","steps":["အတန်း 3 တန်း ရှိပြီး တစ်တန်းစီမှာ 4 ပွင့် ရှိတယ်။","4 စီ ရေပါ - 4၊ 8၊ 12။","ဒါကြောင့် 3 × 4 = 12။"],"visual":{"kind":"array","rows":3,"cols":4,"object":"star"}}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"ดาว 3 แถว แถวละ 4 ดวง มีกี่ดวง","steps":["มี 3 แถว แถวละ 4","นับทีละ 4: 4, 8, 12","ดังนั้น 3 × 4 = 12"],"visual":{"kind":"array","rows":3,"cols":4,"object":"star"}}}}'::jsonb),
  ('0574ef8f-ee24-44f4-a273-f75df91f5a1a', 'ca0a26ea-52fd-4fc3-9d54-ef6cce146a1d', 'practice', 'Your turn', '{"kind":"practice","text":"Try 5 questions. You get two tries at each one."}'::jsonb, 3, '{"my":{"title":"သင့်အလှည့်","content":{"kind":"practice","text":"မေးခွန်း 5 ခု ဖြေကြည့်ပါ။ တစ်ခုစီကို နှစ်ကြိမ် ဖြေနိုင်တယ်။"}},"th":{"title":"ถึงตาเธอแล้ว","content":{"kind":"practice","text":"ลองทำ 5 ข้อ แต่ละข้อตอบได้สองครั้ง"}}}'::jsonb),
  ('0474edfc-ef24-4687-a173-f5cafa1f5bad', 'ca0a26ea-52fd-4fc3-9d54-ef6cce146a1d', 'summary', 'Remember', '{"kind":"summary","points":["× means groups of.","Rows × columns gives the total."]}'::jsonb, 4, '{"my":{"title":"မှတ်ထားပါ","content":{"kind":"summary","points":["× ဆိုတာ \"အုပ်စု ... စု\"။","အတန်း × ကော်လံ က စုစုပေါင်းကို ပေးတယ်။"]}},"th":{"title":"จำไว้นะ","content":{"kind":"summary","points":["× หมายถึงจำนวนกลุ่ม","แถว × หลัก ได้จำนวนทั้งหมด"]}}}'::jsonb),
  ('79ed5917-c36b-4fa4-9a2e-4339139a4916', 'f38d59d0-1246-4c79-ac8c-e042171c4c93', 'introduction', 'Let''s learn', '{"kind":"introduction","text":"Knowing your times tables makes bigger maths faster. Use facts you know to work out ones you do not."}'::jsonb, 1, '{"my":{"title":"သင်ယူကြစို့","content":{"kind":"introduction","text":"အမြှောက်ဇယား သိရင် ပိုကြီးတဲ့ သင်္ချာတွေကို မြန်မြန် တွက်နိုင်တယ်။ မသိတာကို တွက်ဖို့ သိပြီးသား အချက်တွေကို သုံးပါ။"}},"th":{"title":"มาเรียนกัน","content":{"kind":"introduction","text":"การรู้สูตรคูณทำให้คิดเลขที่ใหญ่ขึ้นได้เร็วขึ้น ใช้สูตรที่รู้แล้วช่วยหาสูตรที่ยังไม่รู้"}}}'::jsonb),
  ('78ed5784-c46b-4137-992e-41a6149a4aa9', 'f38d59d0-1246-4c79-ac8c-e042171c4c93', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"What is 7 × 6?","steps":["Split 7 into 5 and 2.","5 × 6 = 30 and 2 × 6 = 12.","30 + 12 = 42, so 7 × 6 = 42."]}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"7 × 6 က ဘယ်လောက်လဲ။","steps":["7 ကို 5 နဲ့ 2 အဖြစ် ခွဲပါ။","5 × 6 = 30 နဲ့ 2 × 6 = 12။","30 + 12 = 42၊ ဒါကြောင့် 7 × 6 = 42။"]}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"7 × 6 เท่ากับเท่าไร","steps":["แยก 7 เป็น 5 กับ 2","5 × 6 = 30 และ 2 × 6 = 12","30 + 12 = 42 ดังนั้น 7 × 6 = 42"]}}}'::jsonb),
  ('7bed5c3d-c56b-42ca-982e-4013119a45f0', 'f38d59d0-1246-4c79-ac8c-e042171c4c93', 'practice', 'Your turn', '{"kind":"practice","text":"Try 5 questions. You get two tries at each one."}'::jsonb, 3, '{"my":{"title":"သင့်အလှည့်","content":{"kind":"practice","text":"မေးခွန်း 5 ခု ဖြေကြည့်ပါ။ တစ်ခုစီကို နှစ်ကြိမ် ဖြေနိုင်တယ်။"}},"th":{"title":"ถึงตาเธอแล้ว","content":{"kind":"practice","text":"ลองทำ 5 ข้อ แต่ละข้อตอบได้สองครั้ง"}}}'::jsonb),
  ('7aed5aaa-c66b-445d-972e-3e80129a4783', 'f38d59d0-1246-4c79-ac8c-e042171c4c93', 'summary', 'Remember', '{"kind":"summary","points":["Split hard facts into easier ones.","a × b is the same as b × a."]}'::jsonb, 4, '{"my":{"title":"မှတ်ထားပါ","content":{"kind":"summary","points":["ခက်တဲ့ အချက်တွေကို ပိုလွယ်တာတွေအဖြစ် ခွဲပါ။","a × b က b × a နဲ့ အတူတူပါ။"]}},"th":{"title":"จำไว้นะ","content":{"kind":"summary","points":["แยกสูตรยากเป็นสูตรที่ง่ายกว่า","a × b เท่ากับ b × a"]}}}'::jsonb),
  ('0c6a83ad-4cc0-4d62-91ff-52d7a7a5ca14', 'bc10714a-1f18-451b-9df2-26e4643fb37d', 'introduction', 'Let''s learn', '{"kind":"introduction","text":"When a story has equal groups, you can multiply."}'::jsonb, 1, '{"my":{"title":"သင်ယူကြစို့","content":{"kind":"introduction","text":"ပုံပြင်မှာ အုပ်စုညီတွေ ရှိရင် မြှောက်လို့ ရတယ်။"}},"th":{"title":"มาเรียนกัน","content":{"kind":"introduction","text":"เมื่อเรื่องราวมีกลุ่มที่เท่ากัน เราใช้การคูณได้"}}}'::jsonb),
  ('0b6a821a-4dc0-4ef5-90ff-5144a8a5cba7', 'bc10714a-1f18-451b-9df2-26e4643fb37d', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"There are 4 bags with 6 oranges in each. How many oranges?","steps":["4 equal groups of 6.","4 × 6 = 24.","There are 24 oranges."]}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"လိမ္မော်သီး 6 လုံးစီပါတဲ့ အိတ် 4 လုံး ရှိတယ်။ လိမ္မော်သီး ဘယ်နှလုံး ရှိလဲ။","steps":["6 စီပါတဲ့ အုပ်စုညီ 4 စု။","4 × 6 = 24။","လိမ္မော်သီး 24 လုံး ရှိတယ်။"]}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"มีส้ม 4 ถุง ถุงละ 6 ผล มีส้มกี่ผล","steps":["4 กลุ่มเท่า ๆ กัน กลุ่มละ 6","4 × 6 = 24","มีส้ม 24 ผล"]}}}'::jsonb),
