  ('096a7ef4-4bc0-4bcf-92ff-546aaaa5cecd', 'bc10714a-1f18-451b-9df2-26e4643fb37d', 'summary', 'Remember', '{"kind":"summary","points":["Look for \"each\" or \"every\" — they often mean equal groups.","Number of groups × size of each group."]}'::jsonb, 4, '{"my":{"title":"မှတ်ထားပါ","content":{"kind":"summary","points":["\"တစ်ခုစီ\" ဒါမှမဟုတ် \"တိုင်း\" ကို ရှာပါ - အုပ်စုညီလို့ အဓိပ္ပာယ်ရလေ့ရှိတယ်။","အုပ်စု အရေအတွက် × အုပ်စုတစ်ခုရဲ့ အရွယ်။"]}},"th":{"title":"จำไว้นะ","content":{"kind":"summary","points":["มองหาคำว่า \"ละ\" หรือ \"ทุก\" ซึ่งมักหมายถึงกลุ่มที่เท่ากัน","จำนวนกลุ่ม × ขนาดของแต่ละกลุ่ม"]}}}'::jsonb),
  ('1407f419-ec2e-4850-80fd-1f7b86eb93f2', '8bc01bec-fd00-45af-bc00-45ce640f51a1', 'introduction', 'Let''s learn', '{"kind":"introduction","text":"Dividing means sharing equally. Everyone gets the same amount.","visual":{"kind":"objects","object":"cookie","groups":[12]}}'::jsonb, 1, '{"my":{"title":"သင်ယူကြစို့","content":{"kind":"introduction","text":"စားခြင်းဆိုတာ ညီညီမျှမျှ ခွဲဝေခြင်းပါ။ လူတိုင်း အရေအတွက် တူတူ ရတယ်။","visual":{"kind":"objects","object":"cookie","groups":[12]}}},"th":{"title":"มาเรียนกัน","content":{"kind":"introduction","text":"การหารคือการแบ่งเท่า ๆ กัน ทุกคนได้จำนวนเท่ากัน","visual":{"kind":"objects","object":"cookie","groups":[12]}}}}'::jsonb),
  ('1307f286-ed2e-49e3-bffd-1de887eb9585', '8bc01bec-fd00-45af-bc00-45ce640f51a1', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"Share 12 cookies between 3 friends.","steps":["Give one to each friend, again and again.","Each friend ends up with 4.","12 ÷ 3 = 4."],"visual":{"kind":"objects","object":"cookie","groups":[12]}}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"ကွတ်ကီး 12 ခုကို သူငယ်ချင်း 3 ယောက်ကြား ခွဲဝေပါ။","steps":["သူငယ်ချင်း တစ်ယောက်ကို တစ်ခုစီ ထပ်ခါထပ်ခါ ပေးပါ။","သူငယ်ချင်း တစ်ယောက်စီ 4 ခု ရတယ်။","12 ÷ 3 = 4။"],"visual":{"kind":"objects","object":"cookie","groups":[12]}}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"แบ่งคุกกี้ 12 ชิ้นให้เพื่อน 3 คน","steps":["แจกให้เพื่อนคนละชิ้นวนไปเรื่อย ๆ","เพื่อนแต่ละคนได้ 4 ชิ้น","12 ÷ 3 = 4"],"visual":{"kind":"objects","object":"cookie","groups":[12]}}}}'::jsonb),
  ('1207f0f3-ee2e-4b76-82fd-22a184eb90cc', '8bc01bec-fd00-45af-bc00-45ce640f51a1', 'practice', 'Your turn', '{"kind":"practice","text":"Try 5 questions. You get two tries at each one."}'::jsonb, 3, '{"my":{"title":"သင့်အလှည့်","content":{"kind":"practice","text":"မေးခွန်း 5 ခု ဖြေကြည့်ပါ။ တစ်ခုစီကို နှစ်ကြိမ် ဖြေနိုင်တယ်။"}},"th":{"title":"ถึงตาเธอแล้ว","content":{"kind":"practice","text":"ลองทำ 5 ข้อ แต่ละข้อตอบได้สองครั้ง"}}}'::jsonb),
  ('1107ef60-ef2e-4d09-81fd-210e85eb925f', '8bc01bec-fd00-45af-bc00-45ce640f51a1', 'summary', 'Remember', '{"kind":"summary","points":["÷ means share equally.","Check with multiplication: 3 × 4 = 12."]}'::jsonb, 4, '{"my":{"title":"မှတ်ထားပါ","content":{"kind":"summary","points":["÷ ဆိုတာ ညီညီမျှမျှ ခွဲဝေပါ။","မြှောက်ခြင်းနဲ့ စစ်ပါ - 3 × 4 = 12။"]}},"th":{"title":"จำไว้นะ","content":{"kind":"summary","points":["÷ หมายถึงแบ่งเท่า ๆ กัน","ตรวจด้วยการคูณ: 3 × 4 = 12"]}}}'::jsonb),
  ('47d9b53a-faec-4c75-b54c-dae4c56196df', 'ec33dba1-363b-4d64-8fde-59db59a9a286', 'introduction', 'Let''s learn', '{"kind":"introduction","text":"Division is the opposite of multiplication. If you know 6 × 4 = 24, you know 24 ÷ 6 = 4."}'::jsonb, 1, '{"my":{"title":"သင်ယူကြစို့","content":{"kind":"introduction","text":"စားခြင်းက မြှောက်ခြင်းရဲ့ ဆန့်ကျင်ဘက်ပါ။ 6 × 4 = 24 ကို သိရင် 24 ÷ 6 = 4 ကို သိတယ်။"}},"th":{"title":"มาเรียนกัน","content":{"kind":"introduction","text":"การหารเป็นสิ่งตรงข้ามกับการคูณ ถ้ารู้ว่า 6 × 4 = 24 ก็รู้ว่า 24 ÷ 6 = 4"}}}'::jsonb),
  ('48d9b6cd-f9ec-4ae2-b64c-dc77c461954c', 'ec33dba1-363b-4d64-8fde-59db59a9a286', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"What is 35 ÷ 5?","steps":["Think: 5 × what = 35?","5 × 7 = 35.","So 35 ÷ 5 = 7."]}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"35 ÷ 5 က ဘယ်လောက်လဲ။","steps":["စဉ်းစားပါ - 5 × ဘာ = 35။","5 × 7 = 35။","ဒါကြောင့် 35 ÷ 5 = 7။"]}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"35 ÷ 5 เท่ากับเท่าไร","steps":["คิดว่า: 5 × อะไร = 35","5 × 7 = 35","ดังนั้น 35 ÷ 5 = 7"]}}}'::jsonb),
  ('45d9b214-f8ec-494f-b74c-de0ac7619a05', 'ec33dba1-363b-4d64-8fde-59db59a9a286', 'practice', 'Your turn', '{"kind":"practice","text":"Try 5 questions. You get two tries at each one."}'::jsonb, 3, '{"my":{"title":"သင့်အလှည့်","content":{"kind":"practice","text":"မေးခွန်း 5 ခု ဖြေကြည့်ပါ။ တစ်ခုစီကို နှစ်ကြိမ် ဖြေနိုင်တယ်။"}},"th":{"title":"ถึงตาเธอแล้ว","content":{"kind":"practice","text":"ลองทำ 5 ข้อ แต่ละข้อตอบได้สองครั้ง"}}}'::jsonb),
  ('46d9b3a7-f7ec-47bc-b84c-df9dc6619872', 'ec33dba1-363b-4d64-8fde-59db59a9a286', 'summary', 'Remember', '{"kind":"summary","points":["Turn division into a times-table question.","Check by multiplying back."]}'::jsonb, 4, '{"my":{"title":"မှတ်ထားပါ","content":{"kind":"summary","points":["စားခြင်းကို အမြှောက်ဇယား မေးခွန်းအဖြစ် ပြောင်းပါ။","ပြန်မြှောက်ပြီး စစ်ပါ။"]}},"th":{"title":"จำไว้นะ","content":{"kind":"summary","points":["เปลี่ยนการหารเป็นคำถามสูตรคูณ","ตรวจโดยคูณกลับ"]}}}'::jsonb),
  ('25bbc00c-b3b3-44fb-a9d0-5ca26930a931', 'e4f8c15f-f842-4302-a023-8c35cd602b50', 'introduction', 'Let''s learn', '{"kind":"introduction","text":"Sometimes things do not share out exactly. What is left over is the remainder."}'::jsonb, 1, '{"my":{"title":"သင်ယူကြစို့","content":{"kind":"introduction","text":"တစ်ခါတလေ ပြတ်ပြတ်သားသား ခွဲဝေလို့ မရဘူး။ ကျန်တာက အကြွင်းပါ။"}},"th":{"title":"มาเรียนกัน","content":{"kind":"introduction","text":"บางครั้งแบ่งได้ไม่ลงตัว ส่วนที่เหลือเรียกว่าเศษ"}}}'::jsonb),
  ('26bbc19f-b2b3-4368-aad0-5e356830a79e', 'e4f8c15f-f842-4302-a023-8c35cd602b50', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"17 children make teams of 5. How many full teams?","steps":["Count in 5s: 5, 10, 15. The next would be 20 — too many.","3 teams use 15 children.","17 − 15 = 2 left over. So 3 full teams, remainder 2."]}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"ကလေး 17 ယောက်က 5 ယောက်စီ အသင်းဖွဲ့တယ်။ အသင်းပြည့် ဘယ်နှသင်း ရလဲ။","steps":["5 စီ ရေပါ - 5၊ 10၊ 15။ နောက်တစ်ခုက 20 ဖြစ်မှာမို့ များလွန်းတယ်။","အသင်း 3 သင်းက ကလေး 15 ယောက် သုံးတယ်။","17 − 15 = 2 ယောက် ကျန်တယ်။ ဒါကြောင့် အသင်းပြည့် 3 သင်း၊ အကြွင်း 2။"]}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"เด็ก 17 คนจัดทีม ทีมละ 5 คน ได้ทีมเต็มกี่ทีม","steps":["นับทีละ 5: 5, 10, 15 ครั้งต่อไปคือ 20 ซึ่งมากเกินไป","3 ทีมใช้เด็ก 15 คน","17 − 15 = 2 คนที่เหลือ จึงได้ 3 ทีมเต็ม เศษ 2"]}}}'::jsonb),
  ('27bbc332-b5b3-4821-a7d0-597c6730a60b', 'e4f8c15f-f842-4302-a023-8c35cd602b50', 'practice', 'Your turn', '{"kind":"practice","text":"Try 5 questions. You get two tries at each one."}'::jsonb, 3, '{"my":{"title":"သင့်အလှည့်","content":{"kind":"practice","text":"မေးခွန်း 5 ခု ဖြေကြည့်ပါ။ တစ်ခုစီကို နှစ်ကြိမ် ဖြေနိုင်တယ်။"}},"th":{"title":"ถึงตาเธอแล้ว","content":{"kind":"practice","text":"ลองทำ 5 ข้อ แต่ละข้อตอบได้สองครั้ง"}}}'::jsonb),
  ('28bbc4c5-b4b3-468e-a8d0-5b0f6630a478', 'e4f8c15f-f842-4302-a023-8c35cd602b50', 'summary', 'Remember', '{"kind":"summary","points":["The remainder is what is left over.","Read the question: does it ask for full groups?"]}'::jsonb, 4, '{"my":{"title":"မှတ်ထားပါ","content":{"kind":"summary","points":["အကြွင်းဆိုတာ ကျန်တဲ့ အရာပါ။","မေးခွန်းကို ဖတ်ပါ - အုပ်စုပြည့်ကို မေးနေတာလား။"]}},"th":{"title":"จำไว้นะ","content":{"kind":"summary","points":["เศษคือส่วนที่เหลือ","อ่านคำถาม: ถามหากลุ่มที่เต็มหรือเปล่า"]}}}'::jsonb),
  ('cde89b35-3cb9-428e-a592-7a0326d9491c', '93be7b9a-dedb-460b-8ff6-9458942c9d99', 'introduction', 'Let''s learn', '{"kind":"introduction","text":"A fraction is part of a whole that has been split into equal parts.","visual":{"kind":"fraction_bar","parts":4,"shaded":3}}'::jsonb, 1, '{"my":{"title":"သင်ယူကြစို့","content":{"kind":"introduction","text":"အပိုင်းကိန်းဆိုတာ အပိုင်းညီတွေ ခွဲထားတဲ့ တစ်ခုလုံးရဲ့ အစိတ်အပိုင်းပါ။","visual":{"kind":"fraction_bar","parts":4,"shaded":3}}},"th":{"title":"มาเรียนกัน","content":{"kind":"introduction","text":"เศษส่วนคือส่วนหนึ่งของสิ่งที่ถูกแบ่งเป็นส่วนเท่า ๆ กัน","visual":{"kind":"fraction_bar","parts":4,"shaded":3}}}}'::jsonb),
