  ('94f33932-7b86-4d95-8300-4238c8ee2ceb', '25358f2e-7580-4cd3-b3c3-0e24d65947f1', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"What is 3/4 of 20?","steps":["Find 1/4 first: 20 ÷ 4 = 5.","3/4 is three of those: 3 × 5 = 15.","So 3/4 of 20 is 15."]}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"20 ရဲ့ 3/4 က ဘယ်လောက်လဲ။","steps":["1/4 ကို အရင်ရှာပါ - 20 ÷ 4 = 5။","3/4 က အဲဒီလို သုံးခုပါ - 3 × 5 = 15။","ဒါကြောင့် 20 ရဲ့ 3/4 က 15 ပါ။"]}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"3/4 ของ 20 เท่ากับเท่าไร","steps":["หา 1/4 ก่อน: 20 ÷ 4 = 5","3/4 คือสามส่วนแบบนั้น: 3 × 5 = 15","ดังนั้น 3/4 ของ 20 คือ 15"]}}}'::jsonb),
