  ('2e13edd6-2b4b-4241-b93f-1b1c87226617', 'd32b6072-1037-41bf-a34f-67d87b8c1f75', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"What is 1/3 + 1/6?","steps":["Change 1/3 into sixths: 1/3 = 2/6.","2/6 + 1/6 = 3/6.","3/6 simplifies to 1/2."]}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"1/3 + 1/6 က ဘယ်လောက်လဲ။","steps":["1/3 ကို ခြောက်ပုံပုံအဖြစ် ပြောင်းပါ - 1/3 = 2/6။","2/6 + 1/6 = 3/6။","3/6 ကို ရိုးရှင်းအောင်လုပ်ရင် 1/2 ရတယ်။"]}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"1/3 + 1/6 เท่ากับเท่าไร","steps":["เปลี่ยน 1/3 เป็นส่วนหก: 1/3 = 2/6","2/6 + 1/6 = 3/6","3/6 ทำเป็นอย่างต่ำได้ 1/2"]}}}'::jsonb),
