  ('15a7f9d9-d3af-46d4-b099-cddf5842d4da', '498ca0eb-c600-4ae8-8c1f-e1a16a46adfe', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"What is 30% of 60?","steps":["10% of 60 = 60 ÷ 10 = 6.","30% is 3 lots of 10%.","3 × 6 = 18."]}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"60 ရဲ့ 30% က ဘယ်လောက်လဲ။","steps":["60 ရဲ့ 10% = 60 ÷ 10 = 6။","30% က 10% သုံးခုပါ။","3 × 6 = 18။"]}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"30% ของ 60 เท่ากับเท่าไร","steps":["10% ของ 60 = 60 ÷ 10 = 6","30% คือ 10% สามครั้ง","3 × 6 = 18"]}}}'::jsonb),
