  ('9a2dd9c2-7fae-4319-b08b-7ef441ceb5eb', '014c4da5-d493-4074-96de-b39782b99fd6', 'introduction', 'Let''s learn', '{"kind":"introduction","text":"A ratio compares amounts. 2 : 3 means for every 2 of one thing there are 3 of another.","visual":{"kind":"ratio","a":{"object":"apple","count":2},"b":{"object":"star","count":3}}}'::jsonb, 1, '{"my":{"title":"သင်ယူကြစို့","content":{"kind":"introduction","text":"အချိုးက ပမာဏတွေကို နှိုင်းယှဉ်တယ်။ 2 : 3 ဆိုတာ တစ်မျိုး 2 ခုတိုင်းအတွက် နောက်တစ်မျိုး 3 ခု ရှိတယ်။","visual":{"kind":"ratio","a":{"object":"apple","count":2},"b":{"object":"star","count":3}}}},"th":{"title":"มาเรียนกัน","content":{"kind":"introduction","text":"อัตราส่วนใช้เปรียบเทียบปริมาณ 2 : 3 หมายถึง ทุก 2 ของสิ่งหนึ่ง มี 3 ของอีกสิ่งหนึ่ง","visual":{"kind":"ratio","a":{"object":"apple","count":2},"b":{"object":"star","count":3}}}}}'::jsonb),
  ('9b2ddb55-7eae-4186-b18b-808740ceb458', '014c4da5-d493-4074-96de-b39782b99fd6', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"Share 15 sweets in the ratio 2 : 3.","steps":["Total parts: 2 + 3 = 5.","One part: 15 ÷ 5 = 3.","The shares are 2 × 3 = 6 and 3 × 3 = 9."]}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"သကြားလုံး 15 လုံးကို 2 : 3 အချိုးနဲ့ ခွဲဝေပါ။","steps":["အပိုင်း စုစုပေါင်း - 2 + 3 = 5။","တစ်ပိုင်း - 15 ÷ 5 = 3။","ခွဲဝေမှုတွေက 2 × 3 = 6 နဲ့ 3 × 3 = 9။"]}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"แบ่งลูกอม 15 เม็ดในอัตราส่วน 2 : 3","steps":["จำนวนส่วนทั้งหมด: 2 + 3 = 5","หนึ่งส่วน: 15 ÷ 5 = 3","ส่วนแบ่งคือ 2 × 3 = 6 และ 3 × 3 = 9"]}}}'::jsonb),
  ('982dd69c-7dae-4ff3-b28b-821a43ceb911', '014c4da5-d493-4074-96de-b39782b99fd6', 'practice', 'Your turn', '{"kind":"practice","text":"Try 5 questions. You get two tries at each one."}'::jsonb, 3, '{"my":{"title":"သင့်အလှည့်","content":{"kind":"practice","text":"မေးခွန်း 5 ခု ဖြေကြည့်ပါ။ တစ်ခုစီကို နှစ်ကြိမ် ဖြေနိုင်တယ်။"}},"th":{"title":"ถึงตาเธอแล้ว","content":{"kind":"practice","text":"ลองทำ 5 ข้อ แต่ละข้อตอบได้สองครั้ง"}}}'::jsonb),
  ('992dd82f-7cae-4e60-b38b-83ad42ceb77e', '014c4da5-d493-4074-96de-b39782b99fd6', 'summary', 'Remember', '{"kind":"summary","points":["Simplify a ratio like a fraction.","Sharing: add the parts, divide, then multiply."]}'::jsonb, 4, '{"my":{"title":"မှတ်ထားပါ","content":{"kind":"summary","points":["အချိုးကို အပိုင်းကိန်းလို ရိုးရှင်းအောင် လုပ်ပါ။","ခွဲဝေခြင်း - အပိုင်းတွေ ပေါင်း၊ စား၊ ပြီးရင် မြှောက်ပါ။"]}},"th":{"title":"จำไว้นะ","content":{"kind":"summary","points":["ทำอัตราส่วนเป็นอย่างต่ำเหมือนเศษส่วน","การแบ่ง: บวกส่วน หาร แล้วคูณ"]}}}'::jsonb),
  ('ce3b1a8d-676e-4778-b349-8ff748e8462a', 'e922268c-0682-478b-9d81-68ae70200c8d', 'introduction', 'Let''s learn', '{"kind":"introduction","text":"Numbers less than zero are negative. On a number line they are to the left of 0.","visual":{"kind":"number_line","min":-6,"max":6,"step":1,"highlight":[-4]}}'::jsonb, 1, '{"my":{"title":"သင်ယူကြစို့","content":{"kind":"introduction","text":"သုညထက်ငယ်တဲ့ ဂဏန်းတွေက အနုတ်ကိန်းပါ။ ကိန်းမျဉ်းပေါ်မှာ 0 ရဲ့ ဘယ်ဘက်မှာ ရှိတယ်။","visual":{"kind":"number_line","min":-6,"max":6,"step":1,"highlight":[-4]}}},"th":{"title":"มาเรียนกัน","content":{"kind":"introduction","text":"จำนวนที่น้อยกว่าศูนย์คือจำนวนลบ บนเส้นจำนวนจะอยู่ทางซ้ายของ 0","visual":{"kind":"number_line","min":-6,"max":6,"step":1,"highlight":[-4]}}}}'::jsonb),
  ('cd3b18fa-686e-490b-b249-8e6449e847bd', 'e922268c-0682-478b-9d81-68ae70200c8d', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"Which is greater, −2 or −5?","steps":["Find both on the number line.","−2 is further right than −5.","So −2 > −5."],"visual":{"kind":"number_line","min":-6,"max":2,"step":1,"highlight":[-5,-2]}}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"−2 နဲ့ −5 ဘယ်ဟာ ပိုကြီးလဲ။","steps":["ကိန်းမျဉ်းပေါ်မှာ နှစ်ခုလုံးကို ရှာပါ။","−2 က −5 ထက် ညာဘက်ကို ပိုရောက်တယ်။","ဒါကြောင့် −2 > −5။"],"visual":{"kind":"number_line","min":-6,"max":2,"step":1,"highlight":[-5,-2]}}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"จำนวนใดมากกว่า −2 หรือ −5","steps":["หาทั้งสองจำนวนบนเส้นจำนวน","−2 อยู่ทางขวามากกว่า −5","ดังนั้น −2 > −5"],"visual":{"kind":"number_line","min":-6,"max":2,"step":1,"highlight":[-5,-2]}}}}'::jsonb),
