  ('cb3b15d4-6a6e-4c31-b449-918a47e84497', 'e922268c-0682-478b-9d81-68ae70200c8d', 'summary', 'Remember', '{"kind":"summary","points":["Further right means greater.","−1 is greater than −10."]}'::jsonb, 4, '{"my":{"title":"မှတ်ထားပါ","content":{"kind":"summary","points":["ညာဘက်ကို ပိုရောက်လေ ပိုကြီးလေပါ။","−1 က −10 ထက် ကြီးတယ်။"]}},"th":{"title":"จำไว้นะ","content":{"kind":"summary","points":["อยู่ทางขวามากกว่าหมายถึงมากกว่า","−1 มากกว่า −10"]}}}'::jsonb),
  ('8ca3830d-bb20-44ca-b2d1-a533e42055c0', 'c7b1bd5e-f206-4953-afd2-8a840eb9c009', 'introduction', 'Let''s learn', '{"kind":"introduction","text":"Adding moves right on the number line. Subtracting moves left. Subtracting a negative moves right!"}'::jsonb, 1, '{"my":{"title":"သင်ယူကြစို့","content":{"kind":"introduction","text":"ပေါင်းရင် ကိန်းမျဉ်းပေါ်မှာ ညာဘက်ကို ရွှေ့တယ်။ နုတ်ရင် ဘယ်ဘက်ကို ရွှေ့တယ်။ အနုတ်ကိန်းကို နုတ်ရင် ညာဘက်ကို ရွှေ့တယ်!"}},"th":{"title":"มาเรียนกัน","content":{"kind":"introduction","text":"การบวกคือเลื่อนไปทางขวาบนเส้นจำนวน การลบคือเลื่อนไปทางซ้าย การลบจำนวนลบคือเลื่อนไปทางขวา!"}}}'::jsonb),
  ('8ba3817a-bc20-465d-b1d1-a3a0e5205753', 'c7b1bd5e-f206-4953-afd2-8a840eb9c009', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"What is −3 + 7?","steps":["Start at −3.","Move 7 to the right, passing 0.","You land on 4, so −3 + 7 = 4."],"visual":{"kind":"number_line","min":-4,"max":5,"step":1,"highlight":[-3],"jumps":[{"from":-3,"to":4}]}}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"−3 + 7 က ဘယ်လောက်လဲ။","steps":["−3 မှာ စပါ။","0 ကို ဖြတ်ပြီး ညာဘက်ကို 7 ရွှေ့ပါ။","4 မှာ ရောက်လို့ −3 + 7 = 4။"],"visual":{"kind":"number_line","min":-4,"max":5,"step":1,"highlight":[-3],"jumps":[{"from":-3,"to":4}]}}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"−3 + 7 เท่ากับเท่าไร","steps":["เริ่มที่ −3","เลื่อนไปทางขวา 7 ช่อง ผ่าน 0","จะถึง 4 ดังนั้น −3 + 7 = 4"],"visual":{"kind":"number_line","min":-4,"max":5,"step":1,"highlight":[-3],"jumps":[{"from":-3,"to":4}]}}}}'::jsonb),
