  ('89a37e54-ba20-4337-b3d1-a6c6e7205a79', 'c7b1bd5e-f206-4953-afd2-8a840eb9c009', 'summary', 'Remember', '{"kind":"summary","points":["+ moves right, − moves left.","Subtracting a negative is the same as adding."]}'::jsonb, 4, '{"my":{"title":"မှတ်ထားပါ","content":{"kind":"summary","points":["+ က ညာဘက်ကို၊ − က ဘယ်ဘက်ကို ရွှေ့တယ်။","အနုတ်ကိန်းကို နုတ်တာက ပေါင်းတာနဲ့ အတူတူပါ။"]}},"th":{"title":"จำไว้นะ","content":{"kind":"summary","points":["+ เลื่อนไปทางขวา − เลื่อนไปทางซ้าย","การลบจำนวนลบเท่ากับการบวก"]}}}'::jsonb),
  ('f3f85058-692a-4de9-b3e0-84eaa7b33c0b', '684bf745-e1dd-47ae-9dd8-a6f712cb4d48', 'introduction', 'Let''s learn', '{"kind":"introduction","text":"Thermometers are vertical number lines. Temperatures can rise above or fall below 0°C.","visual":{"kind":"thermometer","value":-4}}'::jsonb, 1, '{"my":{"title":"သင်ယူကြစို့","content":{"kind":"introduction","text":"သာမိုမီတာတွေက ဒေါင်လိုက် ကိန်းမျဉ်းတွေပါ။ အပူချိန်က 0°C အထက်ကို တက်နိုင်သလို အောက်ကိုလည်း ကျနိုင်တယ်။","visual":{"kind":"thermometer","value":-4}}},"th":{"title":"มาเรียนกัน","content":{"kind":"introduction","text":"เทอร์โมมิเตอร์คือเส้นจำนวนแนวตั้ง อุณหภูมิอาจสูงกว่าหรือต่ำกว่า 0°C","visual":{"kind":"thermometer","value":-4}}}}'::jsonb),
  ('f4f851eb-682a-4c56-b4e0-867da6b33a78', '684bf745-e1dd-47ae-9dd8-a6f712cb4d48', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"It is −4°C. It rises by 6 degrees. What is the temperature now?","steps":["Rising means add.","−4 + 6 = 2.","The temperature is 2°C."],"visual":{"kind":"thermometer","value":-4}}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"−4°C ရှိတယ်။ 6 ဒီဂရီ တက်သွားတယ်။ အခု အပူချိန် ဘယ်လောက်လဲ။","steps":["တက်တာက ပေါင်းရမယ်။","−4 + 6 = 2။","အပူချိန်က 2°C ပါ။"],"visual":{"kind":"thermometer","value":-4}}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"อุณหภูมิ −4°C แล้วสูงขึ้น 6 องศา ตอนนี้อุณหภูมิเท่าไร","steps":["สูงขึ้นแปลว่าบวก","−4 + 6 = 2","อุณหภูมิคือ 2°C"],"visual":{"kind":"thermometer","value":-4}}}}'::jsonb),
