  ('f6f85511-662a-4930-b2e0-8357a8b33d9e', '684bf745-e1dd-47ae-9dd8-a6f712cb4d48', 'summary', 'Remember', '{"kind":"summary","points":["Rise: add. Fall: subtract.","Difference: count up through 0."]}'::jsonb, 4, '{"my":{"title":"မှတ်ထားပါ","content":{"kind":"summary","points":["တက်ရင် - ပေါင်းပါ။ ကျရင် - နုတ်ပါ။","ကွာခြားချက် - 0 ကို ဖြတ်ပြီး အပေါ်ကို ရေပါ။"]}},"th":{"title":"จำไว้นะ","content":{"kind":"summary","points":["สูงขึ้น: บวก ลดลง: ลบ","ผลต่าง: นับขึ้นผ่าน 0"]}}}'::jsonb),
  ('206e4f81-ffd6-4758-9d3a-4b63b866fac2', 'f60ed9e4-4a14-412f-861e-d27eb1b3f6a9', 'introduction', 'Let''s learn', '{"kind":"introduction","text":"Perimeter is the total length around the outside of a shape.","visual":{"kind":"rectangle","width":7,"height":3,"unit":"cm"}}'::jsonb, 1, '{"my":{"title":"သင်ယူကြစို့","content":{"kind":"introduction","text":"ပတ်လည်အနားဆိုတာ ပုံရဲ့ အပြင်ဘက်ကို ပတ်တဲ့ စုစုပေါင်း အလျားပါ။","visual":{"kind":"rectangle","width":7,"height":3,"unit":"cm"}}},"th":{"title":"มาเรียนกัน","content":{"kind":"introduction","text":"ความยาวรอบรูปคือความยาวทั้งหมดรอบด้านนอกของรูป","visual":{"kind":"rectangle","width":7,"height":3,"unit":"cm"}}}}'::jsonb),
  ('1f6e4dee-00d6-48eb-9c3a-49d0b966fc55', 'f60ed9e4-4a14-412f-861e-d27eb1b3f6a9', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"Find the perimeter of a 7 cm by 3 cm rectangle.","steps":["Add length and width: 7 + 3 = 10.","There are two of each: 2 × 10 = 20.","The perimeter is 20 cm."],"visual":{"kind":"rectangle","width":7,"height":3,"unit":"cm"}}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"7 cm နဲ့ 3 cm ရှိတဲ့ ထောင့်မှန်စတုဂံရဲ့ ပတ်လည်အနားကို ရှာပါ။","steps":["အလျားနဲ့ အနံကို ပေါင်းပါ - 7 + 3 = 10။","တစ်ခုစီ နှစ်ခုစီ ရှိတယ် - 2 × 10 = 20။","ပတ်လည်အနားက 20 cm ပါ။"],"visual":{"kind":"rectangle","width":7,"height":3,"unit":"cm"}}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"หาความยาวรอบรูปของสี่เหลี่ยมผืนผ้าขนาด 7 cm คูณ 3 cm","steps":["บวกความยาวกับความกว้าง: 7 + 3 = 10","มีอย่างละสองด้าน: 2 × 10 = 20","ความยาวรอบรูปคือ 20 cm"],"visual":{"kind":"rectangle","width":7,"height":3,"unit":"cm"}}}}'::jsonb),
  ('1e6e4c5b-01d6-4a7e-9f3a-4e89b666f79c', 'f60ed9e4-4a14-412f-861e-d27eb1b3f6a9', 'practice', 'Your turn', '{"kind":"practice","text":"Try 5 questions. You get two tries at each one."}'::jsonb, 3, '{"my":{"title":"သင့်အလှည့်","content":{"kind":"practice","text":"မေးခွန်း 5 ခု ဖြေကြည့်ပါ။ တစ်ခုစီကို နှစ်ကြိမ် ဖြေနိုင်တယ်။"}},"th":{"title":"ถึงตาเธอแล้ว","content":{"kind":"practice","text":"ลองทำ 5 ข้อ แต่ละข้อตอบได้สองครั้ง"}}}'::jsonb),
  ('1d6e4ac8-02d6-4c11-9e3a-4cf6b766f92f', 'f60ed9e4-4a14-412f-861e-d27eb1b3f6a9', 'summary', 'Remember', '{"kind":"summary","points":["Rectangle perimeter = 2 × (length + width).","Square perimeter = 4 × side."]}'::jsonb, 4, '{"my":{"title":"မှတ်ထားပါ","content":{"kind":"summary","points":["ထောင့်မှန်စတုဂံ ပတ်လည်အနား = 2 × (အလျား + အနံ)။","စတုရန်း ပတ်လည်အနား = 4 × အနား။"]}},"th":{"title":"จำไว้นะ","content":{"kind":"summary","points":["ความยาวรอบรูปสี่เหลี่ยมผืนผ้า = 2 × (ยาว + กว้าง)","ความยาวรอบรูปสี่เหลี่ยมจัตุรัส = 4 × ด้าน"]}}}'::jsonb),
  ('ac16052c-6139-495d-a44b-66aec1848cd7', '111e6d59-4819-412a-8d07-1f638046fd2c', 'introduction', 'Let''s learn', '{"kind":"introduction","text":"Area is the amount of space inside a shape, measured in squares like cm².","visual":{"kind":"rectangle","width":5,"height":3,"unit":"cm","showGrid":true}}'::jsonb, 1, '{"my":{"title":"သင်ယူကြစို့","content":{"kind":"introduction","text":"ဧရိယာဆိုတာ ပုံထဲက နေရာပမာဏပါ၊ cm² လို စတုရန်းယူနစ်တွေနဲ့ တိုင်းတယ်။","visual":{"kind":"rectangle","width":5,"height":3,"unit":"cm","showGrid":true}}},"th":{"title":"มาเรียนกัน","content":{"kind":"introduction","text":"พื้นที่คือขนาดของที่ว่างภายในรูป วัดเป็นตารางหน่วย เช่น cm²","visual":{"kind":"rectangle","width":5,"height":3,"unit":"cm","showGrid":true}}}}'::jsonb),
  ('ad1606bf-6039-47ca-a54b-6841c0848b44', '111e6d59-4819-412a-8d07-1f638046fd2c', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"Find the area of a 5 cm by 3 cm rectangle.","steps":["There are 3 rows of 5 squares.","3 × 5 = 15.","The area is 15 cm²."],"visual":{"kind":"rectangle","width":5,"height":3,"unit":"cm","showGrid":true}}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"5 cm နဲ့ 3 cm ရှိတဲ့ ထောင့်မှန်စတုဂံရဲ့ ဧရိယာကို ရှာပါ။","steps":["5 ကွက်စီပါတဲ့ အတန်း 3 တန်း ရှိတယ်။","3 × 5 = 15။","ဧရိယာက 15 cm² ပါ။"],"visual":{"kind":"rectangle","width":5,"height":3,"unit":"cm","showGrid":true}}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"หาพื้นที่ของสี่เหลี่ยมผืนผ้าขนาด 5 cm คูณ 3 cm","steps":["มี 3 แถว แถวละ 5 ช่อง","3 × 5 = 15","พื้นที่คือ 15 cm²"],"visual":{"kind":"rectangle","width":5,"height":3,"unit":"cm","showGrid":true}}}}'::jsonb),
  ('ae160852-5f39-4637-a24b-6388c3848ffd', '111e6d59-4819-412a-8d07-1f638046fd2c', 'practice', 'Your turn', '{"kind":"practice","text":"Try 5 questions. You get two tries at each one."}'::jsonb, 3, '{"my":{"title":"သင့်အလှည့်","content":{"kind":"practice","text":"မေးခွန်း 5 ခု ဖြေကြည့်ပါ။ တစ်ခုစီကို နှစ်ကြိမ် ဖြေနိုင်တယ်။"}},"th":{"title":"ถึงตาเธอแล้ว","content":{"kind":"practice","text":"ลองทำ 5 ข้อ แต่ละข้อตอบได้สองครั้ง"}}}'::jsonb),
  ('af1609e5-5e39-44a4-a34b-651bc2848e6a', '111e6d59-4819-412a-8d07-1f638046fd2c', 'summary', 'Remember', '{"kind":"summary","points":["Area = length × width.","Area is in square units, like cm²."]}'::jsonb, 4, '{"my":{"title":"မှတ်ထားပါ","content":{"kind":"summary","points":["ဧရိယာ = အလျား × အနံ။","ဧရိယာက cm² လို စတုရန်းယူနစ်နဲ့ ဖြစ်တယ်။"]}},"th":{"title":"จำไว้นะ","content":{"kind":"summary","points":["พื้นที่ = ยาว × กว้าง","พื้นที่มีหน่วยเป็นตารางหน่วย เช่น cm²"]}}}'::jsonb),
  ('52b9502b-1543-4a90-91a8-62bd16cd3462', '8744379c-ed0a-436d-bfb0-dfce89ad5c57', 'introduction', 'Let''s learn', '{"kind":"introduction","text":"A triangle fits exactly into half of a rectangle with the same base and height.","visual":{"kind":"triangle","base":8,"height":5,"unit":"cm"}}'::jsonb, 1, '{"my":{"title":"သင်ယူကြစို့","content":{"kind":"introduction","text":"တြိဂံတစ်ခုက အခြေနဲ့ အမြင့် တူတဲ့ ထောင့်မှန်စတုဂံရဲ့ တစ်ဝက်ထဲမှာ အတိအကျ ဝင်တယ်။","visual":{"kind":"triangle","base":8,"height":5,"unit":"cm"}}},"th":{"title":"มาเรียนกัน","content":{"kind":"introduction","text":"สามเหลี่ยมพอดีกับครึ่งหนึ่งของสี่เหลี่ยมผืนผ้าที่มีฐานและความสูงเท่ากัน","visual":{"kind":"triangle","base":8,"height":5,"unit":"cm"}}}}'::jsonb),
  ('51b94e98-1643-4c23-90a8-612a17cd35f5', '8744379c-ed0a-436d-bfb0-dfce89ad5c57', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"Find the area of a triangle with base 8 cm and height 5 cm.","steps":["Rectangle area: 8 × 5 = 40.","The triangle is half: 40 ÷ 2 = 20.","The area is 20 cm²."],"visual":{"kind":"triangle","base":8,"height":5,"unit":"cm"}}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"အခြေ 8 cm နဲ့ အမြင့် 5 cm ရှိတဲ့ တြိဂံရဲ့ ဧရိယာကို ရှာပါ။","steps":["ထောင့်မှန်စတုဂံ ဧရိယာ - 8 × 5 = 40။","တြိဂံက တစ်ဝက်ပါ - 40 ÷ 2 = 20။","ဧရိယာက 20 cm² ပါ။"],"visual":{"kind":"triangle","base":8,"height":5,"unit":"cm"}}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"หาพื้นที่ของสามเหลี่ยมฐาน 8 cm สูง 5 cm","steps":["พื้นที่สี่เหลี่ยมผืนผ้า: 8 × 5 = 40","สามเหลี่ยมคือครึ่งหนึ่ง: 40 ÷ 2 = 20","พื้นที่คือ 20 cm²"],"visual":{"kind":"triangle","base":8,"height":5,"unit":"cm"}}}}'::jsonb),
  ('54b95351-1743-4db6-8fa8-5f9714cd313c', '8744379c-ed0a-436d-bfb0-dfce89ad5c57', 'practice', 'Your turn', '{"kind":"practice","text":"Try 5 questions. You get two tries at each one."}'::jsonb, 3, '{"my":{"title":"သင့်အလှည့်","content":{"kind":"practice","text":"မေးခွန်း 5 ခု ဖြေကြည့်ပါ။ တစ်ခုစီကို နှစ်ကြိမ် ဖြေနိုင်တယ်။"}},"th":{"title":"ถึงตาเธอแล้ว","content":{"kind":"practice","text":"ลองทำ 5 ข้อ แต่ละข้อตอบได้สองครั้ง"}}}'::jsonb),
  ('53b951be-1843-4f49-8ea8-5e0415cd32cf', '8744379c-ed0a-436d-bfb0-dfce89ad5c57', 'summary', 'Remember', '{"kind":"summary","points":["Triangle area = 1/2 × base × height.","The height is straight up from the base."]}'::jsonb, 4, '{"my":{"title":"မှတ်ထားပါ","content":{"kind":"summary","points":["တြိဂံ ဧရိယာ = 1/2 × အခြေ × အမြင့်။","အမြင့်က အခြေကနေ တည့်တည့် အပေါ်ကို ဖြစ်တယ်။"]}},"th":{"title":"จำไว้นะ","content":{"kind":"summary","points":["พื้นที่สามเหลี่ยม = 1/2 × ฐาน × สูง","ความสูงวัดตั้งฉากขึ้นจากฐาน"]}}}'::jsonb),
  ('c5522a09-524c-43cc-96cf-0653c7059c8e', '327c2d58-9405-4fbf-aada-190aa131e319', 'introduction', 'Let''s learn', '{"kind":"introduction","text":"In algebra, a letter stands for a number. 3n means 3 × n."}'::jsonb, 1, '{"my":{"title":"သင်ယူကြစို့","content":{"kind":"introduction","text":"အက္ခရာသင်္ချာမှာ အက္ခရာတစ်လုံးက ဂဏန်းတစ်ခုကို ကိုယ်စားပြုတယ်။ 3n ဆိုတာ 3 × n ပါ။"}},"th":{"title":"มาเรียนกัน","content":{"kind":"introduction","text":"ในพีชคณิต ตัวอักษรใช้แทนจำนวน 3n หมายถึง 3 × n"}}}'::jsonb),
  ('c4522876-534c-455f-95cf-04c0c8059e21', '327c2d58-9405-4fbf-aada-190aa131e319', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"If n = 5, what is 2n + 3?","steps":["2n means 2 × n = 2 × 5 = 10.","Then add 3: 10 + 3 = 13."]}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"n = 5 ဆိုရင် 2n + 3 က ဘယ်လောက်လဲ။","steps":["2n ဆိုတာ 2 × n = 2 × 5 = 10။","ပြီးရင် 3 ပေါင်းပါ - 10 + 3 = 13။"]}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"ถ้า n = 5 แล้ว 2n + 3 เท่ากับเท่าไร","steps":["2n หมายถึง 2 × n = 2 × 5 = 10","แล้วบวก 3: 10 + 3 = 13"]}}}'::jsonb),
  ('c35226e3-544c-46f2-98cf-0979c5059968', '327c2d58-9405-4fbf-aada-190aa131e319', 'practice', 'Your turn', '{"kind":"practice","text":"Try 5 questions. You get two tries at each one."}'::jsonb, 3, '{"my":{"title":"သင့်အလှည့်","content":{"kind":"practice","text":"မေးခွန်း 5 ခု ဖြေကြည့်ပါ။ တစ်ခုစီကို နှစ်ကြိမ် ဖြေနိုင်တယ်။"}},"th":{"title":"ถึงตาเธอแล้ว","content":{"kind":"practice","text":"ลองทำ 5 ข้อ แต่ละข้อตอบได้สองครั้ง"}}}'::jsonb),
  ('c2522550-554c-4885-97cf-07e6c6059afb', '327c2d58-9405-4fbf-aada-190aa131e319', 'summary', 'Remember', '{"kind":"summary","points":["A number next to a letter means multiply.","Multiply first, then add or subtract."]}'::jsonb, 4, '{"my":{"title":"မှတ်ထားပါ","content":{"kind":"summary","points":["အက္ခရာဘေးက ဂဏန်းဆိုတာ မြှောက်ပါ။","အရင်မြှောက်ပြီးမှ ပေါင်း ဒါမှမဟုတ် နုတ်ပါ။"]}},"th":{"title":"จำไว้นะ","content":{"kind":"summary","points":["จำนวนที่อยู่ติดตัวอักษรหมายถึงคูณ","คูณก่อน แล้วจึงบวกหรือลบ"]}}}'::jsonb),
  ('4d99ce4c-41b5-46e5-8b30-6d0e2d33e10f', 'ee175789-43e1-4c82-918a-4b0346c8d77c', 'introduction', 'Let''s learn', '{"kind":"introduction","text":"An equation is balanced. Whatever you do to one side, do to the other."}'::jsonb, 1, '{"my":{"title":"သင်ယူကြစို့","content":{"kind":"introduction","text":"ညီမျှခြင်းက ချိန်ခွင်လျှာလို ညီနေတယ်။ တစ်ဘက်ကို ဘာလုပ်လုပ် နောက်တစ်ဘက်ကိုလည်း လုပ်ပါ။"}},"th":{"title":"มาเรียนกัน","content":{"kind":"introduction","text":"สมการสมดุลเหมือนตาชั่ง ทำอะไรกับข้างหนึ่ง ต้องทำกับอีกข้างด้วย"}}}'::jsonb),
  ('4e99cfdf-40b5-4552-8c30-6ea12c33df7c', 'ee175789-43e1-4c82-918a-4b0346c8d77c', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"Solve 2x + 5 = 17.","steps":["Subtract 5 from both sides: 2x = 12.","Divide both sides by 2: x = 6.","Check: 2 × 6 + 5 = 17."]}'::jsonb, 2, '{"my":{"title":"ဖြေရှင်းပြထားသော ဥပမာ","content":{"kind":"worked_example","problem":"2x + 5 = 17 ကို ဖြေရှင်းပါ။","steps":["နှစ်ဘက်လုံးကနေ 5 နုတ်ပါ - 2x = 12။","နှစ်ဘက်လုံးကို 2 နဲ့ စားပါ - x = 6။","စစ်ကြည့်ပါ - 2 × 6 + 5 = 17။"]}},"th":{"title":"ตัวอย่างพร้อมวิธีทำ","content":{"kind":"worked_example","problem":"แก้สมการ 2x + 5 = 17","steps":["ลบ 5 ทั้งสองข้าง: 2x = 12","หารทั้งสองข้างด้วย 2: x = 6","ตรวจ: 2 × 6 + 5 = 17"]}}}'::jsonb),
