  ('0441f24e-b134-491b-b9c0-97383d165965', 'dbdef370-8ba4-4321-9569-a27ae1e28923', 'numeric', 'Round 674 to the nearest 100.', '{"kind":"number_line","min":600,"max":700,"step":10,"highlight":[674]}'::jsonb, '{"value":"700"}'::jsonb, null, '674 is between 600 and 700. The tens digit is 7, which is 5 or more, so round up to 700.', 'Look at the tens digit. Is it 5 or more?', 3, 10, 5, true, '{"my":{"prompt":"674 ကို အနီးစပ်ဆုံး 100 ပြည့်ကိန်းသို့ ပြောင်းပါ။","explanation":"674 က 600 နဲ့ 700 ကြားမှာ ရှိတယ်။ ဆယ်လီ ဂဏန်းက 7 ဖြစ်ပြီး 5 နဲ့ အထက်ဖြစ်လို့ အပေါ်ကို ပြောင်းရမယ် - 700။","hint":"ဆယ်လီ ဂဏန်းကို ကြည့်ပါ။ 5 နဲ့ အထက်လား။"},"th":{"prompt":"ปัด 674 เป็นจำนวนเต็มร้อยที่ใกล้ที่สุด","explanation":"674 อยู่ระหว่าง 600 กับ 700 เลขในหลักสิบคือ 7 ซึ่งมากกว่าหรือเท่ากับ 5 จึงปัดขึ้นเป็น 700","hint":"ดูเลขในหลักสิบ มากกว่าหรือเท่ากับ 5 ไหม"}}'::jsonb),
  ('f2258610-3a18-4f55-b252-697ae979e347', 'ca0a26ea-52fd-4fc3-9d54-ef6cce146a1d', 'numeric', 'There are 4 rows with 5 flowers in each row. How many flowers are there?', '{"kind":"array","rows":4,"cols":5,"object":"flower"}'::jsonb, '{"value":"20"}'::jsonb, null, '4 rows of 5 is 4 × 5. Count in 5s: 5, 10, 15, 20. So 4 × 5 = 20.', 'Count in 5s, once for each row.', 1, 10, 1, true, '{"my":{"prompt":"အတန်း 4 တန်း ရှိပြီး တစ်တန်းမှာ ပန်း 5 ပွင့် စီ ရှိတယ်။ ပန်း ဘယ်နှပွင့် ရှိလဲ။","explanation":"5 စီပါတဲ့ အတန်း 4 တန်းက 4 × 5 ပါ။ 5 စီ ရေပါ - 5, 10, 15, 20။ ဒါကြောင့် 4 × 5 = 20။","hint":"အတန်းတစ်တန်းအတွက် တစ်ခါစီ 5 စီ ရေပါ။"},"th":{"prompt":"มี 4 แถว แถวละ ดอกไม้ 5 ดอก มีดอกไม้ทั้งหมดกี่ดอก","explanation":"4 แถว แถวละ 5 คือ 4 × 5 นับทีละ 5: 5, 10, 15, 20 ดังนั้น 4 × 5 = 20","hint":"นับทีละ 5 แถวละหนึ่งครั้ง"}}'::jsonb),
  ('f32587a3-3918-4dc2-b352-6b0de879e1b4', 'ca0a26ea-52fd-4fc3-9d54-ef6cce146a1d', 'numeric', 'There are 2 rows with 4 blocks in each row. How many blocks are there?', '{"kind":"array","rows":2,"cols":4,"object":"block"}'::jsonb, '{"value":"8"}'::jsonb, null, '2 rows of 4 is 2 × 4. Count in 4s: 4, 8. So 2 × 4 = 8.', 'Count in 4s, once for each row.', 1, 10, 2, true, '{"my":{"prompt":"အတန်း 2 တန်း ရှိပြီး တစ်တန်းမှာ တုံးလေး 4 တုံး စီ ရှိတယ်။ တုံးလေး ဘယ်နှတုံး ရှိလဲ။","explanation":"4 စီပါတဲ့ အတန်း 2 တန်းက 2 × 4 ပါ။ 4 စီ ရေပါ - 4, 8။ ဒါကြောင့် 2 × 4 = 8။","hint":"အတန်းတစ်တန်းအတွက် တစ်ခါစီ 4 စီ ရေပါ။"},"th":{"prompt":"มี 2 แถว แถวละ บล็อก 4 ก้อน มีบล็อกทั้งหมดกี่ก้อน","explanation":"2 แถว แถวละ 4 คือ 2 × 4 นับทีละ 4: 4, 8 ดังนั้น 2 × 4 = 8","hint":"นับทีละ 4 แถวละหนึ่งครั้ง"}}'::jsonb),
  ('f4258936-3818-4c2f-b052-6654eb79e66d', 'ca0a26ea-52fd-4fc3-9d54-ef6cce146a1d', 'numeric', 'What is 4 × 2?', null, '{"value":"8"}'::jsonb, null, '4 × 2 means 4 groups of 2. Count in 2s: 2, 4, 6, 8. So 4 × 2 = 8.', 'Count in 2s, 4 times.', 1, 10, 3, true, '{"my":{"prompt":"4 × 2 က ဘယ်လောက်လဲ။","explanation":"4 × 2 ဆိုတာ 2 စီပါတဲ့ အုပ်စု 4 စုပါ။ 2 စီ ရေပါ - 2, 4, 6, 8။ ဒါကြောင့် 4 × 2 = 8။","hint":"2 စီ 4 ကြိမ် ရေပါ။"},"th":{"prompt":"4 × 2 เท่ากับเท่าไร","explanation":"4 × 2 หมายถึง 4 กลุ่ม กลุ่มละ 2 นับทีละ 2: 2, 4, 6, 8 ดังนั้น 4 × 2 = 8","hint":"นับทีละ 2 จำนวน 4 ครั้ง"}}'::jsonb),
  ('f5258ac9-3718-4a9c-b152-67e7ea79e4da', 'ca0a26ea-52fd-4fc3-9d54-ef6cce146a1d', 'numeric', 'There are 4 rows with 3 apples in each row. How many apples are there?', '{"kind":"array","rows":4,"cols":3,"object":"apple"}'::jsonb, '{"value":"12"}'::jsonb, null, '4 rows of 3 is 4 × 3. Count in 3s: 3, 6, 9, 12. So 4 × 3 = 12.', 'Count in 3s, once for each row.', 1, 10, 4, true, '{"my":{"prompt":"အတန်း 4 တန်း ရှိပြီး တစ်တန်းမှာ ပန်းသီး 3 လုံး စီ ရှိတယ်။ ပန်းသီး ဘယ်နှလုံး ရှိလဲ။","explanation":"3 စီပါတဲ့ အတန်း 4 တန်းက 4 × 3 ပါ။ 3 စီ ရေပါ - 3, 6, 9, 12။ ဒါကြောင့် 4 × 3 = 12။","hint":"အတန်းတစ်တန်းအတွက် တစ်ခါစီ 3 စီ ရေပါ။"},"th":{"prompt":"มี 4 แถว แถวละ แอปเปิล 3 ผล มีแอปเปิลทั้งหมดกี่ผล","explanation":"4 แถว แถวละ 3 คือ 4 × 3 นับทีละ 3: 3, 6, 9, 12 ดังนั้น 4 × 3 = 12","hint":"นับทีละ 3 แถวละหนึ่งครั้ง"}}'::jsonb),
  ('f6258c5c-3618-4909-ae52-632ee579dcfb', 'ca0a26ea-52fd-4fc3-9d54-ef6cce146a1d', 'numeric', 'What is 2 × 5?', null, '{"value":"10"}'::jsonb, null, '2 × 5 means 2 groups of 5. Count in 5s: 5, 10. So 2 × 5 = 10.', 'Count in 5s, 2 times.', 1, 10, 5, true, '{"my":{"prompt":"2 × 5 က ဘယ်လောက်လဲ။","explanation":"2 × 5 ဆိုတာ 5 စီပါတဲ့ အုပ်စု 2 စုပါ။ 5 စီ ရေပါ - 5, 10။ ဒါကြောင့် 2 × 5 = 10။","hint":"5 စီ 2 ကြိမ် ရေပါ။"},"th":{"prompt":"2 × 5 เท่ากับเท่าไร","explanation":"2 × 5 หมายถึง 2 กลุ่ม กลุ่มละ 5 นับทีละ 5: 5, 10 ดังนั้น 2 × 5 = 10","hint":"นับทีละ 5 จำนวน 2 ครั้ง"}}'::jsonb),
  ('485938ba-92f2-4db7-a7f3-000419ace9c9', 'f38d59d0-1246-4c79-ac8c-e042171c4c93', 'numeric', 'What is 12 × 3?', null, '{"value":"36"}'::jsonb, null, '12 × 3 means 12 groups of 3. Split it up: 5 × 3 = 15 and 7 × 3 = 21. 15 + 21 = 36. So 12 × 3 = 36.', 'Count in 3s, 12 times.', 2, 10, 1, true, '{"my":{"prompt":"12 × 3 က ဘယ်လောက်လဲ။","explanation":"12 × 3 ဆိုတာ 3 စီပါတဲ့ အုပ်စု 12 စုပါ။ ခွဲလိုက်ပါ - 5 × 3 = 15 နဲ့ 7 × 3 = 21။ 15 + 21 = 36။ ဒါကြောင့် 12 × 3 = 36။","hint":"3 စီ 12 ကြိမ် ရေပါ။"},"th":{"prompt":"12 × 3 เท่ากับเท่าไร","explanation":"12 × 3 หมายถึง 12 กลุ่ม กลุ่มละ 3 แยกคิด: 5 × 3 = 15 และ 7 × 3 = 21 15 + 21 = 36 ดังนั้น 12 × 3 = 36","hint":"นับทีละ 3 จำนวน 12 ครั้ง"}}'::jsonb),
  ('49593a4d-91f2-4c24-a8f3-019718ace836', 'f38d59d0-1246-4c79-ac8c-e042171c4c93', 'numeric', 'What is 10 × 4?', null, '{"value":"40"}'::jsonb, null, '10 × 4 means 10 groups of 4. Split it up: 5 × 4 = 20 and 5 × 4 = 20. 20 + 20 = 40. So 10 × 4 = 40.', 'Count in 4s, 10 times.', 2, 10, 2, true, '{"my":{"prompt":"10 × 4 က ဘယ်လောက်လဲ။","explanation":"10 × 4 ဆိုတာ 4 စီပါတဲ့ အုပ်စု 10 စုပါ။ ခွဲလိုက်ပါ - 5 × 4 = 20 နဲ့ 5 × 4 = 20။ 20 + 20 = 40။ ဒါကြောင့် 10 × 4 = 40။","hint":"4 စီ 10 ကြိမ် ရေပါ။"},"th":{"prompt":"10 × 4 เท่ากับเท่าไร","explanation":"10 × 4 หมายถึง 10 กลุ่ม กลุ่มละ 4 แยกคิด: 5 × 4 = 20 และ 5 × 4 = 20 20 + 20 = 40 ดังนั้น 10 × 4 = 40","hint":"นับทีละ 4 จำนวน 10 ครั้ง"}}'::jsonb),
  ('46593594-94f2-40dd-a9f3-032a17ace6a3', 'f38d59d0-1246-4c79-ac8c-e042171c4c93', 'missing_number', 'What number goes in the box?', '{"kind":"equation","parts":["5","×",null,"=","30"]}'::jsonb, '{"value":"6"}'::jsonb, null, 'Count in 5s until you reach 30: that takes 6 steps. So 5 × 6 = 30. Check: 30 ÷ 5 = 6.', 'How many 5s make 30?', 2, 10, 3, true, '{"my":{"prompt":"အကွက်ထဲမှာ ဘယ်ဂဏန်း ဝင်မလဲ။","explanation":"30 ရောက်တဲ့အထိ 5 စီ ရေပါ - 6 လှမ်း ကြာတယ်။ ဒါကြောင့် 5 × 6 = 30။ စစ်ကြည့်ပါ - 30 ÷ 5 = 6။","hint":"5 ဘယ်နှခု ပေါင်းရင် 30 ဖြစ်လဲ။"},"th":{"prompt":"ตัวเลขใดอยู่ในกล่อง","explanation":"นับทีละ 5 จนถึง 30: ใช้ 6 ครั้ง ดังนั้น 5 × 6 = 30 ตรวจ: 30 ÷ 5 = 6","hint":"5 กี่ตัวรวมกันได้ 30"}}'::jsonb),
  ('47593727-93f2-4f4a-aaf3-04bd16ace510', 'f38d59d0-1246-4c79-ac8c-e042171c4c93', 'numeric', 'What is 4 × 8?', null, '{"value":"32"}'::jsonb, null, '4 × 8 means 4 groups of 8. Count in 8s: 8, 16, 24, 32. So 4 × 8 = 32.', 'Count in 8s, 4 times.', 2, 10, 4, true, '{"my":{"prompt":"4 × 8 က ဘယ်လောက်လဲ။","explanation":"4 × 8 ဆိုတာ 8 စီပါတဲ့ အုပ်စု 4 စုပါ။ 8 စီ ရေပါ - 8, 16, 24, 32။ ဒါကြောင့် 4 × 8 = 32။","hint":"8 စီ 4 ကြိမ် ရေပါ။"},"th":{"prompt":"4 × 8 เท่ากับเท่าไร","explanation":"4 × 8 หมายถึง 4 กลุ่ม กลุ่มละ 8 นับทีละ 8: 8, 16, 24, 32 ดังนั้น 4 × 8 = 32","hint":"นับทีละ 8 จำนวน 4 ครั้ง"}}'::jsonb),
  ('4459326e-8ef2-476b-a3f2-f9b81dacf015', 'f38d59d0-1246-4c79-ac8c-e042171c4c93', 'missing_number', 'What number goes in the box?', '{"kind":"equation","parts":["4","×",null,"=","16"]}'::jsonb, '{"value":"4"}'::jsonb, null, 'Count in 4s until you reach 16: that takes 4 steps. So 4 × 4 = 16. Check: 16 ÷ 4 = 4.', 'How many 4s make 16?', 2, 10, 5, true, '{"my":{"prompt":"အကွက်ထဲမှာ ဘယ်ဂဏန်း ဝင်မလဲ။","explanation":"16 ရောက်တဲ့အထိ 4 စီ ရေပါ - 4 လှမ်း ကြာတယ်။ ဒါကြောင့် 4 × 4 = 16။ စစ်ကြည့်ပါ - 16 ÷ 4 = 4။","hint":"4 ဘယ်နှခု ပေါင်းရင် 16 ဖြစ်လဲ။"},"th":{"prompt":"ตัวเลขใดอยู่ในกล่อง","explanation":"นับทีละ 4 จนถึง 16: ใช้ 4 ครั้ง ดังนั้น 4 × 4 = 16 ตรวจ: 16 ÷ 4 = 4","hint":"4 กี่ตัวรวมกันได้ 16"}}'::jsonb),
  ('ac1cf2b0-3d8a-48cd-bbf7-ff42e83570e7', 'bc10714a-1f18-451b-9df2-26e4643fb37d', 'numeric', 'Omar has 6 tables with 4 chairs in each. How many chairs are there altogether?', null, '{"value":"24"}'::jsonb, null, 'There are 6 equal groups of 4, so multiply: 6 × 4 = 24. There are 24 chairs.', 'Equal groups means you can multiply.', 3, 10, 1, true, '{"my":{"prompt":"မင်း မှာ စားပွဲ 6 လုံး ရှိပြီး တစ်လုံးစီမှာ ကုလားထိုင် 4 လုံး ပါတယ်။ ကုလားထိုင် စုစုပေါင်း ဘယ်နှလုံး ရှိလဲ။","explanation":"4 စီပါတဲ့ အုပ်စု 6 စု ရှိလို့ မြှောက်ပါ - 6 × 4 = 24။ ကုလားထိုင် 24 လုံး ရှိတယ်။","hint":"အုပ်စုတွေ ညီနေရင် မြှောက်လို့ ရတယ်။"},"th":{"prompt":"กล้ามีโต๊ะ 6 ตัว แต่ละตัวมีเก้าอี้ 4 ตัว มีเก้าอี้ทั้งหมดกี่ตัว","explanation":"มี 6 กลุ่มเท่า ๆ กัน กลุ่มละ 4 จึงคูณ: 6 × 4 = 24 มีเก้าอี้ 24 ตัว","hint":"กลุ่มที่เท่ากันแปลว่าใช้การคูณได้"}}'::jsonb),
  ('ad1cf443-3c8a-473a-bcf8-00d5e7356f54', 'bc10714a-1f18-451b-9df2-26e4643fb37d', 'numeric', 'Zara has 5 bags with 4 oranges in each. How many oranges are there altogether?', null, '{"value":"20"}'::jsonb, null, 'There are 5 equal groups of 4, so multiply: 5 × 4 = 20. There are 20 oranges.', 'Equal groups means you can multiply.', 3, 10, 2, true, '{"my":{"prompt":"နန္ဒာ မှာ အိတ် 5 လုံး ရှိပြီး တစ်လုံးစီမှာ လိမ္မော်သီး 4 လုံး ပါတယ်။ လိမ္မော်သီး စုစုပေါင်း ဘယ်နှလုံး ရှိလဲ။","explanation":"4 စီပါတဲ့ အုပ်စု 5 စု ရှိလို့ မြှောက်ပါ - 5 × 4 = 20။ လိမ္မော်သီး 20 လုံး ရှိတယ်။","hint":"အုပ်စုတွေ ညီနေရင် မြှောက်လို့ ရတယ်။"},"th":{"prompt":"แพรวมีถุง 5 ถุง แต่ละถุงมีส้ม 4 ผล มีส้มทั้งหมดกี่ผล","explanation":"มี 5 กลุ่มเท่า ๆ กัน กลุ่มละ 4 จึงคูณ: 5 × 4 = 20 มีส้ม 20 ผล","hint":"กลุ่มที่เท่ากันแปลว่าใช้การคูณได้"}}'::jsonb),
  ('ae1cf5d6-3b8a-45a7-b9f7-fc1cea35740d', 'bc10714a-1f18-451b-9df2-26e4643fb37d', 'numeric', 'What is 8 × 9?', null, '{"value":"72"}'::jsonb, null, '8 × 9 means 8 groups of 9. Split it up: 5 × 9 = 45 and 3 × 9 = 27. 45 + 27 = 72. So 8 × 9 = 72.', 'Count in 9s, 8 times.', 3, 10, 3, true, '{"my":{"prompt":"8 × 9 က ဘယ်လောက်လဲ။","explanation":"8 × 9 ဆိုတာ 9 စီပါတဲ့ အုပ်စု 8 စုပါ။ ခွဲလိုက်ပါ - 5 × 9 = 45 နဲ့ 3 × 9 = 27။ 45 + 27 = 72။ ဒါကြောင့် 8 × 9 = 72။","hint":"9 စီ 8 ကြိမ် ရေပါ။"},"th":{"prompt":"8 × 9 เท่ากับเท่าไร","explanation":"8 × 9 หมายถึง 8 กลุ่ม กลุ่มละ 9 แยกคิด: 5 × 9 = 45 และ 3 × 9 = 27 45 + 27 = 72 ดังนั้น 8 × 9 = 72","hint":"นับทีละ 9 จำนวน 8 ครั้ง"}}'::jsonb),
  ('af1cf769-3a8a-4414-baf7-fdafe935727a', 'bc10714a-1f18-451b-9df2-26e4643fb37d', 'numeric', 'Kai has 8 tables with 3 chairs in each. How many chairs are there altogether?', null, '{"value":"24"}'::jsonb, null, 'There are 8 equal groups of 3, so multiply: 8 × 3 = 24. There are 24 chairs.', 'Equal groups means you can multiply.', 3, 10, 4, true, '{"my":{"prompt":"ကောင်း မှာ စားပွဲ 8 လုံး ရှိပြီး တစ်လုံးစီမှာ ကုလားထိုင် 3 လုံး ပါတယ်။ ကုလားထိုင် စုစုပေါင်း ဘယ်နှလုံး ရှိလဲ။","explanation":"3 စီပါတဲ့ အုပ်စု 8 စု ရှိလို့ မြှောက်ပါ - 8 × 3 = 24။ ကုလားထိုင် 24 လုံး ရှိတယ်။","hint":"အုပ်စုတွေ ညီနေရင် မြှောက်လို့ ရတယ်။"},"th":{"prompt":"โอ๊ตมีโต๊ะ 8 ตัว แต่ละตัวมีเก้าอี้ 3 ตัว มีเก้าอี้ทั้งหมดกี่ตัว","explanation":"มี 8 กลุ่มเท่า ๆ กัน กลุ่มละ 3 จึงคูณ: 8 × 3 = 24 มีเก้าอี้ 24 ตัว","hint":"กลุ่มที่เท่ากันแปลว่าใช้การคูณได้"}}'::jsonb),
  ('b01cf8fc-398a-4281-b7f7-f8f6e4356a9b', 'bc10714a-1f18-451b-9df2-26e4643fb37d', 'numeric', 'Noah has 9 bags with 9 oranges in each. How many oranges are there altogether?', null, '{"value":"81"}'::jsonb, null, 'There are 9 equal groups of 9, so multiply: 9 × 9 = 81. There are 81 oranges.', 'Equal groups means you can multiply.', 3, 10, 5, true, '{"my":{"prompt":"ကျော် မှာ အိတ် 9 လုံး ရှိပြီး တစ်လုံးစီမှာ လိမ္မော်သီး 9 လုံး ပါတယ်။ လိမ္မော်သီး စုစုပေါင်း ဘယ်နှလုံး ရှိလဲ။","explanation":"9 စီပါတဲ့ အုပ်စု 9 စု ရှိလို့ မြှောက်ပါ - 9 × 9 = 81။ လိမ္မော်သီး 81 လုံး ရှိတယ်။","hint":"အုပ်စုတွေ ညီနေရင် မြှောက်လို့ ရတယ်။"},"th":{"prompt":"ภูมิมีถุง 9 ถุง แต่ละถุงมีส้ม 9 ผล มีส้มทั้งหมดกี่ผล","explanation":"มี 9 กลุ่มเท่า ๆ กัน กลุ่มละ 9 จึงคูณ: 9 × 9 = 81 มีส้ม 81 ผล","hint":"กลุ่มที่เท่ากันแปลว่าใช้การคูณได้"}}'::jsonb),
  ('f1e00c06-3aae-4eb9-9924-3cb028844a2b', '8bc01bec-fd00-45af-bc00-45ce640f51a1', 'numeric', 'Share 12 shells equally between 3 friends. How many does each friend get?', '{"kind":"objects","object":"shell","groups":[12]}'::jsonb, '{"value":"4"}'::jsonb, null, 'Give one to each friend in turn until they are all gone. 12 ÷ 3 = 4, because 3 × 4 = 12.', 'Which number times 3 makes 12?', 1, 10, 1, true, '{"my":{"prompt":"ခရုခွံ 12 ခု ကို သူငယ်ချင်း 3 ယောက်ကြား ညီညီမျှမျှ ခွဲဝေပါ။ သူငယ်ချင်း တစ်ယောက်စီ ဘယ်နှခု ရလဲ။","explanation":"ကုန်သွားတဲ့အထိ သူငယ်ချင်း တစ်ယောက်ကို တစ်ခုစီ အလှည့်ကျ ပေးပါ။ 3 × 4 = 12 ဖြစ်လို့ 12 ÷ 3 = 4။","hint":"ဘယ်ဂဏန်းကို 3 နဲ့ မြှောက်ရင် 12 ဖြစ်လဲ။"},"th":{"prompt":"แบ่งเปลือกหอย 12 อัน ให้เพื่อน 3 คนเท่า ๆ กัน เพื่อนแต่ละคนได้กี่อัน","explanation":"แจกให้เพื่อนทีละคนคนละหนึ่งจนหมด 12 ÷ 3 = 4 เพราะ 3 × 4 = 12","hint":"จำนวนใดคูณ 3 ได้ 12"}}'::jsonb),
  ('f2e00d99-39ae-4d26-9a24-3e4327844898', '8bc01bec-fd00-45af-bc00-45ce640f51a1', 'numeric', 'Share 20 cookies equally between 4 friends. How many does each friend get?', '{"kind":"objects","object":"cookie","groups":[20]}'::jsonb, '{"value":"5"}'::jsonb, null, 'Give one to each friend in turn until they are all gone. 20 ÷ 4 = 5, because 4 × 5 = 20.', 'Which number times 4 makes 20?', 1, 10, 2, true, '{"my":{"prompt":"ကွတ်ကီး 20 ခု ကို သူငယ်ချင်း 4 ယောက်ကြား ညီညီမျှမျှ ခွဲဝေပါ။ သူငယ်ချင်း တစ်ယောက်စီ ဘယ်နှခု ရလဲ။","explanation":"ကုန်သွားတဲ့အထိ သူငယ်ချင်း တစ်ယောက်ကို တစ်ခုစီ အလှည့်ကျ ပေးပါ။ 4 × 5 = 20 ဖြစ်လို့ 20 ÷ 4 = 5။","hint":"ဘယ်ဂဏန်းကို 4 နဲ့ မြှောက်ရင် 20 ဖြစ်လဲ။"},"th":{"prompt":"แบ่งคุกกี้ 20 ชิ้น ให้เพื่อน 4 คนเท่า ๆ กัน เพื่อนแต่ละคนได้กี่ชิ้น","explanation":"แจกให้เพื่อนทีละคนคนละหนึ่งจนหมด 20 ÷ 4 = 5 เพราะ 4 × 5 = 20","hint":"จำนวนใดคูณ 4 ได้ 20"}}'::jsonb),
  ('efe008e0-38ae-4b93-9b24-3fd62a844d51', '8bc01bec-fd00-45af-bc00-45ce640f51a1', 'numeric', 'What is 4 ÷ 2?', null, '{"value":"2"}'::jsonb, null, 'Think of the times table: 2 × 2 = 4. So 4 ÷ 2 = 2.', '2 times what makes 4?', 1, 10, 3, true, '{"my":{"prompt":"4 ÷ 2 က ဘယ်လောက်လဲ။","explanation":"အမြှောက်ဇယားကို စဉ်းစားပါ - 2 × 2 = 4။ ဒါကြောင့် 4 ÷ 2 = 2။","hint":"2 ကို ဘာနဲ့ မြှောက်ရင် 4 ဖြစ်လဲ။"},"th":{"prompt":"4 ÷ 2 เท่ากับเท่าไร","explanation":"นึกถึงสูตรคูณ: 2 × 2 = 4 ดังนั้น 4 ÷ 2 = 2","hint":"2 คูณอะไรได้ 4"}}'::jsonb),
  ('f0e00a73-37ae-4a00-9c24-416929844bbe', '8bc01bec-fd00-45af-bc00-45ce640f51a1', 'numeric', 'Share 12 apples equally between 4 friends. How many does each friend get?', '{"kind":"objects","object":"apple","groups":[12]}'::jsonb, '{"value":"3"}'::jsonb, null, 'Give one to each friend in turn until they are all gone. 12 ÷ 4 = 3, because 4 × 3 = 12.', 'Which number times 4 makes 12?', 1, 10, 4, true, '{"my":{"prompt":"ပန်းသီး 12 လုံး ကို သူငယ်ချင်း 4 ယောက်ကြား ညီညီမျှမျှ ခွဲဝေပါ။ သူငယ်ချင်း တစ်ယောက်စီ ဘယ်နှလုံး ရလဲ။","explanation":"ကုန်သွားတဲ့အထိ သူငယ်ချင်း တစ်ယောက်ကို တစ်ခုစီ အလှည့်ကျ ပေးပါ။ 4 × 3 = 12 ဖြစ်လို့ 12 ÷ 4 = 3။","hint":"ဘယ်ဂဏန်းကို 4 နဲ့ မြှောက်ရင် 12 ဖြစ်လဲ။"},"th":{"prompt":"แบ่งแอปเปิล 12 ผล ให้เพื่อน 4 คนเท่า ๆ กัน เพื่อนแต่ละคนได้กี่ผล","explanation":"แจกให้เพื่อนทีละคนคนละหนึ่งจนหมด 12 ÷ 4 = 3 เพราะ 4 × 3 = 12","hint":"จำนวนใดคูณ 4 ได้ 12"}}'::jsonb),
  ('f5e01252-3eae-4505-9d24-42fc2c845077', '8bc01bec-fd00-45af-bc00-45ce640f51a1', 'numeric', 'What is 30 ÷ 5?', null, '{"value":"6"}'::jsonb, null, 'Think of the times table: 5 × 6 = 30. So 30 ÷ 5 = 6.', '5 times what makes 30?', 1, 10, 5, true, '{"my":{"prompt":"30 ÷ 5 က ဘယ်လောက်လဲ။","explanation":"အမြှောက်ဇယားကို စဉ်းစားပါ - 5 × 6 = 30။ ဒါကြောင့် 30 ÷ 5 = 6။","hint":"5 ကို ဘာနဲ့ မြှောက်ရင် 30 ဖြစ်လဲ။"},"th":{"prompt":"30 ÷ 5 เท่ากับเท่าไร","explanation":"นึกถึงสูตรคูณ: 5 × 6 = 30 ดังนั้น 30 ÷ 5 = 6","hint":"5 คูณอะไรได้ 30"}}'::jsonb),
  ('42661a73-ffe9-415a-8139-42d5bfa68074', 'ec33dba1-363b-4d64-8fde-59db59a9a286', 'numeric', 'What is 10 ÷ 5?', null, '{"value":"2"}'::jsonb, null, 'Think of the times table: 5 × 2 = 10. So 10 ÷ 5 = 2.', '5 times what makes 10?', 2, 10, 1, true, '{"my":{"prompt":"10 ÷ 5 က ဘယ်လောက်လဲ။","explanation":"အမြှောက်ဇယားကို စဉ်းစားပါ - 5 × 2 = 10။ ဒါကြောင့် 10 ÷ 5 = 2။","hint":"5 ကို ဘာနဲ့ မြှောက်ရင် 10 ဖြစ်လဲ။"},"th":{"prompt":"10 ÷ 5 เท่ากับเท่าไร","explanation":"นึกถึงสูตรคูณ: 5 × 2 = 10 ดังนั้น 10 ÷ 5 = 2","hint":"5 คูณอะไรได้ 10"}}'::jsonb),
  ('416618e0-00e9-42ed-8039-4142c0a68207', 'ec33dba1-363b-4d64-8fde-59db59a9a286', 'numeric', 'What is 27 ÷ 9?', null, '{"value":"3"}'::jsonb, null, 'Think of the times table: 9 × 3 = 27. So 27 ÷ 9 = 3.', '9 times what makes 27?', 2, 10, 2, true, '{"my":{"prompt":"27 ÷ 9 က ဘယ်လောက်လဲ။","explanation":"အမြှောက်ဇယားကို စဉ်းစားပါ - 9 × 3 = 27။ ဒါကြောင့် 27 ÷ 9 = 3။","hint":"9 ကို ဘာနဲ့ မြှောက်ရင် 27 ဖြစ်လဲ။"},"th":{"prompt":"27 ÷ 9 เท่ากับเท่าไร","explanation":"นึกถึงสูตรคูณ: 9 × 3 = 27 ดังนั้น 27 ÷ 9 = 3","hint":"9 คูณอะไรได้ 27"}}'::jsonb),
  ('44661d99-fde9-4e34-bf39-3fafc1a6839a', 'ec33dba1-363b-4d64-8fde-59db59a9a286', 'missing_number', 'What number goes in the box?', '{"kind":"equation","parts":["80","÷",null,"=","8"]}'::jsonb, '{"value":"10"}'::jsonb, null, '80 split into groups of the missing number makes 8. Since 8 × 10 = 80, the missing number is 10.', 'Think: 8 × what = 80?', 2, 10, 3, true, '{"my":{"prompt":"အကွက်ထဲမှာ ဘယ်ဂဏန်း ဝင်မလဲ။","explanation":"80 ကို ပျောက်နေတဲ့ ဂဏန်းစီ အုပ်စုခွဲရင် 8 စု ရတယ်။ 8 × 10 = 80 ဖြစ်လို့ ပျောက်နေတဲ့ ဂဏန်းက 10 ပါ။","hint":"စဉ်းစားပါ - 8 × ဘာ = 80။"},"th":{"prompt":"ตัวเลขใดอยู่ในกล่อง","explanation":"80 แบ่งเป็นกลุ่มละจำนวนที่หายไป ได้ 8 กลุ่ม เพราะ 8 × 10 = 80 จำนวนที่หายไปคือ 10","hint":"คิดว่า: 8 × อะไร = 80"}}'::jsonb),
  ('43661c06-fee9-4fc7-be39-3e1cc2a6852d', 'ec33dba1-363b-4d64-8fde-59db59a9a286', 'missing_number', 'What number goes in the box?', '{"kind":"equation","parts":["16","÷",null,"=","4"]}'::jsonb, '{"value":"4"}'::jsonb, null, '16 split into groups of the missing number makes 4. Since 4 × 4 = 16, the missing number is 4.', 'Think: 4 × what = 16?', 2, 10, 4, true, '{"my":{"prompt":"အကွက်ထဲမှာ ဘယ်ဂဏန်း ဝင်မလဲ။","explanation":"16 ကို ပျောက်နေတဲ့ ဂဏန်းစီ အုပ်စုခွဲရင် 4 စု ရတယ်။ 4 × 4 = 16 ဖြစ်လို့ ပျောက်နေတဲ့ ဂဏန်းက 4 ပါ။","hint":"စဉ်းစားပါ - 4 × ဘာ = 16။"},"th":{"prompt":"ตัวเลขใดอยู่ในกล่อง","explanation":"16 แบ่งเป็นกลุ่มละจำนวนที่หายไป ได้ 4 กลุ่ม เพราะ 4 × 4 = 16 จำนวนที่หายไปคือ 4","hint":"คิดว่า: 4 × อะไร = 16"}}'::jsonb),
  ('466620bf-fbe9-4b0e-bd39-3c89bba67a28', 'ec33dba1-363b-4d64-8fde-59db59a9a286', 'numeric', 'What is 45 ÷ 9?', null, '{"value":"5"}'::jsonb, null, 'Think of the times table: 9 × 5 = 45. So 45 ÷ 9 = 5.', '9 times what makes 45?', 2, 10, 5, true, '{"my":{"prompt":"45 ÷ 9 က ဘယ်လောက်လဲ။","explanation":"အမြှောက်ဇယားကို စဉ်းစားပါ - 9 × 5 = 45။ ဒါကြောင့် 45 ÷ 9 = 5။","hint":"9 ကို ဘာနဲ့ မြှောက်ရင် 45 ဖြစ်လဲ။"},"th":{"prompt":"45 ÷ 9 เท่ากับเท่าไร","explanation":"นึกถึงสูตรคูณ: 9 × 5 = 45 ดังนั้น 45 ÷ 9 = 5","hint":"9 คูณอะไรได้ 45"}}'::jsonb),
  ('a318a4ed-1029-4eac-9ab6-685b087867f2', 'e4f8c15f-f842-4302-a023-8c35cd602b50', 'numeric', 'Kai puts 30 books onto 6 shelves, with the same number on each shelf. How many books go on each shelf?', null, '{"value":"5"}'::jsonb, null, 'Sharing equally means divide: 30 ÷ 6 = 5, because 6 × 5 = 30.', 'Sharing equally means dividing.', 3, 10, 1, true, '{"my":{"prompt":"ကောင်း က စာအုပ် 30 အုပ်ကို စင် 6 ခုပေါ်မှာ တစ်ခုစီ အရေအတွက် တူအောင် တင်တယ်။ စင်တစ်ခုစီမှာ စာအုပ် ဘယ်နှအုပ် ရှိလဲ။","explanation":"ညီညီမျှမျှ ခွဲဝေတာက စားခြင်းပါ - 6 × 5 = 30 ဖြစ်လို့ 30 ÷ 6 = 5။","hint":"ညီညီမျှမျှ ခွဲဝေတာက စားခြင်းပါ။"},"th":{"prompt":"โอ๊ตวางหนังสือ 30 เล่มบนชั้น 6 ชั้น ชั้นละเท่า ๆ กัน แต่ละชั้นมีหนังสือกี่เล่ม","explanation":"การแบ่งเท่า ๆ กันคือการหาร: 30 ÷ 6 = 5 เพราะ 6 × 5 = 30","hint":"การแบ่งเท่า ๆ กันคือการหาร"}}'::jsonb),
  ('a218a35a-1129-403f-99b6-66c809786985', 'e4f8c15f-f842-4302-a023-8c35cd602b50', 'numeric', '16 children make teams of 3. How many full teams can they make?', null, '{"value":"5"}'::jsonb, null, '16 ÷ 3 = 5 remainder 1, because 3 × 5 = 15 and 16 − 15 = 1. So there are 5 full teams and 1 child left over.', 'Count in 3s without going past 16.', 3, 10, 2, true, '{"my":{"prompt":"ကလေး 16 ယောက်က 3 ယောက်စီ အသင်းဖွဲ့တယ်။ အသင်းပြည့် ဘယ်နှသင်း ဖွဲ့နိုင်လဲ။","explanation":"3 × 5 = 15 နဲ့ 16 − 15 = 1 ဖြစ်လို့ 16 ÷ 3 = 5 အကြွင်း 1။ ဒါကြောင့် အသင်းပြည့် 5 သင်းနဲ့ ကလေး 1 ယောက် ကျန်တယ်။","hint":"16 ကို မကျော်ဘဲ 3 စီ ရေပါ။"},"th":{"prompt":"เด็ก 16 คนจัดทีม ทีมละ 3 คน จัดได้ทีมเต็มกี่ทีม","explanation":"16 ÷ 3 = 5 เศษ 1 เพราะ 3 × 5 = 15 และ 16 − 15 = 1 จึงได้ทีมเต็ม 5 ทีม และเหลือเด็ก 1 คน","hint":"นับทีละ 3 โดยไม่เกิน 16"}}'::jsonb),
  ('a118a1c7-1229-41d2-9cb6-6b81067864cc', 'e4f8c15f-f842-4302-a023-8c35cd602b50', 'numeric', 'Ava puts 18 books onto 6 shelves, with the same number on each shelf. How many books go on each shelf?', null, '{"value":"3"}'::jsonb, null, 'Sharing equally means divide: 18 ÷ 6 = 3, because 6 × 3 = 18.', 'Sharing equally means dividing.', 3, 10, 3, true, '{"my":{"prompt":"သီရိ က စာအုပ် 18 အုပ်ကို စင် 6 ခုပေါ်မှာ တစ်ခုစီ အရေအတွက် တူအောင် တင်တယ်။ စင်တစ်ခုစီမှာ စာအုပ် ဘယ်နှအုပ် ရှိလဲ။","explanation":"ညီညီမျှမျှ ခွဲဝေတာက စားခြင်းပါ - 6 × 3 = 18 ဖြစ်လို့ 18 ÷ 6 = 3။","hint":"ညီညီမျှမျှ ခွဲဝေတာက စားခြင်းပါ။"},"th":{"prompt":"ฝนวางหนังสือ 18 เล่มบนชั้น 6 ชั้น ชั้นละเท่า ๆ กัน แต่ละชั้นมีหนังสือกี่เล่ม","explanation":"การแบ่งเท่า ๆ กันคือการหาร: 18 ÷ 6 = 3 เพราะ 6 × 3 = 18","hint":"การแบ่งเท่า ๆ กันคือการหาร"}}'::jsonb),
  ('a018a034-1329-4365-9bb6-69ee0778665f', 'e4f8c15f-f842-4302-a023-8c35cd602b50', 'numeric', '20 children make teams of 3. How many full teams can they make?', null, '{"value":"6"}'::jsonb, null, '20 ÷ 3 = 6 remainder 2, because 3 × 6 = 18 and 20 − 18 = 2. So there are 6 full teams and 2 children left over.', 'Count in 3s without going past 20.', 3, 10, 4, true, '{"my":{"prompt":"ကလေး 20 ယောက်က 3 ယောက်စီ အသင်းဖွဲ့တယ်။ အသင်းပြည့် ဘယ်နှသင်း ဖွဲ့နိုင်လဲ။","explanation":"3 × 6 = 18 နဲ့ 20 − 18 = 2 ဖြစ်လို့ 20 ÷ 3 = 6 အကြွင်း 2။ ဒါကြောင့် အသင်းပြည့် 6 သင်းနဲ့ ကလေး 2 ယောက် ကျန်တယ်။","hint":"20 ကို မကျော်ဘဲ 3 စီ ရေပါ။"},"th":{"prompt":"เด็ก 20 คนจัดทีม ทีมละ 3 คน จัดได้ทีมเต็มกี่ทีม","explanation":"20 ÷ 3 = 6 เศษ 2 เพราะ 3 × 6 = 18 และ 20 − 18 = 2 จึงได้ทีมเต็ม 6 ทีม และเหลือเด็ก 2 คน","hint":"นับทีละ 3 โดยไม่เกิน 20"}}'::jsonb),
  ('9f189ea1-0c29-4860-9eb6-6ea7047861a6', 'e4f8c15f-f842-4302-a023-8c35cd602b50', 'numeric', '35 children make teams of 4. How many full teams can they make?', null, '{"value":"8"}'::jsonb, null, '35 ÷ 4 = 8 remainder 3, because 4 × 8 = 32 and 35 − 32 = 3. So there are 8 full teams and 3 children left over.', 'Count in 4s without going past 35.', 3, 10, 5, true, '{"my":{"prompt":"ကလေး 35 ယောက်က 4 ယောက်စီ အသင်းဖွဲ့တယ်။ အသင်းပြည့် ဘယ်နှသင်း ဖွဲ့နိုင်လဲ။","explanation":"4 × 8 = 32 နဲ့ 35 − 32 = 3 ဖြစ်လို့ 35 ÷ 4 = 8 အကြွင်း 3။ ဒါကြောင့် အသင်းပြည့် 8 သင်းနဲ့ ကလေး 3 ယောက် ကျန်တယ်။","hint":"35 ကို မကျော်ဘဲ 4 စီ ရေပါ။"},"th":{"prompt":"เด็ก 35 คนจัดทีม ทีมละ 4 คน จัดได้ทีมเต็มกี่ทีม","explanation":"35 ÷ 4 = 8 เศษ 3 เพราะ 4 × 8 = 32 และ 35 − 32 = 3 จึงได้ทีมเต็ม 8 ทีม และเหลือเด็ก 3 คน","hint":"นับทีละ 4 โดยไม่เกิน 35"}}'::jsonb),
  ('23c1a460-547a-4ed5-b425-146ec7301133', '93be7b9a-dedb-460b-8ff6-9458942c9d99', 'multiple_choice', 'What fraction of the bar is shaded?', '{"kind":"fraction_bar","parts":3,"shaded":2}'::jsonb, '{"value":"a"}'::jsonb, '[{"id":"a","label":"2/3"},{"id":"b","label":"1/3"},{"id":"c","label":"2/4"},{"id":"d","label":"2/1"}]'::jsonb, 'The bar has 3 equal parts and 2 are shaded. The bottom number is the total parts, the top number is the shaded parts: 2/3.', 'Count all the parts, then count the shaded parts.', 1, 10, 1, true, '{"my":{"prompt":"ဘားရဲ့ ဘယ်အပိုင်းကိန်းကို အရောင်ခြယ်ထားလဲ။","explanation":"ဘားမှာ အပိုင်းညီ 3 ပိုင်း ရှိပြီး 2 ပိုင်းကို အရောင်ခြယ်ထားတယ်။ အောက်ဂဏန်းက အပိုင်း စုစုပေါင်း၊ အပေါ်ဂဏန်းက အရောင်ခြယ်ထားတဲ့ အပိုင်းပါ - 2/3။","hint":"အပိုင်းအားလုံးကို ရေပြီး အရောင်ခြယ်ထားတဲ့ အပိုင်းတွေကို ရေပါ။"},"th":{"prompt":"แถบนี้ระบายสีไปเศษส่วนเท่าไร","explanation":"แถบมี 3 ส่วนเท่า ๆ กัน ระบายสี 2 ส่วน ตัวส่วนคือจำนวนส่วนทั้งหมด ตัวเศษคือส่วนที่ระบายสี: 2/3","hint":"นับส่วนทั้งหมด แล้วนับส่วนที่ระบายสี"}}'::jsonb),
  ('24c1a5f3-537a-4d42-b525-1601c6300fa0', '93be7b9a-dedb-460b-8ff6-9458942c9d99', 'multiple_choice', 'What fraction of the bar is shaded?', '{"kind":"fraction_bar","parts":5,"shaded":1}'::jsonb, '{"value":"a"}'::jsonb, '[{"id":"a","label":"1/5"},{"id":"b","label":"1/4"},{"id":"c","label":"4/5"},{"id":"d","label":"1/6"}]'::jsonb, 'The bar has 5 equal parts and 1 is shaded. The bottom number is the total parts, the top number is the shaded parts: 1/5.', 'Count all the parts, then count the shaded parts.', 1, 10, 2, true, '{"my":{"prompt":"ဘားရဲ့ ဘယ်အပိုင်းကိန်းကို အရောင်ခြယ်ထားလဲ။","explanation":"ဘားမှာ အပိုင်းညီ 5 ပိုင်း ရှိပြီး 1 ပိုင်းကို အရောင်ခြယ်ထားတယ်။ အောက်ဂဏန်းက အပိုင်း စုစုပေါင်း၊ အပေါ်ဂဏန်းက အရောင်ခြယ်ထားတဲ့ အပိုင်းပါ - 1/5။","hint":"အပိုင်းအားလုံးကို ရေပြီး အရောင်ခြယ်ထားတဲ့ အပိုင်းတွေကို ရေပါ။"},"th":{"prompt":"แถบนี้ระบายสีไปเศษส่วนเท่าไร","explanation":"แถบมี 5 ส่วนเท่า ๆ กัน ระบายสี 1 ส่วน ตัวส่วนคือจำนวนส่วนทั้งหมด ตัวเศษคือส่วนที่ระบายสี: 1/5","hint":"นับส่วนทั้งหมด แล้วนับส่วนที่ระบายสี"}}'::jsonb),
  ('25c1a786-527a-4baf-b225-1148c9301459', '93be7b9a-dedb-460b-8ff6-9458942c9d99', 'multiple_choice', 'Which fraction means one half?', null, '{"value":"c"}'::jsonb, '[{"id":"a","label":"2/1"},{"id":"b","label":"1/3"},{"id":"c","label":"1/2"},{"id":"d","label":"2/2"}]'::jsonb, 'One half means 1 out of 2 equal parts, which we write as 1/2. 2/2 is a whole, and 1/3 is one third.', 'How many equal parts make halves?', 1, 10, 3, true, '{"my":{"prompt":"ဘယ်အပိုင်းကိန်းက တစ်ဝက်ကို ဆိုလိုလဲ။","explanation":"တစ်ဝက်ဆိုတာ အပိုင်းညီ 2 ပိုင်းထဲက 1 ပိုင်းပါ၊ 1/2 လို့ ရေးတယ်။ 2/2 က တစ်ခုလုံးဖြစ်ပြီး 1/3 က သုံးပုံတစ်ပုံပါ။","hint":"တစ်ဝက်တွေ ရဖို့ အပိုင်းညီ ဘယ်နှပိုင်း လိုလဲ။"},"th":{"prompt":"เศษส่วนใดหมายถึงครึ่งหนึ่ง","explanation":"ครึ่งหนึ่งคือ 1 ส่วนจาก 2 ส่วนเท่า ๆ กัน เขียนเป็น 1/2 ส่วน 2/2 คือทั้งหมด และ 1/3 คือหนึ่งในสาม","hint":"ต้องแบ่งเป็นกี่ส่วนเท่า ๆ กันจึงได้ครึ่ง"}}'::jsonb),
  ('26c1a919-517a-4a1c-b325-12dbc83012c6', '93be7b9a-dedb-460b-8ff6-9458942c9d99', 'multiple_choice', 'What fraction of the bar is shaded?', '{"kind":"fraction_bar","parts":6,"shaded":4}'::jsonb, '{"value":"c"}'::jsonb, '[{"id":"a","label":"4/7"},{"id":"b","label":"2/6"},{"id":"c","label":"4/6"},{"id":"d","label":"4/2"}]'::jsonb, 'The bar has 6 equal parts and 4 are shaded. The bottom number is the total parts, the top number is the shaded parts: 4/6.', 'Count all the parts, then count the shaded parts.', 1, 10, 4, true, '{"my":{"prompt":"ဘားရဲ့ ဘယ်အပိုင်းကိန်းကို အရောင်ခြယ်ထားလဲ။","explanation":"ဘားမှာ အပိုင်းညီ 6 ပိုင်း ရှိပြီး 4 ပိုင်းကို အရောင်ခြယ်ထားတယ်။ အောက်ဂဏန်းက အပိုင်း စုစုပေါင်း၊ အပေါ်ဂဏန်းက အရောင်ခြယ်ထားတဲ့ အပိုင်းပါ - 4/6။","hint":"အပိုင်းအားလုံးကို ရေပြီး အရောင်ခြယ်ထားတဲ့ အပိုင်းတွေကို ရေပါ။"},"th":{"prompt":"แถบนี้ระบายสีไปเศษส่วนเท่าไร","explanation":"แถบมี 6 ส่วนเท่า ๆ กัน ระบายสี 4 ส่วน ตัวส่วนคือจำนวนส่วนทั้งหมด ตัวเศษคือส่วนที่ระบายสี: 4/6","hint":"นับส่วนทั้งหมด แล้วนับส่วนที่ระบายสี"}}'::jsonb),
