  ('41c4da34-6b12-48e5-8fd8-10e248179b5b', '25358f2e-7580-4cd3-b3c3-0e24d65947f1', 'numeric', 'What is 1/4 of 20?', null, '{"value":"5"}'::jsonb, null, 'Split 20 into 4 equal groups: 20 ÷ 4 = 5. So 1/4 of 20 is 5.', 'Start by dividing 20 by 4.', 2, 10, 1, true, '{"my":{"prompt":"20 ရဲ့ 1/4 က ဘယ်လောက်လဲ။","explanation":"20 ကို အုပ်စုညီ 4 စု ခွဲပါ - 20 ÷ 4 = 5။ ဒါကြောင့် 20 ရဲ့ 1/4 က 5 ပါ။","hint":"20 ကို 4 နဲ့ စားခြင်းဖြင့် စပါ။"},"th":{"prompt":"1/4 ของ 20 เท่ากับเท่าไร","explanation":"แบ่ง 20 เป็น 4 กลุ่มเท่า ๆ กัน: 20 ÷ 4 = 5 ดังนั้น 1/4 ของ 20 คือ 5","hint":"เริ่มจากนำ 20 หารด้วย 4"}}'::jsonb),
  ('42c4dbc7-6a12-4752-90d8-1275471799c8', '25358f2e-7580-4cd3-b3c3-0e24d65947f1', 'numeric', 'What is 1/3 of 15?', null, '{"value":"5"}'::jsonb, null, 'Split 15 into 3 equal groups: 15 ÷ 3 = 5. So 1/3 of 15 is 5.', 'Start by dividing 15 by 3.', 2, 10, 2, true, '{"my":{"prompt":"15 ရဲ့ 1/3 က ဘယ်လောက်လဲ။","explanation":"15 ကို အုပ်စုညီ 3 စု ခွဲပါ - 15 ÷ 3 = 5။ ဒါကြောင့် 15 ရဲ့ 1/3 က 5 ပါ။","hint":"15 ကို 3 နဲ့ စားခြင်းဖြင့် စပါ။"},"th":{"prompt":"1/3 ของ 15 เท่ากับเท่าไร","explanation":"แบ่ง 15 เป็น 3 กลุ่มเท่า ๆ กัน: 15 ÷ 3 = 5 ดังนั้น 1/3 ของ 15 คือ 5","hint":"เริ่มจากนำ 15 หารด้วย 3"}}'::jsonb),
  ('43c4dd5a-6912-45bf-8dd8-0dbc4a179e81', '25358f2e-7580-4cd3-b3c3-0e24d65947f1', 'numeric', 'What is 1/3 of 18?', null, '{"value":"6"}'::jsonb, null, 'Split 18 into 3 equal groups: 18 ÷ 3 = 6. So 1/3 of 18 is 6.', 'Start by dividing 18 by 3.', 2, 10, 3, true, '{"my":{"prompt":"18 ရဲ့ 1/3 က ဘယ်လောက်လဲ။","explanation":"18 ကို အုပ်စုညီ 3 စု ခွဲပါ - 18 ÷ 3 = 6။ ဒါကြောင့် 18 ရဲ့ 1/3 က 6 ပါ။","hint":"18 ကို 3 နဲ့ စားခြင်းဖြင့် စပါ။"},"th":{"prompt":"1/3 ของ 18 เท่ากับเท่าไร","explanation":"แบ่ง 18 เป็น 3 กลุ่มเท่า ๆ กัน: 18 ÷ 3 = 6 ดังนั้น 1/3 ของ 18 คือ 6","hint":"เริ่มจากนำ 18 หารด้วย 3"}}'::jsonb),
  ('44c4deed-6812-442c-8ed8-0f4f49179cee', '25358f2e-7580-4cd3-b3c3-0e24d65947f1', 'numeric', 'What is 1/3 of 9?', null, '{"value":"3"}'::jsonb, null, 'Split 9 into 3 equal groups: 9 ÷ 3 = 3. So 1/3 of 9 is 3.', 'Start by dividing 9 by 3.', 2, 10, 4, true, '{"my":{"prompt":"9 ရဲ့ 1/3 က ဘယ်လောက်လဲ။","explanation":"9 ကို အုပ်စုညီ 3 စု ခွဲပါ - 9 ÷ 3 = 3။ ဒါကြောင့် 9 ရဲ့ 1/3 က 3 ပါ။","hint":"9 ကို 3 နဲ့ စားခြင်းဖြင့် စပါ။"},"th":{"prompt":"1/3 ของ 9 เท่ากับเท่าไร","explanation":"แบ่ง 9 เป็น 3 กลุ่มเท่า ๆ กัน: 9 ÷ 3 = 3 ดังนั้น 1/3 ของ 9 คือ 3","hint":"เริ่มจากนำ 9 หารด้วย 3"}}'::jsonb),
  ('3dc4d3e8-6712-4299-8bd8-0a964c17a1a7', '25358f2e-7580-4cd3-b3c3-0e24d65947f1', 'numeric', 'What is 1/2 of 20?', null, '{"value":"10"}'::jsonb, null, 'Split 20 into 2 equal groups: 20 ÷ 2 = 10. So 1/2 of 20 is 10.', 'Start by dividing 20 by 2.', 2, 10, 5, true, '{"my":{"prompt":"20 ရဲ့ 1/2 က ဘယ်လောက်လဲ။","explanation":"20 ကို အုပ်စုညီ 2 စု ခွဲပါ - 20 ÷ 2 = 10။ ဒါကြောင့် 20 ရဲ့ 1/2 က 10 ပါ။","hint":"20 ကို 2 နဲ့ စားခြင်းဖြင့် စပါ။"},"th":{"prompt":"1/2 ของ 20 เท่ากับเท่าไร","explanation":"แบ่ง 20 เป็น 2 กลุ่มเท่า ๆ กัน: 20 ÷ 2 = 10 ดังนั้น 1/2 ของ 20 คือ 10","hint":"เริ่มจากนำ 20 หารด้วย 2"}}'::jsonb),
  ('39bac9bf-74b9-4840-8e47-6f6d1f187fde', '099f9d3d-977c-42fe-9b24-92d3fc1f8c3c', 'compare', 'Which sign makes this true?', '{"kind":"compare","left":"2/7","right":"3/7"}'::jsonb, '{"value":"<"}'::jsonb, null, 'Both fractions have 7 equal parts. 3 parts is more than 2 parts, so 2/7 < 3/7.', 'When the bottom numbers match, compare the top numbers.', 3, 10, 1, true, '{"my":{"prompt":"ဘယ်သင်္ကေတက ဒါကို မှန်စေလဲ။","explanation":"အပိုင်းကိန်း နှစ်ခုလုံးမှာ အပိုင်းညီ 7 ပိုင်း ရှိတယ်။ 3 ပိုင်းက 2 ပိုင်းထက် များလို့ 2/7 < 3/7။","hint":"အောက်ဂဏန်းတွေ တူရင် အပေါ်ဂဏန်းတွေကို နှိုင်းယှဉ်ပါ။"},"th":{"prompt":"เครื่องหมายใดทำให้ถูกต้อง","explanation":"เศษส่วนทั้งสองมี 7 ส่วนเท่ากัน 3 ส่วนมากกว่า 2 ส่วน ดังนั้น 2/7 < 3/7","hint":"ถ้าตัวส่วนเท่ากัน ให้เปรียบเทียบตัวเศษ"}}'::jsonb),
  ('38bac82c-75b9-49d3-8d47-6dda20188171', '099f9d3d-977c-42fe-9b24-92d3fc1f8c3c', 'compare', 'Which sign makes this true?', '{"kind":"compare","left":"1/9","right":"1/6"}'::jsonb, '{"value":"<"}'::jsonb, null, 'When a whole is cut into more parts, each part is smaller. 1/9 is smaller than 1/6, so 1/9 < 1/6.', 'Would you rather have 1 slice of a cake cut into 2 or into 8?', 3, 10, 2, true, '{"my":{"prompt":"ဘယ်သင်္ကေတက ဒါကို မှန်စေလဲ။","explanation":"တစ်ခုလုံးကို အပိုင်းများများ ပိုင်းလေ အပိုင်းတစ်ခုစီ ငယ်လေပါ။ 1/9 က 1/6 ထက် ငယ်လို့ 1/9 < 1/6။","hint":"ကိတ်မုန့်ကို 2 ပိုင်း ပိုင်းတာထဲက တစ်ပိုင်းနဲ့ 8 ပိုင်း ပိုင်းတာထဲက တစ်ပိုင်း ဘယ်ဟာ ယူချင်လဲ။"},"th":{"prompt":"เครื่องหมายใดทำให้ถูกต้อง","explanation":"เมื่อแบ่งของทั้งหมดเป็นหลายส่วนขึ้น แต่ละส่วนจะเล็กลง 1/9 น้อยกว่า 1/6 ดังนั้น 1/9 < 1/6","hint":"อยากได้เค้ก 1 ชิ้นจากเค้กที่ตัดเป็น 2 ชิ้น หรือ 8 ชิ้น"}}'::jsonb),
  ('3bbacce5-76b9-4b66-8c47-6c471d187cb8', '099f9d3d-977c-42fe-9b24-92d3fc1f8c3c', 'compare', 'Which sign makes this true?', '{"kind":"compare","left":"4/9","right":"5/9"}'::jsonb, '{"value":"<"}'::jsonb, null, 'Both fractions have 9 equal parts. 5 parts is more than 4 parts, so 4/9 < 5/9.', 'When the bottom numbers match, compare the top numbers.', 3, 10, 3, true, '{"my":{"prompt":"ဘယ်သင်္ကေတက ဒါကို မှန်စေလဲ။","explanation":"အပိုင်းကိန်း နှစ်ခုလုံးမှာ အပိုင်းညီ 9 ပိုင်း ရှိတယ်။ 5 ပိုင်းက 4 ပိုင်းထက် များလို့ 4/9 < 5/9။","hint":"အောက်ဂဏန်းတွေ တူရင် အပေါ်ဂဏန်းတွေကို နှိုင်းယှဉ်ပါ။"},"th":{"prompt":"เครื่องหมายใดทำให้ถูกต้อง","explanation":"เศษส่วนทั้งสองมี 9 ส่วนเท่ากัน 5 ส่วนมากกว่า 4 ส่วน ดังนั้น 4/9 < 5/9","hint":"ถ้าตัวส่วนเท่ากัน ให้เปรียบเทียบตัวเศษ"}}'::jsonb),
  ('3abacb52-77b9-4cf9-8b47-6ab41e187e4b', '099f9d3d-977c-42fe-9b24-92d3fc1f8c3c', 'compare', 'Which sign makes this true?', '{"kind":"compare","left":"7/8","right":"5/8"}'::jsonb, '{"value":">"}'::jsonb, null, 'Both fractions have 8 equal parts. 7 parts is more than 5 parts, so 7/8 > 5/8.', 'When the bottom numbers match, compare the top numbers.', 3, 10, 4, true, '{"my":{"prompt":"ဘယ်သင်္ကေတက ဒါကို မှန်စေလဲ။","explanation":"အပိုင်းကိန်း နှစ်ခုလုံးမှာ အပိုင်းညီ 8 ပိုင်း ရှိတယ်။ 7 ပိုင်းက 5 ပိုင်းထက် များလို့ 7/8 > 5/8။","hint":"အောက်ဂဏန်းတွေ တူရင် အပေါ်ဂဏန်းတွေကို နှိုင်းယှဉ်ပါ။"},"th":{"prompt":"เครื่องหมายใดทำให้ถูกต้อง","explanation":"เศษส่วนทั้งสองมี 8 ส่วนเท่ากัน 7 ส่วนมากกว่า 5 ส่วน ดังนั้น 7/8 > 5/8","hint":"ถ้าตัวส่วนเท่ากัน ให้เปรียบเทียบตัวเศษ"}}'::jsonb),
  ('35bac373-78b9-4e8c-8a47-69212318862a', '099f9d3d-977c-42fe-9b24-92d3fc1f8c3c', 'compare', 'Which sign makes this true?', '{"kind":"compare","left":"1/5","right":"4/5"}'::jsonb, '{"value":"<"}'::jsonb, null, 'Both fractions have 5 equal parts. 4 parts is more than 1 parts, so 1/5 < 4/5.', 'When the bottom numbers match, compare the top numbers.', 3, 10, 5, true, '{"my":{"prompt":"ဘယ်သင်္ကေတက ဒါကို မှန်စေလဲ။","explanation":"အပိုင်းကိန်း နှစ်ခုလုံးမှာ အပိုင်းညီ 5 ပိုင်း ရှိတယ်။ 4 ပိုင်းက 1 ပိုင်းထက် များလို့ 1/5 < 4/5။","hint":"အောက်ဂဏန်းတွေ တူရင် အပေါ်ဂဏန်းတွေကို နှိုင်းယှဉ်ပါ။"},"th":{"prompt":"เครื่องหมายใดทำให้ถูกต้อง","explanation":"เศษส่วนทั้งสองมี 5 ส่วนเท่ากัน 4 ส่วนมากกว่า 1 ส่วน ดังนั้น 1/5 < 4/5","hint":"ถ้าตัวส่วนเท่ากัน ให้เปรียบเทียบตัวเศษ"}}'::jsonb),
  ('41a4ac6b-a41c-4e82-a0c6-ffc1bc8f7c00', 'd0f19b69-e5c7-45e4-adfb-245f51276442', 'multiple_choice', 'What time does the clock show?', '{"kind":"clock","hour":11,"minute":0}'::jsonb, '{"value":"d"}'::jsonb, '[{"id":"a","label":"11:30"},{"id":"b","label":"12:55"},{"id":"c","label":"10:00"},{"id":"d","label":"11:00"}]'::jsonb, 'The short hand points to 11, so the hour is 11. The long hand points to 12, which means exactly 11 o''clock. The time is 11:00.', 'Read the short hand for the hour, then the long hand for minutes.', 1, 10, 1, true, '{"my":{"prompt":"နာရီက ဘယ်အချိန်ကို ပြနေလဲ။","explanation":"လက်တံတိုက 11 ကို ညွှန်နေတယ်၊ ဒါကြောင့် နာရီက 11 ပါ။ လက်တံရှည်က 12 ကို ညွှန်နေလို့ 11 နာရီ တိတိပါ။ အချိန်က 11:00 ပါ။","hint":"နာရီအတွက် လက်တံတိုကို အရင်ဖတ်ပြီး မိနစ်အတွက် လက်တံရှည်ကို ဖတ်ပါ။"},"th":{"prompt":"นาฬิกาบอกเวลาเท่าไร","explanation":"เข็มสั้นชี้ที่ 11 ชั่วโมงจึงเป็น 11 เข็มยาวชี้ที่ 12 แปลว่า 11 นาฬิกาตรง เวลาคือ 11:00","hint":"อ่านเข็มสั้นเพื่อดูชั่วโมง แล้วอ่านเข็มยาวเพื่อดูนาที"}}'::jsonb),
  ('40a4aad8-a51c-4015-9fc6-fe2ebd8f7d93', 'd0f19b69-e5c7-45e4-adfb-245f51276442', 'multiple_choice', 'What time does the clock show?', '{"kind":"clock","hour":2,"minute":0}'::jsonb, '{"value":"c"}'::jsonb, '[{"id":"a","label":"12:10"},{"id":"b","label":"2:30"},{"id":"c","label":"2:00"},{"id":"d","label":"3:00"}]'::jsonb, 'The short hand points to 2, so the hour is 2. The long hand points to 12, which means exactly 2 o''clock. The time is 2:00.', 'Read the short hand for the hour, then the long hand for minutes.', 1, 10, 2, true, '{"my":{"prompt":"နာရီက ဘယ်အချိန်ကို ပြနေလဲ။","explanation":"လက်တံတိုက 2 ကို ညွှန်နေတယ်၊ ဒါကြောင့် နာရီက 2 ပါ။ လက်တံရှည်က 12 ကို ညွှန်နေလို့ 2 နာရီ တိတိပါ။ အချိန်က 2:00 ပါ။","hint":"နာရီအတွက် လက်တံတိုကို အရင်ဖတ်ပြီး မိနစ်အတွက် လက်တံရှည်ကို ဖတ်ပါ။"},"th":{"prompt":"นาฬิกาบอกเวลาเท่าไร","explanation":"เข็มสั้นชี้ที่ 2 ชั่วโมงจึงเป็น 2 เข็มยาวชี้ที่ 12 แปลว่า 2 นาฬิกาตรง เวลาคือ 2:00","hint":"อ่านเข็มสั้นเพื่อดูชั่วโมง แล้วอ่านเข็มยาวเพื่อดูนาที"}}'::jsonb),
  ('43a4af91-a21c-4b5c-9ec6-fc9bbe8f7f26', 'd0f19b69-e5c7-45e4-adfb-245f51276442', 'multiple_choice', 'What time does the clock show?', '{"kind":"clock","hour":3,"minute":45}'::jsonb, '{"value":"c"}'::jsonb, '[{"id":"a","label":"3:15"},{"id":"b","label":"9:15"},{"id":"c","label":"3:45"},{"id":"d","label":"4:45"}]'::jsonb, 'The short hand is between 3 and 4, so the hour is 3. The long hand points to 9. Each number is 5 minutes, so that is 9 × 5 = 45 minutes. The time is 3:45.', 'Read the short hand for the hour, then the long hand for minutes.', 1, 10, 3, true, '{"my":{"prompt":"နာရီက ဘယ်အချိန်ကို ပြနေလဲ။","explanation":"လက်တံတိုက 3 နဲ့ 4 ကြားမှာ ရှိတယ်၊ ဒါကြောင့် နာရီက 3 ပါ။ လက်တံရှည်က 9 ကို ညွှန်နေတယ်။ ဂဏန်းတစ်ခုစီက 5 မိနစ်ဖြစ်လို့ 9 × 5 = 45 မိနစ်ပါ။ အချိန်က 3:45 ပါ။","hint":"နာရီအတွက် လက်တံတိုကို အရင်ဖတ်ပြီး မိနစ်အတွက် လက်တံရှည်ကို ဖတ်ပါ။"},"th":{"prompt":"นาฬิกาบอกเวลาเท่าไร","explanation":"เข็มสั้นอยู่ระหว่าง 3 กับ 4 ชั่วโมงจึงเป็น 3 เข็มยาวชี้ที่ 9 แต่ละตัวเลขคือ 5 นาที จึงเป็น 9 × 5 = 45 นาที เวลาคือ 3:45","hint":"อ่านเข็มสั้นเพื่อดูชั่วโมง แล้วอ่านเข็มยาวเพื่อดูนาที"}}'::jsonb),
  ('42a4adfe-a31c-4cef-9dc6-fb08bf8f80b9', 'd0f19b69-e5c7-45e4-adfb-245f51276442', 'numeric', 'How many minutes are there in one hour?', null, '{"value":"60"}'::jsonb, null, 'In one hour the long hand goes all the way round the clock. That is 12 numbers × 5 minutes = 60 minutes.', 'Count in 5s all the way round the clock.', 1, 10, 4, true, '{"my":{"prompt":"တစ်နာရီမှာ မိနစ် ဘယ်လောက် ရှိလဲ။","explanation":"တစ်နာရီအတွင်း လက်တံရှည်က နာရီကို တစ်ပတ်လုံး ပတ်တယ်။ ဒါက ဂဏန်း 12 ခု × 5 မိနစ် = 60 မိနစ်ပါ။","hint":"နာရီကို တစ်ပတ်လုံး 5 စီ ရေပါ။"},"th":{"prompt":"หนึ่งชั่วโมงมีกี่นาที","explanation":"ในหนึ่งชั่วโมง เข็มยาวเดินรอบนาฬิกาหนึ่งรอบ นั่นคือ 12 ตัวเลข × 5 นาที = 60 นาที","hint":"นับทีละ 5 ไปรอบนาฬิกา"}}'::jsonb),
  ('45a4b2b7-a01c-4836-a4c7-060dc08f824c', 'd0f19b69-e5c7-45e4-adfb-245f51276442', 'multiple_choice', 'What time does the clock show?', '{"kind":"clock","hour":11,"minute":50}'::jsonb, '{"value":"d"}'::jsonb, '[{"id":"a","label":"11:20"},{"id":"b","label":"10:50"},{"id":"c","label":"12:50"},{"id":"d","label":"11:50"}]'::jsonb, 'The short hand is between 11 and 12, so the hour is 11. The long hand points to 10. Each number is 5 minutes, so that is 10 × 5 = 50 minutes. The time is 11:50.', 'Read the short hand for the hour, then the long hand for minutes.', 1, 10, 5, true, '{"my":{"prompt":"နာရီက ဘယ်အချိန်ကို ပြနေလဲ။","explanation":"လက်တံတိုက 11 နဲ့ 12 ကြားမှာ ရှိတယ်၊ ဒါကြောင့် နာရီက 11 ပါ။ လက်တံရှည်က 10 ကို ညွှန်နေတယ်။ ဂဏန်းတစ်ခုစီက 5 မိနစ်ဖြစ်လို့ 10 × 5 = 50 မိနစ်ပါ။ အချိန်က 11:50 ပါ။","hint":"နာရီအတွက် လက်တံတိုကို အရင်ဖတ်ပြီး မိနစ်အတွက် လက်တံရှည်ကို ဖတ်ပါ။"},"th":{"prompt":"นาฬิกาบอกเวลาเท่าไร","explanation":"เข็มสั้นอยู่ระหว่าง 11 กับ 12 ชั่วโมงจึงเป็น 11 เข็มยาวชี้ที่ 10 แต่ละตัวเลขคือ 5 นาที จึงเป็น 10 × 5 = 50 นาที เวลาคือ 11:50","hint":"อ่านเข็มสั้นเพื่อดูชั่วโมง แล้วอ่านเข็มยาวเพื่อดูนาที"}}'::jsonb),
  ('e1795752-731c-48e3-af99-52e4686076e5', '183b9378-9415-41c5-adaf-645244f6d4ef', 'numeric', 'How many cents are there altogether?', '{"kind":"coins","coins":[10,10,1,1]}'::jsonb, '{"value":"22"}'::jsonb, null, 'Start with the biggest coin and count on: 10, 20, 21, 22. That is 22 cents (22¢).', 'Start with the biggest coin, then count on.', 2, 10, 1, true, '{"my":{"prompt":"စုစုပေါင်း ဘယ်နှဆင့် ရှိလဲ။","explanation":"အကြီးဆုံး အကြွေစေ့ကနေ စပြီး ဆက်ရေပါ - 10, 20, 21, 22။ ဒါက 22 ဆင့် (22¢) ပါ။","hint":"အကြီးဆုံး အကြွေစေ့ကနေ စပြီး ဆက်ရေပါ။"},"th":{"prompt":"มีทั้งหมดกี่เซนต์","explanation":"เริ่มจากเหรียญที่ใหญ่ที่สุด แล้วนับต่อ: 10, 20, 21, 22 รวมเป็น 22 เซนต์ (22¢)","hint":"เริ่มจากเหรียญที่ใหญ่ที่สุด แล้วนับต่อ"}}'::jsonb),
  ('e27958e5-721c-4750-b099-547767607552', '183b9378-9415-41c5-adaf-645244f6d4ef', 'numeric', 'How many cents are there altogether?', '{"kind":"coins","coins":[25,5]}'::jsonb, '{"value":"30"}'::jsonb, null, 'Start with the biggest coin and count on: 25, 30. That is 30 cents (30¢).', 'Start with the biggest coin, then count on.', 2, 10, 2, true, '{"my":{"prompt":"စုစုပေါင်း ဘယ်နှဆင့် ရှိလဲ။","explanation":"အကြီးဆုံး အကြွေစေ့ကနေ စပြီး ဆက်ရေပါ - 25, 30။ ဒါက 30 ဆင့် (30¢) ပါ။","hint":"အကြီးဆုံး အကြွေစေ့ကနေ စပြီး ဆက်ရေပါ။"},"th":{"prompt":"มีทั้งหมดกี่เซนต์","explanation":"เริ่มจากเหรียญที่ใหญ่ที่สุด แล้วนับต่อ: 25, 30 รวมเป็น 30 เซนต์ (30¢)","hint":"เริ่มจากเหรียญที่ใหญ่ที่สุด แล้วนับต่อ"}}'::jsonb),
  ('df79542c-751c-4c09-b199-560a666073bf', '183b9378-9415-41c5-adaf-645244f6d4ef', 'numeric', 'Aisha buys a sticker for 50¢ and pays with 100¢. How many cents of change does Aisha get?', null, '{"value":"50"}'::jsonb, null, 'Change is what is left: 100 − 50 = 50. You can check by counting up from 50 to 100. The change is 50¢.', 'Count up from 50 to 100.', 2, 10, 3, true, '{"my":{"prompt":"စု က စတစ်ကာ ကို 50¢ နဲ့ ဝယ်ပြီး 100¢ ပေးတယ်။ စု ပြန်အမ်းငွေ ဘယ်နှဆင့် ရလဲ။","explanation":"ပြန်အမ်းငွေက ကျန်တဲ့ငွေပါ - 100 − 50 = 50။ 50 ကနေ 100 အထိ ရေတွက်ပြီး စစ်နိုင်တယ်။ ပြန်အမ်းငွေက 50¢ ပါ။","hint":"50 ကနေ 100 အထိ ရေပါ။"},"th":{"prompt":"ขวัญซื้อสติกเกอร์ราคา 50¢ และจ่าย 100¢ ขวัญได้เงินทอนกี่เซนต์","explanation":"เงินทอนคือส่วนที่เหลือ: 100 − 50 = 50 ตรวจได้โดยนับขึ้นจาก 50 ถึง 100 เงินทอนคือ 50¢","hint":"นับขึ้นจาก 50 ถึง 100"}}'::jsonb),
  ('e07955bf-741c-4a76-b299-579d6560722c', '183b9378-9415-41c5-adaf-645244f6d4ef', 'numeric', 'How many cents are there altogether?', '{"kind":"coins","coins":[25,10,10,5,5,1]}'::jsonb, '{"value":"56"}'::jsonb, null, 'Start with the biggest coin and count on: 25, 35, 45, 50, 55, 56. That is 56 cents (56¢).', 'Start with the biggest coin, then count on.', 2, 10, 4, true, '{"my":{"prompt":"စုစုပေါင်း ဘယ်နှဆင့် ရှိလဲ။","explanation":"အကြီးဆုံး အကြွေစေ့ကနေ စပြီး ဆက်ရေပါ - 25, 35, 45, 50, 55, 56။ ဒါက 56 ဆင့် (56¢) ပါ။","hint":"အကြီးဆုံး အကြွေစေ့ကနေ စပြီး ဆက်ရေပါ။"},"th":{"prompt":"มีทั้งหมดกี่เซนต์","explanation":"เริ่มจากเหรียญที่ใหญ่ที่สุด แล้วนับต่อ: 25, 35, 45, 50, 55, 56 รวมเป็น 56 เซนต์ (56¢)","hint":"เริ่มจากเหรียญที่ใหญ่ที่สุด แล้วนับต่อ"}}'::jsonb),
  ('dd795106-771c-4f2f-ab99-4c9864607099', '183b9378-9415-41c5-adaf-645244f6d4ef', 'numeric', 'Leo buys an apple for 25¢ and pays with 50¢. How many cents of change does Leo get?', null, '{"value":"25"}'::jsonb, null, 'Change is what is left: 50 − 25 = 25. You can check by counting up from 25 to 50. The change is 25¢.', 'Count up from 25 to 50.', 2, 10, 5, true, '{"my":{"prompt":"အောင် က ပန်းသီး ကို 25¢ နဲ့ ဝယ်ပြီး 50¢ ပေးတယ်။ အောင် ပြန်အမ်းငွေ ဘယ်နှဆင့် ရလဲ။","explanation":"ပြန်အမ်းငွေက ကျန်တဲ့ငွေပါ - 50 − 25 = 25။ 25 ကနေ 50 အထိ ရေတွက်ပြီး စစ်နိုင်တယ်။ ပြန်အမ်းငွေက 25¢ ပါ။","hint":"25 ကနေ 50 အထိ ရေပါ။"},"th":{"prompt":"ต้นซื้อแอปเปิลราคา 25¢ และจ่าย 50¢ ต้นได้เงินทอนกี่เซนต์","explanation":"เงินทอนคือส่วนที่เหลือ: 50 − 25 = 25 ตรวจได้โดยนับขึ้นจาก 25 ถึง 50 เงินทอนคือ 25¢","hint":"นับขึ้นจาก 25 ถึง 50"}}'::jsonb),
  ('af45eb9b-9ef5-48e8-812f-9119cfe2dc16', '872d05b9-9741-4586-b823-475f1a6e7144', 'numeric', 'How many right angles does a rectangle have?', '{"kind":"shape","shape":"rectangle"}'::jsonb, '{"value":"4"}'::jsonb, null, 'A right angle is a square corner, like the corner of a page. A rectangle has 4 square corners, so it has 4 right angles.', 'Count the square corners.', 2, 10, 1, true, '{"my":{"prompt":"ထောင့်မှန်စတုဂံမှာ ထောင့်မှန် ဘယ်နှခု ရှိလဲ။","explanation":"ထောင့်မှန်ဆိုတာ စာမျက်နှာထောင့်လို စတုရန်းထောင့်ပါ။ ထောင့်မှန်စတုဂံမှာ စတုရန်းထောင့် 4 ခု ရှိလို့ ထောင့်မှန် 4 ခု ရှိတယ်။","hint":"စတုရန်းထောင့်တွေကို ရေပါ။"},"th":{"prompt":"สี่เหลี่ยมผืนผ้ามีมุมฉากกี่มุม","explanation":"มุมฉากคือมุมเหลี่ยม เหมือนมุมของกระดาษ สี่เหลี่ยมผืนผ้ามีมุมเหลี่ยม 4 มุม จึงมีมุมฉาก 4 มุม","hint":"นับมุมเหลี่ยม"}}'::jsonb),
  ('ae45ea08-9ff5-4a7b-802f-8f86d0e2dda9', '872d05b9-9741-4586-b823-475f1a6e7144', 'multiple_choice', 'Which shape has exactly 5 sides?', null, '{"value":"b"}'::jsonb, '[{"id":"a","label":"hexagon"},{"id":"b","label":"pentagon"},{"id":"c","label":"square"},{"id":"d","label":"triangle"}]'::jsonb, 'A pentagon has 5 sides ("penta" means five). A hexagon has 6, a square has 4 and a triangle has 3.', 'Think of words that start with "penta".', 2, 10, 2, true, '{"my":{"prompt":"ဘယ်ပုံမှာ အနား 5 ခု အတိအကျ ရှိလဲ။","options":{"a":"ဆဋ္ဌဂံ","b":"ပဉ္စဂံ","c":"စတုရန်း","d":"တြိဂံ"},"explanation":"ပဉ္စဂံမှာ အနား 5 ခု ရှိတယ် (\"ပဉ္စ\" ဆိုတာ ငါး)။ ဆဋ္ဌဂံမှာ 6 ခု၊ စတုရန်းမှာ 4 ခု၊ တြိဂံမှာ 3 ခု ရှိတယ်။","hint":"\"ပဉ္စ\" ဆိုတာ ဘာကို ဆိုလိုလဲ စဉ်းစားပါ။"},"th":{"prompt":"รูปใดมี 5 ด้านพอดี","options":{"a":"หกเหลี่ยม","b":"ห้าเหลี่ยม","c":"สี่เหลี่ยมจัตุรัส","d":"สามเหลี่ยม"},"explanation":"ห้าเหลี่ยมมี 5 ด้าน หกเหลี่ยมมี 6 ด้าน สี่เหลี่ยมจัตุรัสมี 4 ด้าน และสามเหลี่ยมมี 3 ด้าน","hint":"ชื่อรูปบอกจำนวนเหลี่ยม"}}'::jsonb),
  ('b145eec1-a0f5-4c0e-bf2f-8df3cde2d8f0', '872d05b9-9741-4586-b823-475f1a6e7144', 'numeric', 'What is the perimeter of a rectangle 2 cm long and 5 cm wide?', '{"kind":"rectangle","width":2,"height":5,"unit":"cm"}'::jsonb, '{"value":"14"}'::jsonb, null, 'Perimeter is the distance all the way around. Add all four sides: 2 + 5 + 2 + 5 = 14 cm. That is the same as 2 × (2 + 5).', 'A rectangle has two long sides and two short sides.', 2, 10, 3, true, '{"my":{"prompt":"အလျား 2 စင်တီမီတာ၊ အနံ 5 စင်တီမီတာ ရှိတဲ့ ထောင့်မှန်စတုဂံရဲ့ ပတ်လည်အနားက ဘယ်လောက်လဲ။","explanation":"ပတ်လည်အနားက ပုံကို တစ်ပတ်ပတ်တဲ့ အကွာအဝေးပါ။ အနား လေးခုလုံးကို ပေါင်းပါ - 2 + 5 + 2 + 5 = 14 စင်တီမီတာ။ ဒါက 2 × (2 + 5) နဲ့ အတူတူပါပဲ။","hint":"ထောင့်မှန်စတုဂံမှာ အနားရှည် နှစ်ခုနဲ့ အနားတို နှစ်ခု ရှိတယ်။"},"th":{"prompt":"สี่เหลี่ยมผืนผ้ายาว 2 ซม. กว้าง 5 ซม. มีความยาวรอบรูปเท่าไร","explanation":"ความยาวรอบรูปคือระยะทางรอบรูปทั้งหมด บวกทั้งสี่ด้าน: 2 + 5 + 2 + 5 = 14 ซม. เท่ากับ 2 × (2 + 5)","hint":"สี่เหลี่ยมผืนผ้ามีด้านยาวสองด้านและด้านสั้นสองด้าน"}}'::jsonb),
  ('b045ed2e-a1f5-4da1-be2f-8c60cee2da83', '872d05b9-9741-4586-b823-475f1a6e7144', 'numeric', 'A square has sides of 5 cm. What is its perimeter, in cm?', '{"kind":"rectangle","width":5,"height":5,"unit":"cm"}'::jsonb, '{"value":"20"}'::jsonb, null, 'A square has 4 equal sides. 5 + 5 + 5 + 5 = 20, or 4 × 5 = 20. The perimeter is 20 cm.', 'All four sides of a square are the same length.', 2, 10, 4, true, '{"my":{"prompt":"စတုရန်းတစ်ခုရဲ့ အနားတစ်ခုစီက 5 cm ရှည်တယ်။ ပတ်လည်အနားက cm ဘယ်လောက်လဲ။","explanation":"စတုရန်းမှာ အနားညီ 4 ခု ရှိတယ်။ 5 + 5 + 5 + 5 = 20 ဒါမှမဟုတ် 4 × 5 = 20။ ပတ်လည်အနားက 20 cm ပါ။","hint":"စတုရန်းရဲ့ အနား လေးခုလုံးက အလျား တူတယ်။"},"th":{"prompt":"สี่เหลี่ยมจัตุรัสมีด้านยาว 5 cm ความยาวรอบรูปกี่ cm","explanation":"สี่เหลี่ยมจัตุรัสมี 4 ด้านยาวเท่ากัน 5 + 5 + 5 + 5 = 20 หรือ 4 × 5 = 20 ความยาวรอบรูปคือ 20 cm","hint":"ทั้งสี่ด้านของสี่เหลี่ยมจัตุรัสยาวเท่ากัน"}}'::jsonb),
  ('b345f1e7-a2f5-4f34-852f-9765d3e2e262', '872d05b9-9741-4586-b823-475f1a6e7144', 'numeric', 'What is the perimeter of a rectangle 4 m long and 10 m wide?', '{"kind":"rectangle","width":4,"height":10,"unit":"m"}'::jsonb, '{"value":"28"}'::jsonb, null, 'Perimeter is the distance all the way around. Add all four sides: 4 + 10 + 4 + 10 = 28 m. That is the same as 2 × (4 + 10).', 'A rectangle has two long sides and two short sides.', 2, 10, 5, true, '{"my":{"prompt":"အလျား 4 မီတာ၊ အနံ 10 မီတာ ရှိတဲ့ ထောင့်မှန်စတုဂံရဲ့ ပတ်လည်အနားက ဘယ်လောက်လဲ။","explanation":"ပတ်လည်အနားက ပုံကို တစ်ပတ်ပတ်တဲ့ အကွာအဝေးပါ။ အနား လေးခုလုံးကို ပေါင်းပါ - 4 + 10 + 4 + 10 = 28 မီတာ။ ဒါက 2 × (4 + 10) နဲ့ အတူတူပါပဲ။","hint":"ထောင့်မှန်စတုဂံမှာ အနားရှည် နှစ်ခုနဲ့ အနားတို နှစ်ခု ရှိတယ်။"},"th":{"prompt":"สี่เหลี่ยมผืนผ้ายาว 4 ม. กว้าง 10 ม. มีความยาวรอบรูปเท่าไร","explanation":"ความยาวรอบรูปคือระยะทางรอบรูปทั้งหมด บวกทั้งสี่ด้าน: 4 + 10 + 4 + 10 = 28 ม. เท่ากับ 2 × (4 + 10)","hint":"สี่เหลี่ยมผืนผ้ามีด้านยาวสองด้านและด้านสั้นสองด้าน"}}'::jsonb),
  ('ed6349c7-9a56-4bb8-86ff-49950e76b49e', 'af7fec15-39a0-4d96-a5cf-d61bbdfbaf0c', 'numeric', 'Write 9/25 as a decimal.', null, '{"value":"0.36","format":"decimal"}'::jsonb, null, 'Make the bottom number 100: multiply top and bottom by 4. 9/25 = 36/100 = 0.36.', 'What do you multiply 25 by to make 100?', 1, 10, 1, true, '{"my":{"prompt":"9/25 ကို ဒသမကိန်းအဖြစ် ရေးပါ။","explanation":"အောက်ဂဏန်းကို 100 ဖြစ်အောင်လုပ်ပါ - အပေါ်နဲ့ အောက်ကို 4 နဲ့ မြှောက်ပါ။ 9/25 = 36/100 = 0.36။","hint":"25 ကို ဘာနဲ့ မြှောက်ရင် 100 ဖြစ်လဲ။"},"th":{"prompt":"เขียน 9/25 เป็นทศนิยม","explanation":"ทำตัวส่วนให้เป็น 100: คูณทั้งตัวเศษและตัวส่วนด้วย 4 9/25 = 36/100 = 0.36","hint":"25 คูณด้วยอะไรจึงได้ 100"}}'::jsonb),
  ('ec634834-9b56-4d4b-85ff-48020f76b631', 'af7fec15-39a0-4d96-a5cf-d61bbdfbaf0c', 'numeric', 'Write 0.2 as a fraction in its simplest form.', null, '{"value":"1/5","format":"simplest_fraction"}'::jsonb, null, '0.2 means 2 tenths: 2/10. Divide the top and bottom by 2: 2/10 = 1/5.', 'Write it as tenths first, then simplify.', 1, 10, 2, true, '{"my":{"prompt":"0.2 ကို အရိုးရှင်းဆုံး အပိုင်းကိန်းအဖြစ် ရေးပါ။","explanation":"0.2 ဆိုတာ ဆယ်ပုံတစ်ပုံ 2 ပုံပါ - 2/10။ အပေါ်နဲ့ အောက်ကို 2 နဲ့ စားပါ - 2/10 = 1/5။","hint":"ဆယ်ပုံတစ်ပုံ အဖြစ် အရင်ရေးပြီး ရိုးရှင်းအောင် လုပ်ပါ။"},"th":{"prompt":"เขียน 0.2 เป็นเศษส่วนอย่างต่ำ","explanation":"0.2 หมายถึง 2 ส่วนสิบ: 2/10 หารทั้งตัวเศษและตัวส่วนด้วย 2: 2/10 = 1/5","hint":"เขียนเป็นส่วนสิบก่อน แล้วทำให้เป็นอย่างต่ำ"}}'::jsonb),
  ('ef634ced-9c56-4ede-84ff-466f0c76b178', 'af7fec15-39a0-4d96-a5cf-d61bbdfbaf0c', 'numeric', 'Write 1/20 as a decimal.', null, '{"value":"0.05","format":"decimal"}'::jsonb, null, 'Make the bottom number 100: multiply top and bottom by 5. 1/20 = 5/100 = 0.05.', 'What do you multiply 20 by to make 100?', 1, 10, 3, true, '{"my":{"prompt":"1/20 ကို ဒသမကိန်းအဖြစ် ရေးပါ။","explanation":"အောက်ဂဏန်းကို 100 ဖြစ်အောင်လုပ်ပါ - အပေါ်နဲ့ အောက်ကို 5 နဲ့ မြှောက်ပါ။ 1/20 = 5/100 = 0.05။","hint":"20 ကို ဘာနဲ့ မြှောက်ရင် 100 ဖြစ်လဲ။"},"th":{"prompt":"เขียน 1/20 เป็นทศนิยม","explanation":"ทำตัวส่วนให้เป็น 100: คูณทั้งตัวเศษและตัวส่วนด้วย 5 1/20 = 5/100 = 0.05","hint":"20 คูณด้วยอะไรจึงได้ 100"}}'::jsonb),
  ('ee634b5a-9d57-4071-83ff-44dc0d76b30b', 'af7fec15-39a0-4d96-a5cf-d61bbdfbaf0c', 'numeric', 'Write 0.5 as a fraction in its simplest form.', null, '{"value":"1/2","format":"simplest_fraction"}'::jsonb, null, '0.5 means 5 tenths: 5/10. Divide the top and bottom by 5: 5/10 = 1/2.', 'Write it as tenths first, then simplify.', 1, 10, 4, true, '{"my":{"prompt":"0.5 ကို အရိုးရှင်းဆုံး အပိုင်းကိန်းအဖြစ် ရေးပါ။","explanation":"0.5 ဆိုတာ ဆယ်ပုံတစ်ပုံ 5 ပုံပါ - 5/10။ အပေါ်နဲ့ အောက်ကို 5 နဲ့ စားပါ - 5/10 = 1/2။","hint":"ဆယ်ပုံတစ်ပုံ အဖြစ် အရင်ရေးပြီး ရိုးရှင်းအောင် လုပ်ပါ။"},"th":{"prompt":"เขียน 0.5 เป็นเศษส่วนอย่างต่ำ","explanation":"0.5 หมายถึง 5 ส่วนสิบ: 5/10 หารทั้งตัวเศษและตัวส่วนด้วย 5: 5/10 = 1/2","hint":"เขียนเป็นส่วนสิบก่อน แล้วทำให้เป็นอย่างต่ำ"}}'::jsonb),
  ('e963437b-9e57-4204-82ff-43491276baea', 'af7fec15-39a0-4d96-a5cf-d61bbdfbaf0c', 'numeric', 'Write 1/10 as a decimal.', null, '{"value":"0.1","format":"decimal"}'::jsonb, null, 'Make the bottom number 100: multiply top and bottom by 10. 1/10 = 10/100 = 0.1.', 'What do you multiply 10 by to make 100?', 1, 10, 5, true, '{"my":{"prompt":"1/10 ကို ဒသမကိန်းအဖြစ် ရေးပါ။","explanation":"အောက်ဂဏန်းကို 100 ဖြစ်အောင်လုပ်ပါ - အပေါ်နဲ့ အောက်ကို 10 နဲ့ မြှောက်ပါ။ 1/10 = 10/100 = 0.1။","hint":"10 ကို ဘာနဲ့ မြှောက်ရင် 100 ဖြစ်လဲ။"},"th":{"prompt":"เขียน 1/10 เป็นทศนิยม","explanation":"ทำตัวส่วนให้เป็น 100: คูณทั้งตัวเศษและตัวส่วนด้วย 10 1/10 = 10/100 = 0.1","hint":"10 คูณด้วยอะไรจึงได้ 100"}}'::jsonb),
  ('25e5c7e8-3485-4589-ac5c-948e17a0fa1f', 'd32b6072-1037-41bf-a34f-67d87b8c1f75', 'numeric', 'What is 1/6 + 3/6?', null, '{"value":"4/6","format":"fraction"}'::jsonb, null, 'The bottom numbers are the same, so add the tops: 1 + 3 = 4. The answer is 4/6, which simplifies to 2/3.', 'Keep the bottom number. Add the top numbers.', 2, 10, 1, true, '{"my":{"prompt":"1/6 + 3/6 က ဘယ်လောက်လဲ။","explanation":"အောက်ဂဏန်းတွေ တူလို့ အပေါ်ဂဏန်းတွေကို ပေါင်းပါ - 1 + 3 = 4။ အဖြေက 4/6 ဖြစ်ပြီး 2/3 အထိ ရိုးရှင်းအောင် လုပ်နိုင်တယ်။","hint":"အောက်ဂဏန်းကို မပြောင်းဘဲ အပေါ်ဂဏန်းတွေကို ပေါင်းပါ။"},"th":{"prompt":"1/6 + 3/6 เท่ากับเท่าไร","explanation":"ตัวส่วนเท่ากัน จึงบวกตัวเศษ: 1 + 3 = 4 คำตอบคือ 4/6 ซึ่งทำเป็นอย่างต่ำได้ 2/3","hint":"ตัวส่วนคงเดิม บวกตัวเศษ"}}'::jsonb),
  ('26e5c97b-3385-43f6-ad5c-962116a0f88c', 'd32b6072-1037-41bf-a34f-67d87b8c1f75', 'numeric', 'What is 3/5 + 1/5?', null, '{"value":"4/5","format":"fraction"}'::jsonb, null, 'The bottom numbers are the same, so add the tops: 3 + 1 = 4. The answer is 4/5.', 'Keep the bottom number. Add the top numbers.', 2, 10, 2, true, '{"my":{"prompt":"3/5 + 1/5 က ဘယ်လောက်လဲ။","explanation":"အောက်ဂဏန်းတွေ တူလို့ အပေါ်ဂဏန်းတွေကို ပေါင်းပါ - 3 + 1 = 4။ အဖြေက 4/5။","hint":"အောက်ဂဏန်းကို မပြောင်းဘဲ အပေါ်ဂဏန်းတွေကို ပေါင်းပါ။"},"th":{"prompt":"3/5 + 1/5 เท่ากับเท่าไร","explanation":"ตัวส่วนเท่ากัน จึงบวกตัวเศษ: 3 + 1 = 4 คำตอบคือ 4/5","hint":"ตัวส่วนคงเดิม บวกตัวเศษ"}}'::jsonb),
  ('27e5cb0e-3285-4263-aa5c-916819a0fd45', 'd32b6072-1037-41bf-a34f-67d87b8c1f75', 'numeric', 'What is 1/3 + 1/6?', null, '{"value":"3/6","format":"fraction"}'::jsonb, null, 'Make the bottom numbers the same. 1/3 = 2/6. Then 2/6 + 1/6 = 3/6 = 1/2.', 'Change 1/3 into a fraction with 6 on the bottom.', 2, 10, 3, true, '{"my":{"prompt":"1/3 + 1/6 က ဘယ်လောက်လဲ။","explanation":"အောက်ဂဏန်းတွေကို တူအောင် လုပ်ပါ။ 1/3 = 2/6။ ပြီးရင် 2/6 + 1/6 = 3/6 = 1/2။","hint":"1/3 ကို အောက်ဂဏန်း 6 ရှိတဲ့ အပိုင်းကိန်းအဖြစ် ပြောင်းပါ။"},"th":{"prompt":"1/3 + 1/6 เท่ากับเท่าไร","explanation":"ทำตัวส่วนให้เท่ากัน 1/3 = 2/6 แล้ว 2/6 + 1/6 = 3/6 = 1/2","hint":"เปลี่ยน 1/3 เป็นเศษส่วนที่มีตัวส่วนเป็น 6"}}'::jsonb),
  ('28e5cca1-3185-40d0-ab5c-92fb18a0fbb2', 'd32b6072-1037-41bf-a34f-67d87b8c1f75', 'numeric', 'What is 5/12 + 5/12?', null, '{"value":"10/12","format":"fraction"}'::jsonb, null, 'The bottom numbers are the same, so add the tops: 5 + 5 = 10. The answer is 10/12, which simplifies to 5/6.', 'Keep the bottom number. Add the top numbers.', 2, 10, 4, true, '{"my":{"prompt":"5/12 + 5/12 က ဘယ်လောက်လဲ။","explanation":"အောက်ဂဏန်းတွေ တူလို့ အပေါ်ဂဏန်းတွေကို ပေါင်းပါ - 5 + 5 = 10။ အဖြေက 10/12 ဖြစ်ပြီး 5/6 အထိ ရိုးရှင်းအောင် လုပ်နိုင်တယ်။","hint":"အောက်ဂဏန်းကို မပြောင်းဘဲ အပေါ်ဂဏန်းတွေကို ပေါင်းပါ။"},"th":{"prompt":"5/12 + 5/12 เท่ากับเท่าไร","explanation":"ตัวส่วนเท่ากัน จึงบวกตัวเศษ: 5 + 5 = 10 คำตอบคือ 10/12 ซึ่งทำเป็นอย่างต่ำได้ 5/6","hint":"ตัวส่วนคงเดิม บวกตัวเศษ"}}'::jsonb),
  ('29e5ce34-3885-4bd5-b05c-9ada13a0f3d3', 'd32b6072-1037-41bf-a34f-67d87b8c1f75', 'numeric', 'What is 1/5 + 1/10?', null, '{"value":"3/10","format":"fraction"}'::jsonb, null, 'Make the bottom numbers the same. 1/5 = 2/10. Then 2/10 + 1/10 = 3/10.', 'Change 1/5 into a fraction with 10 on the bottom.', 2, 10, 5, true, '{"my":{"prompt":"1/5 + 1/10 က ဘယ်လောက်လဲ။","explanation":"အောက်ဂဏန်းတွေကို တူအောင် လုပ်ပါ။ 1/5 = 2/10။ ပြီးရင် 2/10 + 1/10 = 3/10။","hint":"1/5 ကို အောက်ဂဏန်း 10 ရှိတဲ့ အပိုင်းကိန်းအဖြစ် ပြောင်းပါ။"},"th":{"prompt":"1/5 + 1/10 เท่ากับเท่าไร","explanation":"ทำตัวส่วนให้เท่ากัน 1/5 = 2/10 แล้ว 2/10 + 1/10 = 3/10","hint":"เปลี่ยน 1/5 เป็นเศษส่วนที่มีตัวส่วนเป็น 10"}}'::jsonb),
  ('3e8624b3-5278-4762-9892-eb11cf39b498', '2c007681-ba89-4b7c-a776-b5c7776dd8ea', 'numeric', 'What is 6.88 − 3.32?', null, '{"value":"3.56","format":"decimal"}'::jsonb, null, 'Line up the decimal points and subtract each place: 6.88 − 3.32 = 3.56, which is 3.56.', 'Write both numbers with two decimal places, then line up the points.', 3, 10, 1, true, '{"my":{"prompt":"6.88 − 3.32 က ဘယ်လောက်လဲ။","explanation":"ဒသမအမှတ်တွေကို တန်းညှိပြီး နေရာတစ်ခုစီကို နုတ်ပါ - 6.88 − 3.32 = 3.56၊ ဒါက 3.56 ပါ။","hint":"ဂဏန်းနှစ်ခုလုံးကို ဒသမနေရာ နှစ်နေရာဖြင့် ရေးပြီး အမှတ်တွေကို တန်းညှိပါ။"},"th":{"prompt":"6.88 − 3.32 เท่ากับเท่าไร","explanation":"ตั้งจุดทศนิยมให้ตรงกัน แล้วลบทีละหลัก: 6.88 − 3.32 = 3.56 ซึ่งก็คือ 3.56","hint":"เขียนทั้งสองจำนวนให้มีทศนิยมสองตำแหน่ง แล้วตั้งจุดให้ตรงกัน"}}'::jsonb),
  ('3d862320-5378-48f5-9792-e97ed039b62b', '2c007681-ba89-4b7c-a776-b5c7776dd8ea', 'numeric', 'What is 6.2 × 100?', null, '{"value":"620","format":"decimal"}'::jsonb, null, 'Multiplying by 100 makes a number 100 times bigger: each digit moves two places to the left. 6.2 × 100 = 620.', 'Move each digit two places to the left.', 3, 10, 2, true, '{"my":{"prompt":"6.2 × 100 က ဘယ်လောက်လဲ။","explanation":"100 နဲ့ မြှောက်ရင် ဂဏန်းက 100 ဆ ကြီးလာတယ် - ဂဏန်းလုံးတိုင်း ဘယ်ဘက်ကို နှစ်နေရာ ရွှေ့တယ်။ 6.2 × 100 = 620။","hint":"ဂဏန်းလုံးတိုင်းကို ဘယ်ဘက်ကို နှစ်နေရာ ရွှေ့ပါ။"},"th":{"prompt":"6.2 × 100 เท่ากับเท่าไร","explanation":"การคูณด้วย 100 ทำให้จำนวนใหญ่ขึ้น 100 เท่า: ทุกหลักเลื่อนไปทางซ้ายสองตำแหน่ง 6.2 × 100 = 620","hint":"เลื่อนทุกหลักไปทางซ้ายสองตำแหน่ง"}}'::jsonb),
  ('408627d9-5078-443c-9692-e7ebd139b7be', '2c007681-ba89-4b7c-a776-b5c7776dd8ea', 'numeric', 'What is 5.55 + 1.07?', null, '{"value":"6.62","format":"decimal"}'::jsonb, null, 'Line up the decimal points and add each place: 5.55 + 1.07 = 6.62, which is 6.62.', 'Write both numbers with two decimal places, then line up the points.', 3, 10, 3, true, '{"my":{"prompt":"5.55 + 1.07 က ဘယ်လောက်လဲ။","explanation":"ဒသမအမှတ်တွေကို တန်းညှိပြီး နေရာတစ်ခုစီကို ပေါင်းပါ - 5.55 + 1.07 = 6.62၊ ဒါက 6.62 ပါ။","hint":"ဂဏန်းနှစ်ခုလုံးကို ဒသမနေရာ နှစ်နေရာဖြင့် ရေးပြီး အမှတ်တွေကို တန်းညှိပါ။"},"th":{"prompt":"5.55 + 1.07 เท่ากับเท่าไร","explanation":"ตั้งจุดทศนิยมให้ตรงกัน แล้วบวกทีละหลัก: 5.55 + 1.07 = 6.62 ซึ่งก็คือ 6.62","hint":"เขียนทั้งสองจำนวนให้มีทศนิยมสองตำแหน่ง แล้วตั้งจุดให้ตรงกัน"}}'::jsonb),
  ('3f862646-5178-45cf-9592-e658d239b951', '2c007681-ba89-4b7c-a776-b5c7776dd8ea', 'numeric', 'What is 96 ÷ 100?', null, '{"value":"0.96","format":"decimal"}'::jsonb, null, 'Dividing by 100 makes a number 100 times smaller: each digit moves two places to the right. 96 ÷ 100 = 0.96.', 'Move each digit two places to the right.', 3, 10, 4, true, '{"my":{"prompt":"96 ÷ 100 က ဘယ်လောက်လဲ။","explanation":"100 နဲ့ စားရင် ဂဏန်းက 100 ဆ ငယ်သွားတယ် - ဂဏန်းလုံးတိုင်း ညာဘက်ကို နှစ်နေရာ ရွှေ့တယ်။ 96 ÷ 100 = 0.96။","hint":"ဂဏန်းလုံးတိုင်းကို ညာဘက်ကို နှစ်နေရာ ရွှေ့ပါ။"},"th":{"prompt":"96 ÷ 100 เท่ากับเท่าไร","explanation":"การหารด้วย 100 ทำให้จำนวนเล็กลง 100 เท่า: ทุกหลักเลื่อนไปทางขวาสองตำแหน่ง 96 ÷ 100 = 0.96","hint":"เลื่อนทุกหลักไปทางขวาสองตำแหน่ง"}}'::jsonb),
  ('42862aff-4e78-4116-9c92-f15dd339bae4', '2c007681-ba89-4b7c-a776-b5c7776dd8ea', 'numeric', 'What is 1.89 − 0.12?', null, '{"value":"1.77","format":"decimal"}'::jsonb, null, 'Line up the decimal points and subtract each place: 1.89 − 0.12 = 1.77, which is 1.77.', 'Write both numbers with two decimal places, then line up the points.', 3, 10, 5, true, '{"my":{"prompt":"1.89 − 0.12 က ဘယ်လောက်လဲ။","explanation":"ဒသမအမှတ်တွေကို တန်းညှိပြီး နေရာတစ်ခုစီကို နုတ်ပါ - 1.89 − 0.12 = 1.77၊ ဒါက 1.77 ပါ။","hint":"ဂဏန်းနှစ်ခုလုံးကို ဒသမနေရာ နှစ်နေရာဖြင့် ရေးပြီး အမှတ်တွေကို တန်းညှိပါ။"},"th":{"prompt":"1.89 − 0.12 เท่ากับเท่าไร","explanation":"ตั้งจุดทศนิยมให้ตรงกัน แล้วลบทีละหลัก: 1.89 − 0.12 = 1.77 ซึ่งก็คือ 1.77","hint":"เขียนทั้งสองจำนวนให้มีทศนิยมสองตำแหน่ง แล้วตั้งจุดให้ตรงกัน"}}'::jsonb),
  ('48cb7bf0-bc1d-401b-bf5d-6be60f0eaca1', 'b9edd62a-4e92-41ad-aac1-f5400c17ed3b', 'numeric', 'What percentage of the grid is shaded? Type the number only.', '{"kind":"percent_grid","shaded":31}'::jsonb, '{"value":"31"}'::jsonb, null, 'The grid has 100 squares and 31 are shaded. "Per cent" means "out of 100", so 31 out of 100 is 31%.', 'Each full row has 10 squares.', 1, 10, 1, true, '{"my":{"prompt":"ဇယားကွက်ရဲ့ ဘယ်နှရာခိုင်နှုန်းကို အရောင်ခြယ်ထားလဲ။ ဂဏန်းကိုသာ ရိုက်ပါ။","explanation":"ဇယားကွက်မှာ အကွက် 100 ရှိပြီး 31 ကွက်ကို အရောင်ခြယ်ထားတယ်။ \"ရာခိုင်နှုန်း\" ဆိုတာ \"100 ထဲက\" လို့ အဓိပ္ပာယ်ရလို့ 100 ထဲက 31 က 31% ပါ။","hint":"အတန်းပြည့် တစ်တန်းစီမှာ အကွက် 10 ကွက် ရှိတယ်။"},"th":{"prompt":"ตารางนี้ระบายสีไปกี่เปอร์เซ็นต์ พิมพ์เฉพาะตัวเลข","explanation":"ตารางมี 100 ช่อง ระบายสี 31 ช่อง \"เปอร์เซ็นต์\" แปลว่า \"จาก 100\" ดังนั้น 31 จาก 100 คือ 31%","hint":"แต่ละแถวเต็มมี 10 ช่อง"}}'::jsonb),
  ('49cb7d83-bb1d-4e88-805d-6d790e0eab0e', 'b9edd62a-4e92-41ad-aac1-f5400c17ed3b', 'multiple_choice', 'Which fraction is the same as 50%?', null, '{"value":"b"}'::jsonb, '[{"id":"a","label":"1/5"},{"id":"b","label":"1/2"},{"id":"c","label":"1/50"},{"id":"d","label":"5/100"}]'::jsonb, '50% means 50 out of 100, which is 50/100. Divide top and bottom by 50: 50/100 = 1/2.', 'Write 50% as a fraction out of 100, then simplify.', 1, 10, 2, true, '{"my":{"prompt":"ဘယ်အပိုင်းကိန်းက 50% နဲ့ တူလဲ။","explanation":"50% ဆိုတာ 100 ထဲက 50 ဖြစ်လို့ 50/100 ပါ။ အပေါ်နဲ့ အောက်ကို 50 နဲ့ စားပါ - 50/100 = 1/2။","hint":"50% ကို 100 ထဲက အပိုင်းကိန်းအဖြစ် ရေးပြီး ရိုးရှင်းအောင် လုပ်ပါ။"},"th":{"prompt":"เศษส่วนใดเท่ากับ 50%","explanation":"50% หมายถึง 50 จาก 100 ซึ่งคือ 50/100 หารทั้งตัวเศษและตัวส่วนด้วย 50: 50/100 = 1/2","hint":"เขียน 50% เป็นเศษส่วนที่มีตัวส่วน 100 แล้วทำเป็นอย่างต่ำ"}}'::jsonb),
  ('4acb7f16-be1d-4341-bd5d-68c00d0ea97b', 'b9edd62a-4e92-41ad-aac1-f5400c17ed3b', 'numeric', 'What percentage of the grid is shaded? Type the number only.', '{"kind":"percent_grid","shaded":55}'::jsonb, '{"value":"55"}'::jsonb, null, 'The grid has 100 squares and 55 are shaded. "Per cent" means "out of 100", so 55 out of 100 is 55%.', 'Each full row has 10 squares.', 1, 10, 3, true, '{"my":{"prompt":"ဇယားကွက်ရဲ့ ဘယ်နှရာခိုင်နှုန်းကို အရောင်ခြယ်ထားလဲ။ ဂဏန်းကိုသာ ရိုက်ပါ။","explanation":"ဇယားကွက်မှာ အကွက် 100 ရှိပြီး 55 ကွက်ကို အရောင်ခြယ်ထားတယ်။ \"ရာခိုင်နှုန်း\" ဆိုတာ \"100 ထဲက\" လို့ အဓိပ္ပာယ်ရလို့ 100 ထဲက 55 က 55% ပါ။","hint":"အတန်းပြည့် တစ်တန်းစီမှာ အကွက် 10 ကွက် ရှိတယ်။"},"th":{"prompt":"ตารางนี้ระบายสีไปกี่เปอร์เซ็นต์ พิมพ์เฉพาะตัวเลข","explanation":"ตารางมี 100 ช่อง ระบายสี 55 ช่อง \"เปอร์เซ็นต์\" แปลว่า \"จาก 100\" ดังนั้น 55 จาก 100 คือ 55%","hint":"แต่ละแถวเต็มมี 10 ช่อง"}}'::jsonb),
  ('4bcb80a9-bd1d-41ae-be5d-6a530c0ea7e8', 'b9edd62a-4e92-41ad-aac1-f5400c17ed3b', 'multiple_choice', 'Which fraction is the same as 25%?', null, '{"value":"a"}'::jsonb, '[{"id":"a","label":"1/4"},{"id":"b","label":"1/25"},{"id":"c","label":"2/5"},{"id":"d","label":"1/2"}]'::jsonb, '25% is 25 out of 100: 25/100. Divide top and bottom by 25: 25/100 = 1/4.', 'How many 25s make 100?', 1, 10, 4, true, '{"my":{"prompt":"ဘယ်အပိုင်းကိန်းက 25% နဲ့ တူလဲ။","explanation":"25% က 100 ထဲက 25 ပါ - 25/100။ အပေါ်နဲ့ အောက်ကို 25 နဲ့ စားပါ - 25/100 = 1/4။","hint":"25 ဘယ်နှခု ပေါင်းရင် 100 ဖြစ်လဲ။"},"th":{"prompt":"เศษส่วนใดเท่ากับ 25%","explanation":"25% คือ 25 จาก 100: 25/100 หารทั้งตัวเศษและตัวส่วนด้วย 25: 25/100 = 1/4","hint":"25 กี่ตัวรวมกันได้ 100"}}'::jsonb),
  ('4ccb823c-c01d-4667-835d-7232130eb2ed', 'b9edd62a-4e92-41ad-aac1-f5400c17ed3b', 'numeric', 'What percentage of the grid is shaded? Type the number only.', '{"kind":"percent_grid","shaded":48}'::jsonb, '{"value":"48"}'::jsonb, null, 'The grid has 100 squares and 48 are shaded. "Per cent" means "out of 100", so 48 out of 100 is 48%.', 'Each full row has 10 squares.', 1, 10, 5, true, '{"my":{"prompt":"ဇယားကွက်ရဲ့ ဘယ်နှရာခိုင်နှုန်းကို အရောင်ခြယ်ထားလဲ။ ဂဏန်းကိုသာ ရိုက်ပါ။","explanation":"ဇယားကွက်မှာ အကွက် 100 ရှိပြီး 48 ကွက်ကို အရောင်ခြယ်ထားတယ်။ \"ရာခိုင်နှုန်း\" ဆိုတာ \"100 ထဲက\" လို့ အဓိပ္ပာယ်ရလို့ 100 ထဲက 48 က 48% ပါ။","hint":"အတန်းပြည့် တစ်တန်းစီမှာ အကွက် 10 ကွက် ရှိတယ်။"},"th":{"prompt":"ตารางนี้ระบายสีไปกี่เปอร์เซ็นต์ พิมพ์เฉพาะตัวเลข","explanation":"ตารางมี 100 ช่อง ระบายสี 48 ช่อง \"เปอร์เซ็นต์\" แปลว่า \"จาก 100\" ดังนั้น 48 จาก 100 คือ 48%","hint":"แต่ละแถวเต็มมี 10 ช่อง"}}'::jsonb),
  ('f7d2f219-28eb-41e6-be51-d3c76d1e9f1c', '498ca0eb-c600-4ae8-8c1f-e1a16a46adfe', 'numeric', 'What is 20% of 160?', null, '{"value":"32"}'::jsonb, null, 'First find 10%: 160 ÷ 10 = 16. Then 20% is 2 × 16 = 32.', 'Find 10% first by dividing by 10.', 2, 10, 1, true, '{"my":{"prompt":"160 ရဲ့ 20% က ဘယ်လောက်လဲ။","explanation":"အရင်ဆုံး 10% ကို ရှာပါ - 160 ÷ 10 = 16။ ပြီးရင် 20% က 2 × 16 = 32။","hint":"10 နဲ့ စားပြီး 10% ကို အရင်ရှာပါ။"},"th":{"prompt":"20% ของ 160 เท่ากับเท่าไร","explanation":"หา 10% ก่อน: 160 ÷ 10 = 16 แล้ว 20% คือ 2 × 16 = 32","hint":"หา 10% ก่อนโดยหารด้วย 10"}}'::jsonb),
  ('f6d2f086-29eb-4379-bd51-d2346e1ea0af', '498ca0eb-c600-4ae8-8c1f-e1a16a46adfe', 'numeric', 'What is 10% of 200?', null, '{"value":"20"}'::jsonb, null, '10% means divide by 10. 200 ÷ 10 = 20.', 'Find 10% first by dividing by 10.', 2, 10, 2, true, '{"my":{"prompt":"200 ရဲ့ 10% က ဘယ်လောက်လဲ။","explanation":"10% ဆိုတာ 10 နဲ့ စားပါ။ 200 ÷ 10 = 20။","hint":"10 နဲ့ စားပြီး 10% ကို အရင်ရှာပါ။"},"th":{"prompt":"10% ของ 200 เท่ากับเท่าไร","explanation":"10% คือหารด้วย 10 200 ÷ 10 = 20","hint":"หา 10% ก่อนโดยหารด้วย 10"}}'::jsonb),
  ('f5d2eef3-26eb-4ec0-8051-d6ed6f1ea242', '498ca0eb-c600-4ae8-8c1f-e1a16a46adfe', 'numeric', 'What is 25% of 120?', null, '{"value":"30"}'::jsonb, null, '25% is one quarter. 120 ÷ 4 = 30.', '25% is the same as one quarter.', 2, 10, 3, true, '{"my":{"prompt":"120 ရဲ့ 25% က ဘယ်လောက်လဲ။","explanation":"25% က လေးပုံတစ်ပုံပါ။ 120 ÷ 4 = 30။","hint":"25% က လေးပုံတစ်ပုံနဲ့ အတူတူပါ။"},"th":{"prompt":"25% ของ 120 เท่ากับเท่าไร","explanation":"25% คือหนึ่งในสี่ 120 ÷ 4 = 30","hint":"25% เท่ากับหนึ่งในสี่"}}'::jsonb),
  ('f4d2ed60-27eb-4053-bf51-d55a701ea3d5', '498ca0eb-c600-4ae8-8c1f-e1a16a46adfe', 'numeric', 'What is 20% of 180?', null, '{"value":"36"}'::jsonb, null, 'First find 10%: 180 ÷ 10 = 18. Then 20% is 2 × 18 = 36.', 'Find 10% first by dividing by 10.', 2, 10, 4, true, '{"my":{"prompt":"180 ရဲ့ 20% က ဘယ်လောက်လဲ။","explanation":"အရင်ဆုံး 10% ကို ရှာပါ - 180 ÷ 10 = 18။ ပြီးရင် 20% က 2 × 18 = 36။","hint":"10 နဲ့ စားပြီး 10% ကို အရင်ရှာပါ။"},"th":{"prompt":"20% ของ 180 เท่ากับเท่าไร","explanation":"หา 10% ก่อน: 180 ÷ 10 = 18 แล้ว 20% คือ 2 × 18 = 36","hint":"หา 10% ก่อนโดยหารด้วย 10"}}'::jsonb),
  ('fbd2f865-2ceb-4832-ba51-cd7b691e98d0', '498ca0eb-c600-4ae8-8c1f-e1a16a46adfe', 'numeric', 'What is 30% of 120?', null, '{"value":"36"}'::jsonb, null, 'First find 10%: 120 ÷ 10 = 12. Then 30% is 3 × 12 = 36.', 'Find 10% first by dividing by 10.', 2, 10, 5, true, '{"my":{"prompt":"120 ရဲ့ 30% က ဘယ်လောက်လဲ။","explanation":"အရင်ဆုံး 10% ကို ရှာပါ - 120 ÷ 10 = 12။ ပြီးရင် 30% က 3 × 12 = 36။","hint":"10 နဲ့ စားပြီး 10% ကို အရင်ရှာပါ။"},"th":{"prompt":"30% ของ 120 เท่ากับเท่าไร","explanation":"หา 10% ก่อน: 120 ÷ 10 = 12 แล้ว 30% คือ 3 × 12 = 36","hint":"หา 10% ก่อนโดยหารด้วย 10"}}'::jsonb),
  ('ae513d37-9ce7-46e2-811c-5c799339fce4', '014c4da5-d493-4074-96de-b39782b99fd6', 'multiple_choice', 'What is the ratio of fish to flowers, in its simplest form?', '{"kind":"ratio","a":{"object":"fish","count":12},"b":{"object":"flower","count":15}}'::jsonb, '{"value":"a"}'::jsonb, '[{"id":"a","label":"4 : 5"},{"id":"b","label":"4 : 6"},{"id":"c","label":"5 : 4"},{"id":"d","label":"12 : 27"}]'::jsonb, 'There are 12 fish and 15 flowers, so the ratio is 12 : 15. Divide both numbers by 3: 12 ÷ 3 = 4 and 15 ÷ 3 = 5. The ratio is 4 : 5.', 'Find a number that divides both counts exactly.', 3, 10, 1, true, '{"my":{"prompt":"ငါး နဲ့ ပန်း ရဲ့ အချိုးကို အရိုးရှင်းဆုံးပုံစံဖြင့် ဘယ်လိုရေးမလဲ။","explanation":"ငါး 12 ကောင် နဲ့ ပန်း 15 ပွင့် ရှိလို့ အချိုးက 12 : 15 ပါ။ ဂဏန်းနှစ်ခုလုံးကို 3 နဲ့ စားပါ - 12 ÷ 3 = 4 နဲ့ 15 ÷ 3 = 5။ အချိုးက 4 : 5 ပါ။","hint":"အရေအတွက် နှစ်ခုလုံးကို ပြတ်အောင် စားနိုင်တဲ့ ဂဏန်းကို ရှာပါ။"},"th":{"prompt":"อัตราส่วนของปลาต่อดอกไม้ในรูปอย่างต่ำคือเท่าไร","explanation":"มีปลา 12 ตัว และดอกไม้ 15 ดอก อัตราส่วนคือ 12 : 15 หารทั้งสองจำนวนด้วย 3: 12 ÷ 3 = 4 และ 15 ÷ 3 = 5 อัตราส่วนคือ 4 : 5","hint":"หาจำนวนที่หารทั้งสองจำนวนได้ลงตัว"}}'::jsonb),
  ('ad513ba4-9de7-4875-801c-5ae69439fe77', '014c4da5-d493-4074-96de-b39782b99fd6', 'numeric', 'Zara and Ivy share 14 marbles in the ratio 4 : 3. How many marbles does Ivy get?', null, '{"value":"6"}'::jsonb, null, 'There are 4 + 3 = 7 parts. Each part is 14 ÷ 7 = 2. Ivy gets 3 parts: 3 × 2 = 6.', 'Add the ratio numbers to find the total number of parts.', 3, 10, 2, true, '{"my":{"prompt":"နန္ဒာ နဲ့ အိ က ဂေါ်လီလုံး 14 လုံးကို 4 : 3 အချိုးနဲ့ ခွဲယူကြတယ်။ အိ က ဂေါ်လီလုံး ဘယ်နှလုံး ရလဲ။","explanation":"အပိုင်း 4 + 3 = 7 ပိုင်း ရှိတယ်။ တစ်ပိုင်းစီက 14 ÷ 7 = 2။ အိ က 3 ပိုင်း ရတယ် - 3 × 2 = 6။","hint":"အပိုင်း စုစုပေါင်းကို သိဖို့ အချိုးဂဏန်းတွေကို ပေါင်းပါ။"},"th":{"prompt":"แพรวกับใบเตยแบ่งลูกแก้ว 14 ลูกในอัตราส่วน 4 : 3 ใบเตยได้ลูกแก้วกี่ลูก","explanation":"มีทั้งหมด 4 + 3 = 7 ส่วน ส่วนละ 14 ÷ 7 = 2 ใบเตยได้ 3 ส่วน: 3 × 2 = 6","hint":"บวกตัวเลขในอัตราส่วนเพื่อหาจำนวนส่วนทั้งหมด"}}'::jsonb),
  ('b051405d-9ae7-43bc-bf1c-5953953a000a', '014c4da5-d493-4074-96de-b39782b99fd6', 'multiple_choice', 'What is the ratio of fish to apples, in its simplest form?', '{"kind":"ratio","a":{"object":"fish","count":4},"b":{"object":"apple","count":6}}'::jsonb, '{"value":"b"}'::jsonb, '[{"id":"a","label":"3 : 2"},{"id":"b","label":"2 : 3"},{"id":"c","label":"4 : 10"},{"id":"d","label":"3 : 6"}]'::jsonb, 'There are 4 fish and 6 apples, so the ratio is 4 : 6. Divide both numbers by 2: 4 ÷ 2 = 2 and 6 ÷ 2 = 3. The ratio is 2 : 3.', 'Find a number that divides both counts exactly.', 3, 10, 3, true, '{"my":{"prompt":"ငါး နဲ့ ပန်းသီး ရဲ့ အချိုးကို အရိုးရှင်းဆုံးပုံစံဖြင့် ဘယ်လိုရေးမလဲ။","explanation":"ငါး 4 ကောင် နဲ့ ပန်းသီး 6 လုံး ရှိလို့ အချိုးက 4 : 6 ပါ။ ဂဏန်းနှစ်ခုလုံးကို 2 နဲ့ စားပါ - 4 ÷ 2 = 2 နဲ့ 6 ÷ 2 = 3။ အချိုးက 2 : 3 ပါ။","hint":"အရေအတွက် နှစ်ခုလုံးကို ပြတ်အောင် စားနိုင်တဲ့ ဂဏန်းကို ရှာပါ။"},"th":{"prompt":"อัตราส่วนของปลาต่อแอปเปิลในรูปอย่างต่ำคือเท่าไร","explanation":"มีปลา 4 ตัว และแอปเปิล 6 ผล อัตราส่วนคือ 4 : 6 หารทั้งสองจำนวนด้วย 2: 4 ÷ 2 = 2 และ 6 ÷ 2 = 3 อัตราส่วนคือ 2 : 3","hint":"หาจำนวนที่หารทั้งสองจำนวนได้ลงตัว"}}'::jsonb),
  ('af513eca-9be7-454f-be1c-57c0963a019d', '014c4da5-d493-4074-96de-b39782b99fd6', 'numeric', 'Ben and Leo share 16 marbles in the ratio 3 : 5. How many marbles does Leo get?', null, '{"value":"10"}'::jsonb, null, 'There are 3 + 5 = 8 parts. Each part is 16 ÷ 8 = 2. Leo gets 5 parts: 5 × 2 = 10.', 'Add the ratio numbers to find the total number of parts.', 3, 10, 4, true, '{"my":{"prompt":"ထက် နဲ့ အောင် က ဂေါ်လီလုံး 16 လုံးကို 3 : 5 အချိုးနဲ့ ခွဲယူကြတယ်။ အောင် က ဂေါ်လီလုံး ဘယ်နှလုံး ရလဲ။","explanation":"အပိုင်း 3 + 5 = 8 ပိုင်း ရှိတယ်။ တစ်ပိုင်းစီက 16 ÷ 8 = 2။ အောင် က 5 ပိုင်း ရတယ် - 5 × 2 = 10။","hint":"အပိုင်း စုစုပေါင်းကို သိဖို့ အချိုးဂဏန်းတွေကို ပေါင်းပါ။"},"th":{"prompt":"เก่งกับต้นแบ่งลูกแก้ว 16 ลูกในอัตราส่วน 3 : 5 ต้นได้ลูกแก้วกี่ลูก","explanation":"มีทั้งหมด 3 + 5 = 8 ส่วน ส่วนละ 16 ÷ 8 = 2 ต้นได้ 5 ส่วน: 5 × 2 = 10","hint":"บวกตัวเลขในอัตราส่วนเพื่อหาจำนวนส่วนทั้งหมด"}}'::jsonb),
  ('aa5136eb-98e7-4096-851c-62c58f39f698', '014c4da5-d493-4074-96de-b39782b99fd6', 'numeric', 'Mia and Leo share 56 marbles in the ratio 3 : 4. How many marbles does Leo get?', null, '{"value":"32"}'::jsonb, null, 'There are 3 + 4 = 7 parts. Each part is 56 ÷ 7 = 8. Leo gets 4 parts: 4 × 8 = 32.', 'Add the ratio numbers to find the total number of parts.', 3, 10, 5, true, '{"my":{"prompt":"မေ နဲ့ အောင် က ဂေါ်လီလုံး 56 လုံးကို 3 : 4 အချိုးနဲ့ ခွဲယူကြတယ်။ အောင် က ဂေါ်လီလုံး ဘယ်နှလုံး ရလဲ။","explanation":"အပိုင်း 3 + 4 = 7 ပိုင်း ရှိတယ်။ တစ်ပိုင်းစီက 56 ÷ 7 = 8။ အောင် က 4 ပိုင်း ရတယ် - 4 × 8 = 32။","hint":"အပိုင်း စုစုပေါင်းကို သိဖို့ အချိုးဂဏန်းတွေကို ပေါင်းပါ။"},"th":{"prompt":"มะลิกับต้นแบ่งลูกแก้ว 56 ลูกในอัตราส่วน 3 : 4 ต้นได้ลูกแก้วกี่ลูก","explanation":"มีทั้งหมด 3 + 4 = 7 ส่วน ส่วนละ 56 ÷ 7 = 8 ต้นได้ 4 ส่วน: 4 × 8 = 32","hint":"บวกตัวเลขในอัตราส่วนเพื่อหาจำนวนส่วนทั้งหมด"}}'::jsonb),
  ('5283b206-1527-4bad-9885-4bd875622cc7', 'e922268c-0682-478b-9d81-68ae70200c8d', 'compare', 'Which sign makes this true?', '{"kind":"compare","left":"4","right":"-4"}'::jsonb, '{"value":">"}'::jsonb, null, 'On a number line, numbers get bigger as you go right. 4 is to the right of −4, so 4 is greater. That means 4 > −4.', 'Picture a number line. Which number is further right?', 1, 10, 1, true, '{"my":{"prompt":"ဘယ်သင်္ကေတက ဒါကို မှန်စေလဲ။","explanation":"ကိန်းမျဉ်းပေါ်မှာ ညာဘက်ကို သွားလေ ဂဏန်းကြီးလေပါ။ 4 က −4 ရဲ့ ညာဘက်မှာ ရှိလို့ 4 က ပိုကြီးတယ်။ ဒါကြောင့် 4 > −4။","hint":"ကိန်းမျဉ်းကို စိတ်ထဲမှာ မြင်ကြည့်ပါ။ ဘယ်ဂဏန်းက ပိုညာဘက်မှာ ရှိလဲ။"},"th":{"prompt":"เครื่องหมายใดทำให้ถูกต้อง","explanation":"บนเส้นจำนวน ยิ่งไปทางขวาจำนวนยิ่งมาก 4 อยู่ทางขวาของ −4 ดังนั้น 4 มากกว่า นั่นคือ 4 > −4","hint":"นึกภาพเส้นจำนวน จำนวนใดอยู่ทางขวามากกว่า"}}'::jsonb),
  ('5383b399-1427-4a1a-9985-4d6b74622b34', 'e922268c-0682-478b-9d81-68ae70200c8d', 'multiple_choice', 'Which number is the smallest?', null, '{"value":"b"}'::jsonb, '[{"id":"a","label":"-5"},{"id":"b","label":"-14"},{"id":"c","label":"-11"},{"id":"d","label":"9"}]'::jsonb, 'In order from smallest to biggest: -14, -11, -5, 9. The smallest is -14.', 'Put the numbers in order first.', 1, 10, 2, true, '{"my":{"prompt":"ဘယ်ဂဏန်းက အငယ်ဆုံးလဲ။","explanation":"အငယ်ဆုံးမှ အကြီးဆုံးသို့ စီရင် - -14, -11, -5, 9။ အငယ်ဆုံးက -14 ပါ။","hint":"ဂဏန်းတွေကို အရင် အစဉ်လိုက်စီပါ။"},"th":{"prompt":"จำนวนใดน้อยที่สุด","explanation":"เรียงจากน้อยไปมาก: -14, -11, -5, 9 จำนวนที่น้อยที่สุดคือ -14","hint":"เรียงลำดับจำนวนก่อน"}}'::jsonb),
  ('5083aee0-1327-4887-9a85-4efe77622fed', 'e922268c-0682-478b-9d81-68ae70200c8d', 'compare', 'Which sign makes this true?', '{"kind":"compare","left":"5","right":"-9"}'::jsonb, '{"value":">"}'::jsonb, null, 'On a number line, numbers get bigger as you go right. 5 is to the right of −9, so 5 is greater. That means 5 > −9.', 'Picture a number line. Which number is further right?', 1, 10, 3, true, '{"my":{"prompt":"ဘယ်သင်္ကေတက ဒါကို မှန်စေလဲ။","explanation":"ကိန်းမျဉ်းပေါ်မှာ ညာဘက်ကို သွားလေ ဂဏန်းကြီးလေပါ။ 5 က −9 ရဲ့ ညာဘက်မှာ ရှိလို့ 5 က ပိုကြီးတယ်။ ဒါကြောင့် 5 > −9။","hint":"ကိန်းမျဉ်းကို စိတ်ထဲမှာ မြင်ကြည့်ပါ။ ဘယ်ဂဏန်းက ပိုညာဘက်မှာ ရှိလဲ။"},"th":{"prompt":"เครื่องหมายใดทำให้ถูกต้อง","explanation":"บนเส้นจำนวน ยิ่งไปทางขวาจำนวนยิ่งมาก 5 อยู่ทางขวาของ −9 ดังนั้น 5 มากกว่า นั่นคือ 5 > −9","hint":"นึกภาพเส้นจำนวน จำนวนใดอยู่ทางขวามากกว่า"}}'::jsonb),
  ('5183b073-1227-46f4-9b85-509176622e5a', 'e922268c-0682-478b-9d81-68ae70200c8d', 'multiple_choice', 'Which number is the biggest?', null, '{"value":"b"}'::jsonb, '[{"id":"a","label":"-4"},{"id":"b","label":"5"},{"id":"c","label":"-7"},{"id":"d","label":"-11"}]'::jsonb, 'In order from smallest to biggest: -11, -7, -4, 5. The biggest is 5.', 'Put the numbers in order first.', 1, 10, 4, true, '{"my":{"prompt":"ဘယ်ဂဏန်းက အကြီးဆုံးလဲ။","explanation":"အငယ်ဆုံးမှ အကြီးဆုံးသို့ စီရင် - -11, -7, -4, 5။ အကြီးဆုံးက 5 ပါ။","hint":"ဂဏန်းတွေကို အရင် အစဉ်လိုက်စီပါ။"},"th":{"prompt":"จำนวนใดมากที่สุด","explanation":"เรียงจากน้อยไปมาก: -11, -7, -4, 5 จำนวนที่มากที่สุดคือ 5","hint":"เรียงลำดับจำนวนก่อน"}}'::jsonb),
  ('5683b852-1127-4561-9c85-52247162267b', 'e922268c-0682-478b-9d81-68ae70200c8d', 'compare', 'Which sign makes this true?', '{"kind":"compare","left":"2","right":"-8"}'::jsonb, '{"value":">"}'::jsonb, null, 'On a number line, numbers get bigger as you go right. 2 is to the right of −8, so 2 is greater. That means 2 > −8.', 'Picture a number line. Which number is further right?', 1, 10, 5, true, '{"my":{"prompt":"ဘယ်သင်္ကေတက ဒါကို မှန်စေလဲ။","explanation":"ကိန်းမျဉ်းပေါ်မှာ ညာဘက်ကို သွားလေ ဂဏန်းကြီးလေပါ။ 2 က −8 ရဲ့ ညာဘက်မှာ ရှိလို့ 2 က ပိုကြီးတယ်။ ဒါကြောင့် 2 > −8။","hint":"ကိန်းမျဉ်းကို စိတ်ထဲမှာ မြင်ကြည့်ပါ။ ဘယ်ဂဏန်းက ပိုညာဘက်မှာ ရှိလဲ။"},"th":{"prompt":"เครื่องหมายใดทำให้ถูกต้อง","explanation":"บนเส้นจำนวน ยิ่งไปทางขวาจำนวนยิ่งมาก 2 อยู่ทางขวาของ −8 ดังนั้น 2 มากกว่า นั่นคือ 2 > −8","hint":"นึกภาพเส้นจำนวน จำนวนใดอยู่ทางขวามากกว่า"}}'::jsonb),
  ('6c820e24-b74c-49ad-8785-74aadc866f83', 'c7b1bd5e-f206-4953-afd2-8a840eb9c009', 'numeric', 'What is −10 − 3?', '{"kind":"number_line","min":-14,"max":-9,"step":1,"highlight":[-10],"jumps":[{"from":-10,"to":-13}]}'::jsonb, '{"value":"-13"}'::jsonb, null, 'Start at −10 on the number line. Subtracting 3 means moving 3 to the left. You land on −13, so −10 − 3 = −13.', 'Adding moves right, subtracting moves left.', 2, 10, 1, true, '{"my":{"prompt":"−10 − 3 က ဘယ်လောက်လဲ။","explanation":"ကိန်းမျဉ်းပေါ်က −10 မှာ စပါ။ 3 ကို နုတ်တာက ဘယ်ဘက်ကို 3 ရွှေ့တာပါ။ −13 မှာ ရောက်လို့ −10 − 3 = −13။","hint":"ပေါင်းရင် ညာဘက်ကို၊ နုတ်ရင် ဘယ်ဘက်ကို ရွှေ့ပါ။"},"th":{"prompt":"−10 − 3 เท่ากับเท่าไร","explanation":"เริ่มที่ −10 บนเส้นจำนวน การลบ 3 คือเลื่อนไปทางซ้าย 3 ช่อง จะถึง −13 ดังนั้น −10 − 3 = −13","hint":"บวกเลื่อนไปทางขวา ลบเลื่อนไปทางซ้าย"}}'::jsonb),
  ('6d820fb7-b64c-481a-8885-763ddb866df0', 'c7b1bd5e-f206-4953-afd2-8a840eb9c009', 'numeric', 'What is 4 − 9?', '{"kind":"number_line","min":-6,"max":5,"step":1,"highlight":[4],"jumps":[{"from":4,"to":-5}]}'::jsonb, '{"value":"-5"}'::jsonb, null, 'Start at 4 on the number line. Subtracting 9 means moving 9 to the left. You land on −5, so 4 − 9 = −5.', 'Adding moves right, subtracting moves left.', 2, 10, 2, true, '{"my":{"prompt":"4 − 9 က ဘယ်လောက်လဲ။","explanation":"ကိန်းမျဉ်းပေါ်က 4 မှာ စပါ။ 9 ကို နုတ်တာက ဘယ်ဘက်ကို 9 ရွှေ့တာပါ။ −5 မှာ ရောက်လို့ 4 − 9 = −5။","hint":"ပေါင်းရင် ညာဘက်ကို၊ နုတ်ရင် ဘယ်ဘက်ကို ရွှေ့ပါ။"},"th":{"prompt":"4 − 9 เท่ากับเท่าไร","explanation":"เริ่มที่ 4 บนเส้นจำนวน การลบ 9 คือเลื่อนไปทางซ้าย 9 ช่อง จะถึง −5 ดังนั้น 4 − 9 = −5","hint":"บวกเลื่อนไปทางขวา ลบเลื่อนไปทางซ้าย"}}'::jsonb),
  ('6e82114a-b54c-4687-8585-7184de8672a9', 'c7b1bd5e-f206-4953-afd2-8a840eb9c009', 'numeric', 'What is 1 − (−8)?', null, '{"value":"9"}'::jsonb, null, 'Subtracting a negative number is the same as adding the positive number. 1 − (−8) = 1 + 8 = 9.', 'Two minus signs together make a plus.', 2, 10, 3, true, '{"my":{"prompt":"1 − (−8) က ဘယ်လောက်လဲ။","explanation":"အနုတ်ကိန်းကို နုတ်တာက အပေါင်းကိန်းကို ပေါင်းတာနဲ့ အတူတူပါ။ 1 − (−8) = 1 + 8 = 9။","hint":"အနုတ်လက္ခဏာ နှစ်ခု ဆက်နေရင် အပေါင်း ဖြစ်တယ်။"},"th":{"prompt":"1 − (−8) เท่ากับเท่าไร","explanation":"การลบจำนวนลบเท่ากับการบวกจำนวนบวก 1 − (−8) = 1 + 8 = 9","hint":"เครื่องหมายลบสองตัวติดกันกลายเป็นบวก"}}'::jsonb),
  ('6f8212dd-b44c-44f4-8685-7317dd867116', 'c7b1bd5e-f206-4953-afd2-8a840eb9c009', 'numeric', 'What is −8 − 9?', '{"kind":"number_line","min":-18,"max":-7,"step":1,"highlight":[-8],"jumps":[{"from":-8,"to":-17}]}'::jsonb, '{"value":"-17"}'::jsonb, null, 'Start at −8 on the number line. Subtracting 9 means moving 9 to the left. You land on −17, so −8 − 9 = −17.', 'Adding moves right, subtracting moves left.', 2, 10, 4, true, '{"my":{"prompt":"−8 − 9 က ဘယ်လောက်လဲ။","explanation":"ကိန်းမျဉ်းပေါ်က −8 မှာ စပါ။ 9 ကို နုတ်တာက ဘယ်ဘက်ကို 9 ရွှေ့တာပါ။ −17 မှာ ရောက်လို့ −8 − 9 = −17။","hint":"ပေါင်းရင် ညာဘက်ကို၊ နုတ်ရင် ဘယ်ဘက်ကို ရွှေ့ပါ။"},"th":{"prompt":"−8 − 9 เท่ากับเท่าไร","explanation":"เริ่มที่ −8 บนเส้นจำนวน การลบ 9 คือเลื่อนไปทางซ้าย 9 ช่อง จะถึง −17 ดังนั้น −8 − 9 = −17","hint":"บวกเลื่อนไปทางขวา ลบเลื่อนไปทางซ้าย"}}'::jsonb),
  ('688207d8-b34c-4361-8385-6e5ee08675cf', 'c7b1bd5e-f206-4953-afd2-8a840eb9c009', 'numeric', 'What is 6 − (−1)?', null, '{"value":"7"}'::jsonb, null, 'Subtracting a negative number is the same as adding the positive number. 6 − (−1) = 6 + 1 = 7.', 'Two minus signs together make a plus.', 2, 10, 5, true, '{"my":{"prompt":"6 − (−1) က ဘယ်လောက်လဲ။","explanation":"အနုတ်ကိန်းကို နုတ်တာက အပေါင်းကိန်းကို ပေါင်းတာနဲ့ အတူတူပါ။ 6 − (−1) = 6 + 1 = 7။","hint":"အနုတ်လက္ခဏာ နှစ်ခု ဆက်နေရင် အပေါင်း ဖြစ်တယ်။"},"th":{"prompt":"6 − (−1) เท่ากับเท่าไร","explanation":"การลบจำนวนลบเท่ากับการบวกจำนวนบวก 6 − (−1) = 6 + 1 = 7","hint":"เครื่องหมายลบสองตัวติดกันกลายเป็นบวก"}}'::jsonb),
  ('90276017-8bcf-4a78-a994-c2c9fe5a509a', '684bf745-e1dd-47ae-9dd8-a6f712cb4d48', 'numeric', 'At noon it was 7°C. At midnight it was −10°C. How many degrees colder was it at midnight?', '{"kind":"thermometer","value":-10}'::jsonb, '{"value":"17"}'::jsonb, null, 'From −10°C up to 0°C is 10 degrees, and from 0°C up to 7°C is 7 degrees. 10 + 7 = 17 degrees.', 'Count up to 0 first, then on to the warmer temperature.', 3, 10, 1, true, '{"my":{"prompt":"နေ့လယ်မှာ 7°C ရှိတယ်။ သန်းခေါင်မှာ −10°C ရှိတယ်။ သန်းခေါင်မှာ ဘယ်နှဒီဂရီ ပိုအေးလဲ။","explanation":"−10°C ကနေ 0°C အထိ 10 ဒီဂရီ၊ 0°C ကနေ 7°C အထိ 7 ဒီဂရီ ရှိတယ်။ 10 + 7 = 17 ဒီဂရီ။","hint":"0 အထိ အရင်ရေပြီး ပိုပူတဲ့ အပူချိန်အထိ ဆက်ရေပါ။"},"th":{"prompt":"ตอนเที่ยงวันอุณหภูมิ 7°C ตอนเที่ยงคืน −10°C เที่ยงคืนหนาวกว่ากี่องศา","explanation":"จาก −10°C ขึ้นไปถึง 0°C คือ 10 องศา และจาก 0°C ขึ้นไปถึง 7°C คือ 7 องศา 10 + 7 = 17 องศา","hint":"นับขึ้นไปถึง 0 ก่อน แล้วนับต่อไปถึงอุณหภูมิที่อุ่นกว่า"}}'::jsonb),
  ('8f275e84-8ccf-4c0b-a894-c136ff5a522d', '684bf745-e1dd-47ae-9dd8-a6f712cb4d48', 'numeric', 'The temperature is 4°C. It rises by 8 degrees. What is the temperature now, in °C?', '{"kind":"thermometer","value":4}'::jsonb, '{"value":"12"}'::jsonb, null, 'Rising means add: 4 + 8 = 12. The temperature is now 12°C.', 'Count up the thermometer.', 3, 10, 2, true, '{"my":{"prompt":"အပူချိန်က 4°C ရှိတယ်။ 8 ဒီဂရီ တက်သွားတယ်။ အခု အပူချိန်က °C ဘယ်လောက်လဲ။","explanation":"တက်တာက ပေါင်းရမယ် - 4 + 8 = 12။ အခု အပူချိန်က 12°C ပါ။","hint":"သာမိုမီတာပေါ်မှာ အပေါ်ကို ရေပါ။"},"th":{"prompt":"อุณหภูมิ 4°C แล้วสูงขึ้น 8 องศา ตอนนี้อุณหภูมิกี่ °C","explanation":"สูงขึ้นแปลว่าบวก: 4 + 8 = 12 ตอนนี้อุณหภูมิ 12°C","hint":"นับขึ้นตามเทอร์โมมิเตอร์"}}'::jsonb),
  ('9227633d-8dcf-4d9e-a794-bfa3fc5a4d74', '684bf745-e1dd-47ae-9dd8-a6f712cb4d48', 'numeric', 'At noon it was 3°C. At midnight it was −9°C. How many degrees colder was it at midnight?', '{"kind":"thermometer","value":-9}'::jsonb, '{"value":"12"}'::jsonb, null, 'From −9°C up to 0°C is 9 degrees, and from 0°C up to 3°C is 3 degrees. 9 + 3 = 12 degrees.', 'Count up to 0 first, then on to the warmer temperature.', 3, 10, 3, true, '{"my":{"prompt":"နေ့လယ်မှာ 3°C ရှိတယ်။ သန်းခေါင်မှာ −9°C ရှိတယ်။ သန်းခေါင်မှာ ဘယ်နှဒီဂရီ ပိုအေးလဲ။","explanation":"−9°C ကနေ 0°C အထိ 9 ဒီဂရီ၊ 0°C ကနေ 3°C အထိ 3 ဒီဂရီ ရှိတယ်။ 9 + 3 = 12 ဒီဂရီ။","hint":"0 အထိ အရင်ရေပြီး ပိုပူတဲ့ အပူချိန်အထိ ဆက်ရေပါ။"},"th":{"prompt":"ตอนเที่ยงวันอุณหภูมิ 3°C ตอนเที่ยงคืน −9°C เที่ยงคืนหนาวกว่ากี่องศา","explanation":"จาก −9°C ขึ้นไปถึง 0°C คือ 9 องศา และจาก 0°C ขึ้นไปถึง 3°C คือ 3 องศา 9 + 3 = 12 องศา","hint":"นับขึ้นไปถึง 0 ก่อน แล้วนับต่อไปถึงอุณหภูมิที่อุ่นกว่า"}}'::jsonb),
  ('912761aa-8ecf-4f31-a694-be10fd5a4f07', '684bf745-e1dd-47ae-9dd8-a6f712cb4d48', 'numeric', 'The temperature is 1°C. It falls by 12 degrees. What is the temperature now, in °C?', '{"kind":"thermometer","value":1}'::jsonb, '{"value":"-11"}'::jsonb, null, 'Falling means subtract: 1 − 12 = −11. The temperature is now −11°C.', 'Count down the thermometer. You may go below zero.', 3, 10, 4, true, '{"my":{"prompt":"အပူချိန်က 1°C ရှိတယ်။ 12 ဒီဂရီ ကျသွားတယ်။ အခု အပူချိန်က °C ဘယ်လောက်လဲ။","explanation":"ကျတာက နုတ်ရမယ် - 1 − 12 = −11။ အခု အပူချိန်က −11°C ပါ။","hint":"သာမိုမီတာပေါ်မှာ အောက်ကို ရေပါ။ သုညအောက် ရောက်နိုင်တယ်။"},"th":{"prompt":"อุณหภูมิ 1°C แล้วลดลง 12 องศา ตอนนี้อุณหภูมิกี่ °C","explanation":"ลดลงแปลว่าลบ: 1 − 12 = −11 ตอนนี้อุณหภูมิ −11°C","hint":"นับลงตามเทอร์โมมิเตอร์ อาจต่ำกว่าศูนย์ได้"}}'::jsonb),
  ('8c2759cb-8fd0-40c4-ad94-c915fa5a4a4e', '684bf745-e1dd-47ae-9dd8-a6f712cb4d48', 'numeric', 'The temperature is 0°C. It falls by 8 degrees. What is the temperature now, in °C?', '{"kind":"thermometer","value":0}'::jsonb, '{"value":"-8"}'::jsonb, null, 'Falling means subtract: 0 − 8 = −8. The temperature is now −8°C.', 'Count down the thermometer. You may go below zero.', 3, 10, 5, true, '{"my":{"prompt":"အပူချိန်က 0°C ရှိတယ်။ 8 ဒီဂရီ ကျသွားတယ်။ အခု အပူချိန်က °C ဘယ်လောက်လဲ။","explanation":"ကျတာက နုတ်ရမယ် - 0 − 8 = −8။ အခု အပူချိန်က −8°C ပါ။","hint":"သာမိုမီတာပေါ်မှာ အောက်ကို ရေပါ။ သုညအောက် ရောက်နိုင်တယ်။"},"th":{"prompt":"อุณหภูมิ 0°C แล้วลดลง 8 องศา ตอนนี้อุณหภูมิกี่ °C","explanation":"ลดลงแปลว่าลบ: 0 − 8 = −8 ตอนนี้อุณหภูมิ −8°C","hint":"นับลงตามเทอร์โมมิเตอร์ อาจต่ำกว่าศูนย์ได้"}}'::jsonb),
  ('1a9f0d6e-3b77-4321-926b-3d386c657c93', 'f60ed9e4-4a14-412f-861e-d27eb1b3f6a9', 'numeric', 'What is the perimeter of a rectangle 14 cm long and 13 cm wide?', '{"kind":"rectangle","width":14,"height":13,"unit":"cm"}'::jsonb, '{"value":"54"}'::jsonb, null, 'Perimeter is the distance all the way around. Add all four sides: 14 + 13 + 14 + 13 = 54 cm. That is the same as 2 × (14 + 13).', 'A rectangle has two long sides and two short sides.', 1, 10, 1, true, '{"my":{"prompt":"အလျား 14 စင်တီမီတာ၊ အနံ 13 စင်တီမီတာ ရှိတဲ့ ထောင့်မှန်စတုဂံရဲ့ ပတ်လည်အနားက ဘယ်လောက်လဲ။","explanation":"ပတ်လည်အနားက ပုံကို တစ်ပတ်ပတ်တဲ့ အကွာအဝေးပါ။ အနား လေးခုလုံးကို ပေါင်းပါ - 14 + 13 + 14 + 13 = 54 စင်တီမီတာ။ ဒါက 2 × (14 + 13) နဲ့ အတူတူပါပဲ။","hint":"ထောင့်မှန်စတုဂံမှာ အနားရှည် နှစ်ခုနဲ့ အနားတို နှစ်ခု ရှိတယ်။"},"th":{"prompt":"สี่เหลี่ยมผืนผ้ายาว 14 ซม. กว้าง 13 ซม. มีความยาวรอบรูปเท่าไร","explanation":"ความยาวรอบรูปคือระยะทางรอบรูปทั้งหมด บวกทั้งสี่ด้าน: 14 + 13 + 14 + 13 = 54 ซม. เท่ากับ 2 × (14 + 13)","hint":"สี่เหลี่ยมผืนผ้ามีด้านยาวสองด้านและด้านสั้นสองด้าน"}}'::jsonb),
  ('1b9f0f01-3a77-418e-936b-3ecb6b657b00', 'f60ed9e4-4a14-412f-861e-d27eb1b3f6a9', 'numeric', 'What is the perimeter of a rectangle 11 cm long and 5 cm wide?', '{"kind":"rectangle","width":11,"height":5,"unit":"cm"}'::jsonb, '{"value":"32"}'::jsonb, null, 'Perimeter is the distance all the way around. Add all four sides: 11 + 5 + 11 + 5 = 32 cm. That is the same as 2 × (11 + 5).', 'A rectangle has two long sides and two short sides.', 1, 10, 2, true, '{"my":{"prompt":"အလျား 11 စင်တီမီတာ၊ အနံ 5 စင်တီမီတာ ရှိတဲ့ ထောင့်မှန်စတုဂံရဲ့ ပတ်လည်အနားက ဘယ်လောက်လဲ။","explanation":"ပတ်လည်အနားက ပုံကို တစ်ပတ်ပတ်တဲ့ အကွာအဝေးပါ။ အနား လေးခုလုံးကို ပေါင်းပါ - 11 + 5 + 11 + 5 = 32 စင်တီမီတာ။ ဒါက 2 × (11 + 5) နဲ့ အတူတူပါပဲ။","hint":"ထောင့်မှန်စတုဂံမှာ အနားရှည် နှစ်ခုနဲ့ အနားတို နှစ်ခု ရှိတယ်။"},"th":{"prompt":"สี่เหลี่ยมผืนผ้ายาว 11 ซม. กว้าง 5 ซม. มีความยาวรอบรูปเท่าไร","explanation":"ความยาวรอบรูปคือระยะทางรอบรูปทั้งหมด บวกทั้งสี่ด้าน: 11 + 5 + 11 + 5 = 32 ซม. เท่ากับ 2 × (11 + 5)","hint":"สี่เหลี่ยมผืนผ้ามีด้านยาวสองด้านและด้านสั้นสองด้าน"}}'::jsonb),
  ('189f0a48-3977-4ffb-946b-405e6e657fb9', 'f60ed9e4-4a14-412f-861e-d27eb1b3f6a9', 'numeric', 'A square has a perimeter of 36 cm. How long is each side, in cm?', null, '{"value":"9"}'::jsonb, null, 'A square has 4 equal sides, so divide the perimeter by 4: 36 ÷ 4 = 9. Each side is 9 cm.', 'A square has 4 sides that are all the same length.', 1, 10, 3, true, '{"my":{"prompt":"စတုရန်းတစ်ခုရဲ့ ပတ်လည်အနားက 36 cm ဖြစ်တယ်။ အနားတစ်ခုစီက cm ဘယ်လောက် ရှည်လဲ။","explanation":"စတုရန်းမှာ အနားညီ 4 ခု ရှိလို့ ပတ်လည်အနားကို 4 နဲ့ စားပါ - 36 ÷ 4 = 9။ အနားတစ်ခုစီက 9 cm ပါ။","hint":"စတုရန်းမှာ အလျား အားလုံးတူတဲ့ အနား 4 ခု ရှိတယ်။"},"th":{"prompt":"สี่เหลี่ยมจัตุรัสมีความยาวรอบรูป 36 cm แต่ละด้านยาวกี่ cm","explanation":"สี่เหลี่ยมจัตุรัสมี 4 ด้านยาวเท่ากัน จึงหารความยาวรอบรูปด้วย 4: 36 ÷ 4 = 9 แต่ละด้านยาว 9 cm","hint":"สี่เหลี่ยมจัตุรัสมี 4 ด้านที่ยาวเท่ากันทั้งหมด"}}'::jsonb),
  ('199f0bdb-3877-4e68-956b-41f16d657e26', 'f60ed9e4-4a14-412f-861e-d27eb1b3f6a9', 'numeric', 'What is the perimeter of a rectangle 17 m long and 20 m wide?', '{"kind":"rectangle","width":17,"height":20,"unit":"m"}'::jsonb, '{"value":"74"}'::jsonb, null, 'Perimeter is the distance all the way around. Add all four sides: 17 + 20 + 17 + 20 = 74 m. That is the same as 2 × (17 + 20).', 'A rectangle has two long sides and two short sides.', 1, 10, 4, true, '{"my":{"prompt":"အလျား 17 မီတာ၊ အနံ 20 မီတာ ရှိတဲ့ ထောင့်မှန်စတုဂံရဲ့ ပတ်လည်အနားက ဘယ်လောက်လဲ။","explanation":"ပတ်လည်အနားက ပုံကို တစ်ပတ်ပတ်တဲ့ အကွာအဝေးပါ။ အနား လေးခုလုံးကို ပေါင်းပါ - 17 + 20 + 17 + 20 = 74 မီတာ။ ဒါက 2 × (17 + 20) နဲ့ အတူတူပါပဲ။","hint":"ထောင့်မှန်စတုဂံမှာ အနားရှည် နှစ်ခုနဲ့ အနားတို နှစ်ခု ရှိတယ်။"},"th":{"prompt":"สี่เหลี่ยมผืนผ้ายาว 17 ม. กว้าง 20 ม. มีความยาวรอบรูปเท่าไร","explanation":"ความยาวรอบรูปคือระยะทางรอบรูปทั้งหมด บวกทั้งสี่ด้าน: 17 + 20 + 17 + 20 = 74 ม. เท่ากับ 2 × (17 + 20)","hint":"สี่เหลี่ยมผืนผ้ามีด้านยาวสองด้านและด้านสั้นสองด้าน"}}'::jsonb),
  ('1e9f13ba-3f77-496d-966b-4384706582df', 'f60ed9e4-4a14-412f-861e-d27eb1b3f6a9', 'numeric', 'What is the perimeter of a rectangle 7 cm long and 2 cm wide?', '{"kind":"rectangle","width":7,"height":2,"unit":"cm"}'::jsonb, '{"value":"18"}'::jsonb, null, 'Perimeter is the distance all the way around. Add all four sides: 7 + 2 + 7 + 2 = 18 cm. That is the same as 2 × (7 + 2).', 'A rectangle has two long sides and two short sides.', 1, 10, 5, true, '{"my":{"prompt":"အလျား 7 စင်တီမီတာ၊ အနံ 2 စင်တီမီတာ ရှိတဲ့ ထောင့်မှန်စတုဂံရဲ့ ပတ်လည်အနားက ဘယ်လောက်လဲ။","explanation":"ပတ်လည်အနားက ပုံကို တစ်ပတ်ပတ်တဲ့ အကွာအဝေးပါ။ အနား လေးခုလုံးကို ပေါင်းပါ - 7 + 2 + 7 + 2 = 18 စင်တီမီတာ။ ဒါက 2 × (7 + 2) နဲ့ အတူတူပါပဲ။","hint":"ထောင့်မှန်စတုဂံမှာ အနားရှည် နှစ်ခုနဲ့ အနားတို နှစ်ခု ရှိတယ်။"},"th":{"prompt":"สี่เหลี่ยมผืนผ้ายาว 7 ซม. กว้าง 2 ซม. มีความยาวรอบรูปเท่าไร","explanation":"ความยาวรอบรูปคือระยะทางรอบรูปทั้งหมด บวกทั้งสี่ด้าน: 7 + 2 + 7 + 2 = 18 ซม. เท่ากับ 2 × (7 + 2)","hint":"สี่เหลี่ยมผืนผ้ามีด้านยาวสองด้านและด้านสั้นสองด้าน"}}'::jsonb),
  ('d536603b-a0b4-424c-96b1-4cbd1f8395de', '111e6d59-4819-412a-8d07-1f638046fd2c', 'numeric', 'What is the area of a rectangle 3 cm long and 7 cm wide, in cm²?', '{"kind":"rectangle","width":3,"height":7,"unit":"cm","showGrid":true}'::jsonb, '{"value":"21"}'::jsonb, null, 'Area = length × width. 3 × 7 = 21, so the area is 21 cm². That is 7 rows of 3 squares.', 'Multiply the length by the width.', 2, 10, 1, true, '{"my":{"prompt":"အလျား 3 စင်တီမီတာ၊ အနံ 7 စင်တီမီတာ ရှိတဲ့ ထောင့်မှန်စတုဂံရဲ့ ဧရိယာက စတုရန်းစင်တီမီတာ ဘယ်လောက်လဲ။","explanation":"ဧရိယာ = အလျား × အနံ။ 3 × 7 = 21 ဖြစ်လို့ ဧရိယာက 21 စတုရန်းစင်တီမီတာ ပါ။ ဒါက 3 ကွက်စီပါတဲ့ အတန်း 7 တန်းပါ။","hint":"အလျားကို အနံနဲ့ မြှောက်ပါ။"},"th":{"prompt":"สี่เหลี่ยมผืนผ้ายาว 3 ซม. กว้าง 7 ซม. มีพื้นที่กี่ ตร.ซม.","explanation":"พื้นที่ = ยาว × กว้าง 3 × 7 = 21 พื้นที่จึงเป็น 21 ตร.ซม. คือ 7 แถว แถวละ 3 ช่อง","hint":"นำความยาวคูณความกว้าง"}}'::jsonb),
  ('d4365ea8-a1b4-43df-95b1-4b2a20839771', '111e6d59-4819-412a-8d07-1f638046fd2c', 'numeric', 'What is the area of a rectangle 7 cm long and 6 cm wide, in cm²?', '{"kind":"rectangle","width":7,"height":6,"unit":"cm","showGrid":true}'::jsonb, '{"value":"42"}'::jsonb, null, 'Area = length × width. 7 × 6 = 42, so the area is 42 cm². That is 6 rows of 7 squares.', 'Multiply the length by the width.', 2, 10, 2, true, '{"my":{"prompt":"အလျား 7 စင်တီမီတာ၊ အနံ 6 စင်တီမီတာ ရှိတဲ့ ထောင့်မှန်စတုဂံရဲ့ ဧရိယာက စတုရန်းစင်တီမီတာ ဘယ်လောက်လဲ။","explanation":"ဧရိယာ = အလျား × အနံ။ 7 × 6 = 42 ဖြစ်လို့ ဧရိယာက 42 စတုရန်းစင်တီမီတာ ပါ။ ဒါက 7 ကွက်စီပါတဲ့ အတန်း 6 တန်းပါ။","hint":"အလျားကို အနံနဲ့ မြှောက်ပါ။"},"th":{"prompt":"สี่เหลี่ยมผืนผ้ายาว 7 ซม. กว้าง 6 ซม. มีพื้นที่กี่ ตร.ซม.","explanation":"พื้นที่ = ยาว × กว้าง 7 × 6 = 42 พื้นที่จึงเป็น 42 ตร.ซม. คือ 6 แถว แถวละ 7 ช่อง","hint":"นำความยาวคูณความกว้าง"}}'::jsonb),
  ('d7366361-a2b4-4572-94b1-49971d8392b8', '111e6d59-4819-412a-8d07-1f638046fd2c', 'numeric', 'What is the area of a rectangle 6 cm long and 5 cm wide, in cm²?', '{"kind":"rectangle","width":6,"height":5,"unit":"cm","showGrid":false}'::jsonb, '{"value":"30"}'::jsonb, null, 'Area = length × width. 6 × 5 = 30, so the area is 30 cm².', 'Multiply the length by the width.', 2, 10, 3, true, '{"my":{"prompt":"အလျား 6 စင်တီမီတာ၊ အနံ 5 စင်တီမီတာ ရှိတဲ့ ထောင့်မှန်စတုဂံရဲ့ ဧရိယာက စတုရန်းစင်တီမီတာ ဘယ်လောက်လဲ။","explanation":"ဧရိယာ = အလျား × အနံ။ 6 × 5 = 30 ဖြစ်လို့ ဧရိယာက 30 စတုရန်းစင်တီမီတာ ပါ။","hint":"အလျားကို အနံနဲ့ မြှောက်ပါ။"},"th":{"prompt":"สี่เหลี่ยมผืนผ้ายาว 6 ซม. กว้าง 5 ซม. มีพื้นที่กี่ ตร.ซม.","explanation":"พื้นที่ = ยาว × กว้าง 6 × 5 = 30 พื้นที่จึงเป็น 30 ตร.ซม.","hint":"นำความยาวคูณความกว้าง"}}'::jsonb),
  ('d63661ce-a3b4-4705-93b1-48041e83944b', '111e6d59-4819-412a-8d07-1f638046fd2c', 'numeric', 'A rectangle has an area of 45 cm² and a width of 5 cm. How long is it, in cm?', null, '{"value":"9"}'::jsonb, null, 'Area = length × width, so length = area ÷ width. 45 ÷ 5 = 9 cm. Check: 9 × 5 = 45.', 'Which number times 5 makes 45?', 2, 10, 4, true, '{"my":{"prompt":"ထောင့်မှန်စတုဂံတစ်ခုရဲ့ ဧရိယာက 45 စတုရန်းစင်တီမီတာ၊ အနံက 5 စင်တီမီတာ ဖြစ်တယ်။ အလျားက စင်တီမီတာ ဘယ်လောက်လဲ။","explanation":"ဧရိယာ = အလျား × အနံ ဖြစ်လို့ အလျား = ဧရိယာ ÷ အနံ။ 45 ÷ 5 = 9 စင်တီမီတာ။ စစ်ကြည့်ပါ - 9 × 5 = 45။","hint":"ဘယ်ဂဏန်းကို 5 နဲ့ မြှောက်ရင် 45 ဖြစ်လဲ။"},"th":{"prompt":"สี่เหลี่ยมผืนผ้ามีพื้นที่ 45 ตร.ซม. และกว้าง 5 ซม. ยาวกี่ ซม.","explanation":"พื้นที่ = ยาว × กว้าง ดังนั้น ยาว = พื้นที่ ÷ กว้าง 45 ÷ 5 = 9 ซม. ตรวจ: 9 × 5 = 45","hint":"จำนวนใดคูณ 5 ได้ 45"}}'::jsonb),
  ('d9366687-9cb4-4c00-92b1-467123839c2a', '111e6d59-4819-412a-8d07-1f638046fd2c', 'numeric', 'What is the area of a rectangle 8 cm long and 8 cm wide, in cm²?', '{"kind":"rectangle","width":8,"height":8,"unit":"cm","showGrid":false}'::jsonb, '{"value":"64"}'::jsonb, null, 'Area = length × width. 8 × 8 = 64, so the area is 64 cm².', 'Multiply the length by the width.', 2, 10, 5, true, '{"my":{"prompt":"အလျား 8 စင်တီမီတာ၊ အနံ 8 စင်တီမီတာ ရှိတဲ့ ထောင့်မှန်စတုဂံရဲ့ ဧရိယာက စတုရန်းစင်တီမီတာ ဘယ်လောက်လဲ။","explanation":"ဧရိယာ = အလျား × အနံ။ 8 × 8 = 64 ဖြစ်လို့ ဧရိယာက 64 စတုရန်းစင်တီမီတာ ပါ။","hint":"အလျားကို အနံနဲ့ မြှောက်ပါ။"},"th":{"prompt":"สี่เหลี่ยมผืนผ้ายาว 8 ซม. กว้าง 8 ซม. มีพื้นที่กี่ ตร.ซม.","explanation":"พื้นที่ = ยาว × กว้าง 8 × 8 = 64 พื้นที่จึงเป็น 64 ตร.ซม.","hint":"นำความยาวคูณความกว้าง"}}'::jsonb),
  ('9035d116-0efb-4c4b-ae4d-a670bf68684d', '8744379c-ed0a-436d-bfb0-dfce89ad5c57', 'numeric', 'A triangle has a base of 10 cm and a height of 11 cm. What is its area, in cm²?', '{"kind":"triangle","base":10,"height":11,"unit":"cm"}'::jsonb, '{"value":"55"}'::jsonb, null, 'A triangle is half of a rectangle with the same base and height. Area = 1/2 × base × height = 1/2 × 10 × 11 = 55 cm².', 'Find base × height, then halve it.', 3, 10, 1, true, '{"my":{"prompt":"တြိဂံတစ်ခုမှာ အခြေ 10 စင်တီမီတာနဲ့ အမြင့် 11 စင်တီမီတာ ရှိတယ်။ ဧရိယာက စတုရန်းစင်တီမီတာ ဘယ်လောက်လဲ။","explanation":"တြိဂံက အခြေနဲ့ အမြင့် တူတဲ့ ထောင့်မှန်စတုဂံရဲ့ တစ်ဝက်ပါ။ ဧရိယာ = 1/2 × အခြေ × အမြင့် = 1/2 × 10 × 11 = 55 စတုရန်းစင်တီမီတာ။","hint":"အခြေ × အမြင့် ကို ရှာပြီး တစ်ဝက်ပိုင်းပါ။"},"th":{"prompt":"สามเหลี่ยมมีฐาน 10 ซม. และสูง 11 ซม. มีพื้นที่กี่ ตร.ซม.","explanation":"สามเหลี่ยมคือครึ่งหนึ่งของสี่เหลี่ยมผืนผ้าที่มีฐานและความสูงเท่ากัน พื้นที่ = 1/2 × ฐาน × สูง = 1/2 × 10 × 11 = 55 ตร.ซม.","hint":"หาฐาน × สูง แล้วหารครึ่ง"}}'::jsonb),
  ('9135d2a9-0dfb-4ab8-af4d-a803be6866ba', '8744379c-ed0a-436d-bfb0-dfce89ad5c57', 'numeric', 'A triangle has a base of 12 cm and a height of 10 cm. What is its area, in cm²?', '{"kind":"triangle","base":12,"height":10,"unit":"cm"}'::jsonb, '{"value":"60"}'::jsonb, null, 'A triangle is half of a rectangle with the same base and height. Area = 1/2 × base × height = 1/2 × 12 × 10 = 60 cm².', 'Find base × height, then halve it.', 3, 10, 2, true, '{"my":{"prompt":"တြိဂံတစ်ခုမှာ အခြေ 12 စင်တီမီတာနဲ့ အမြင့် 10 စင်တီမီတာ ရှိတယ်။ ဧရိယာက စတုရန်းစင်တီမီတာ ဘယ်လောက်လဲ။","explanation":"တြိဂံက အခြေနဲ့ အမြင့် တူတဲ့ ထောင့်မှန်စတုဂံရဲ့ တစ်ဝက်ပါ။ ဧရိယာ = 1/2 × အခြေ × အမြင့် = 1/2 × 12 × 10 = 60 စတုရန်းစင်တီမီတာ။","hint":"အခြေ × အမြင့် ကို ရှာပြီး တစ်ဝက်ပိုင်းပါ။"},"th":{"prompt":"สามเหลี่ยมมีฐาน 12 ซม. และสูง 10 ซม. มีพื้นที่กี่ ตร.ซม.","explanation":"สามเหลี่ยมคือครึ่งหนึ่งของสี่เหลี่ยมผืนผ้าที่มีฐานและความสูงเท่ากัน พื้นที่ = 1/2 × ฐาน × สูง = 1/2 × 12 × 10 = 60 ตร.ซม.","hint":"หาฐาน × สูง แล้วหารครึ่ง"}}'::jsonb),
  ('8e35cdf0-10fb-4f71-b04d-a996bd686527', '8744379c-ed0a-436d-bfb0-dfce89ad5c57', 'numeric', 'A rectangle has an area of 25 cm² and a width of 5 cm. How long is it, in cm?', null, '{"value":"5"}'::jsonb, null, 'Area = length × width, so length = area ÷ width. 25 ÷ 5 = 5 cm. Check: 5 × 5 = 25.', 'Which number times 5 makes 25?', 3, 10, 3, true, '{"my":{"prompt":"ထောင့်မှန်စတုဂံတစ်ခုရဲ့ ဧရိယာက 25 စတုရန်းစင်တီမီတာ၊ အနံက 5 စင်တီမီတာ ဖြစ်တယ်။ အလျားက စင်တီမီတာ ဘယ်လောက်လဲ။","explanation":"ဧရိယာ = အလျား × အနံ ဖြစ်လို့ အလျား = ဧရိယာ ÷ အနံ။ 25 ÷ 5 = 5 စင်တီမီတာ။ စစ်ကြည့်ပါ - 5 × 5 = 25။","hint":"ဘယ်ဂဏန်းကို 5 နဲ့ မြှောက်ရင် 25 ဖြစ်လဲ။"},"th":{"prompt":"สี่เหลี่ยมผืนผ้ามีพื้นที่ 25 ตร.ซม. และกว้าง 5 ซม. ยาวกี่ ซม.","explanation":"พื้นที่ = ยาว × กว้าง ดังนั้น ยาว = พื้นที่ ÷ กว้าง 25 ÷ 5 = 5 ซม. ตรวจ: 5 × 5 = 25","hint":"จำนวนใดคูณ 5 ได้ 25"}}'::jsonb),
  ('8f35cf83-0ffb-4dde-b14d-ab29bc686394', '8744379c-ed0a-436d-bfb0-dfce89ad5c57', 'numeric', 'A garden is 10 m long and 6 m wide. What is its area, in m²?', '{"kind":"rectangle","width":10,"height":6,"unit":"m"}'::jsonb, '{"value":"60"}'::jsonb, null, 'Area = length × width = 10 × 6 = 60. The garden has an area of 60 m².', 'Multiply the length by the width.', 3, 10, 4, true, '{"my":{"prompt":"ဥယျာဉ်တစ်ခုက 10 m ရှည်ပြီး 6 m ကျယ်တယ်။ ဧရိယာက m² ဘယ်လောက်လဲ။","explanation":"ဧရိယာ = အလျား × အနံ = 10 × 6 = 60။ ဥယျာဉ်ရဲ့ ဧရိယာက 60 m² ပါ။","hint":"အလျားကို အနံနဲ့ မြှောက်ပါ။"},"th":{"prompt":"สวนยาว 10 m กว้าง 6 m มีพื้นที่กี่ m²","explanation":"พื้นที่ = ยาว × กว้าง = 10 × 6 = 60 สวนมีพื้นที่ 60 m²","hint":"นำความยาวคูณความกว้าง"}}'::jsonb),
  ('9435d762-12fb-4297-b24d-acbcbb686201', '8744379c-ed0a-436d-bfb0-dfce89ad5c57', 'numeric', 'A triangle has a base of 14 cm and a height of 4 cm. What is its area, in cm²?', '{"kind":"triangle","base":14,"height":4,"unit":"cm"}'::jsonb, '{"value":"28"}'::jsonb, null, 'A triangle is half of a rectangle with the same base and height. Area = 1/2 × base × height = 1/2 × 14 × 4 = 28 cm².', 'Find base × height, then halve it.', 3, 10, 5, true, '{"my":{"prompt":"တြိဂံတစ်ခုမှာ အခြေ 14 စင်တီမီတာနဲ့ အမြင့် 4 စင်တီမီတာ ရှိတယ်။ ဧရိယာက စတုရန်းစင်တီမီတာ ဘယ်လောက်လဲ။","explanation":"တြိဂံက အခြေနဲ့ အမြင့် တူတဲ့ ထောင့်မှန်စတုဂံရဲ့ တစ်ဝက်ပါ။ ဧရိယာ = 1/2 × အခြေ × အမြင့် = 1/2 × 14 × 4 = 28 စတုရန်းစင်တီမီတာ။","hint":"အခြေ × အမြင့် ကို ရှာပြီး တစ်ဝက်ပိုင်းပါ။"},"th":{"prompt":"สามเหลี่ยมมีฐาน 14 ซม. และสูง 4 ซม. มีพื้นที่กี่ ตร.ซม.","explanation":"สามเหลี่ยมคือครึ่งหนึ่งของสี่เหลี่ยมผืนผ้าที่มีฐานและความสูงเท่ากัน พื้นที่ = 1/2 × ฐาน × สูง = 1/2 × 14 × 4 = 28 ตร.ซม.","hint":"หาฐาน × สูง แล้วหารครึ่ง"}}'::jsonb),
  ('ecc91ff2-28b2-4f29-aea1-d1acc8f72243', '327c2d58-9405-4fbf-aada-190aa131e319', 'numeric', 'If n = 6, what is 3n − 7?', null, '{"value":"11"}'::jsonb, null, '3n means 3 × n. Replace n with 6: 3 × 6 = 18. Then 18 − 7 = 11.', '3n means 3 times n.', 1, 10, 1, true, '{"my":{"prompt":"n = 6 ဆိုရင် 3n − 7 က ဘယ်လောက်လဲ။","explanation":"3n ဆိုတာ 3 × n ပါ။ n နေရာမှာ 6 ကို အစားထိုးပါ - 3 × 6 = 18။ ပြီးရင် 18 − 7 = 11။","hint":"3n ဆိုတာ 3 ကို n နဲ့ မြှောက်တာပါ။"},"th":{"prompt":"ถ้า n = 6 แล้ว 3n − 7 เท่ากับเท่าไร","explanation":"3n หมายถึง 3 × n แทน n ด้วย 6: 3 × 6 = 18 แล้ว 18 − 7 = 11","hint":"3n หมายถึง 3 คูณ n"}}'::jsonb),
  ('edc92185-27b2-4d96-afa1-d33fc7f720b0', '327c2d58-9405-4fbf-aada-190aa131e319', 'numeric', 'If n = 8, what is 3n + 2?', null, '{"value":"26"}'::jsonb, null, '3n means 3 × n. Replace n with 8: 3 × 8 = 24. Then 24 + 2 = 26.', '3n means 3 times n.', 1, 10, 2, true, '{"my":{"prompt":"n = 8 ဆိုရင် 3n + 2 က ဘယ်လောက်လဲ။","explanation":"3n ဆိုတာ 3 × n ပါ။ n နေရာမှာ 8 ကို အစားထိုးပါ - 3 × 8 = 24။ ပြီးရင် 24 + 2 = 26။","hint":"3n ဆိုတာ 3 ကို n နဲ့ မြှောက်တာပါ။"},"th":{"prompt":"ถ้า n = 8 แล้ว 3n + 2 เท่ากับเท่าไร","explanation":"3n หมายถึง 3 × n แทน n ด้วย 8: 3 × 8 = 24 แล้ว 24 + 2 = 26","hint":"3n หมายถึง 3 คูณ n"}}'::jsonb),
  ('eac91ccc-26b2-4c03-b0a1-d4d2caf72569', '327c2d58-9405-4fbf-aada-190aa131e319', 'multiple_choice', 'Which expression means "multiply a number n by 4, then add 3"?', null, '{"value":"c"}'::jsonb, '[{"id":"a","label":"4 + 3n"},{"id":"b","label":"n + 4 + 3"},{"id":"c","label":"4n + 3"},{"id":"d","label":"3n + 4"}]'::jsonb, 'Multiplying n by 4 gives 4n. Adding 3 gives 4n + 3.', 'Write the multiplying part first.', 1, 10, 3, true, '{"my":{"prompt":"ဘယ်ကိန်းတန်းက \"ဂဏန်း n ကို 4 နဲ့ မြှောက်ပြီး 3 ပေါင်းပါ\" ကို ဆိုလိုလဲ။","explanation":"n ကို 4 နဲ့ မြှောက်ရင် 4n ရတယ်။ 3 ပေါင်းရင် 4n + 3 ရတယ်။","hint":"မြှောက်တဲ့ အပိုင်းကို အရင်ရေးပါ။"},"th":{"prompt":"นิพจน์ใดหมายถึง \"คูณจำนวน n ด้วย 4 แล้วบวก 3\"","explanation":"คูณ n ด้วย 4 ได้ 4n บวก 3 ได้ 4n + 3","hint":"เขียนส่วนที่เป็นการคูณก่อน"}}'::jsonb),
  ('ebc91e5f-25b2-4a70-b1a1-d665c9f723d6', '327c2d58-9405-4fbf-aada-190aa131e319', 'numeric', 'If n = 5, what is 5n + 7?', null, '{"value":"32"}'::jsonb, null, '5n means 5 × n. Replace n with 5: 5 × 5 = 25. Then 25 + 7 = 32.', '5n means 5 times n.', 1, 10, 4, true, '{"my":{"prompt":"n = 5 ဆိုရင် 5n + 7 က ဘယ်လောက်လဲ။","explanation":"5n ဆိုတာ 5 × n ပါ။ n နေရာမှာ 5 ကို အစားထိုးပါ - 5 × 5 = 25။ ပြီးရင် 25 + 7 = 32။","hint":"5n ဆိုတာ 5 ကို n နဲ့ မြှောက်တာပါ။"},"th":{"prompt":"ถ้า n = 5 แล้ว 5n + 7 เท่ากับเท่าไร","explanation":"5n หมายถึง 5 × n แทน n ด้วย 5: 5 × 5 = 25 แล้ว 25 + 7 = 32","hint":"5n หมายถึง 5 คูณ n"}}'::jsonb),
  ('e8c919a6-2cb2-4575-aaa1-cb60ccf7288f', '327c2d58-9405-4fbf-aada-190aa131e319', 'numeric', 'If n = 9, what is 2n + 6?', null, '{"value":"24"}'::jsonb, null, '2n means 2 × n. Replace n with 9: 2 × 9 = 18. Then 18 + 6 = 24.', '2n means 2 times n.', 1, 10, 5, true, '{"my":{"prompt":"n = 9 ဆိုရင် 2n + 6 က ဘယ်လောက်လဲ။","explanation":"2n ဆိုတာ 2 × n ပါ။ n နေရာမှာ 9 ကို အစားထိုးပါ - 2 × 9 = 18။ ပြီးရင် 18 + 6 = 24။","hint":"2n ဆိုတာ 2 ကို n နဲ့ မြှောက်တာပါ။"},"th":{"prompt":"ถ้า n = 9 แล้ว 2n + 6 เท่ากับเท่าไร","explanation":"2n หมายถึง 2 × n แทน n ด้วย 9: 2 × 9 = 18 แล้ว 18 + 6 = 24","hint":"2n หมายถึง 2 คูณ n"}}'::jsonb),
  ('0ef8322b-20e1-426c-b864-3a451a2d35fe', 'ee175789-43e1-4c82-918a-4b0346c8d77c', 'numeric', 'Solve: 6x = 72. What is x?', null, '{"value":"12"}'::jsonb, null, '6x means 6 × x. Divide both sides by 6: x = 72 ÷ 6 = 12. Check: 6 × 12 = 72.', 'Do the opposite of multiplying.', 2, 10, 1, true, '{"my":{"prompt":"ဖြေရှင်းပါ - 6x = 72။ x က ဘာလဲ။","explanation":"6x ဆိုတာ 6 × x ပါ။ နှစ်ဘက်လုံးကို 6 နဲ့ စားပါ - x = 72 ÷ 6 = 12။ စစ်ကြည့်ပါ - 6 × 12 = 72။","hint":"မြှောက်ခြင်းရဲ့ ဆန့်ကျင်ဘက်ကို လုပ်ပါ။"},"th":{"prompt":"แก้สมการ: 6x = 72 x เท่ากับเท่าไร","explanation":"6x หมายถึง 6 × x หารทั้งสองข้างด้วย 6: x = 72 ÷ 6 = 12 ตรวจ: 6 × 12 = 72","hint":"ทำสิ่งตรงข้ามกับการคูณ"}}'::jsonb),
  ('0df83098-21e1-43ff-b764-38b21b2d3791', 'ee175789-43e1-4c82-918a-4b0346c8d77c', 'numeric', 'Solve: 7x = 77. What is x?', null, '{"value":"11"}'::jsonb, null, '7x means 7 × x. Divide both sides by 7: x = 77 ÷ 7 = 11. Check: 7 × 11 = 77.', 'Do the opposite of multiplying.', 2, 10, 2, true, '{"my":{"prompt":"ဖြေရှင်းပါ - 7x = 77။ x က ဘာလဲ။","explanation":"7x ဆိုတာ 7 × x ပါ။ နှစ်ဘက်လုံးကို 7 နဲ့ စားပါ - x = 77 ÷ 7 = 11။ စစ်ကြည့်ပါ - 7 × 11 = 77။","hint":"မြှောက်ခြင်းရဲ့ ဆန့်ကျင်ဘက်ကို လုပ်ပါ။"},"th":{"prompt":"แก้สมการ: 7x = 77 x เท่ากับเท่าไร","explanation":"7x หมายถึง 7 × x หารทั้งสองข้างด้วย 7: x = 77 ÷ 7 = 11 ตรวจ: 7 × 11 = 77","hint":"ทำสิ่งตรงข้ามกับการคูณ"}}'::jsonb),
  ('10f83551-22e1-4592-b664-371f182d32d8', 'ee175789-43e1-4c82-918a-4b0346c8d77c', 'numeric', 'Solve: 3x + 5 = 38. What is x?', null, '{"value":"11"}'::jsonb, null, 'First subtract 5 from both sides: 3x = 38 − 5 = 33. Then divide both sides by 3: x = 33 ÷ 3 = 11. Check: 3 × 11 + 5 = 38.', 'Undo the + 5 first, then undo the × 3.', 2, 10, 3, true, '{"my":{"prompt":"ဖြေရှင်းပါ - 3x + 5 = 38။ x က ဘာလဲ။","explanation":"အရင်ဆုံး နှစ်ဘက်လုံးကနေ 5 နုတ်ပါ - 3x = 38 − 5 = 33။ ပြီးရင် နှစ်ဘက်လုံးကို 3 နဲ့ စားပါ - x = 33 ÷ 3 = 11။ စစ်ကြည့်ပါ - 3 × 11 + 5 = 38။","hint":"+ 5 ကို အရင်ဖြုတ်ပြီး × 3 ကို ဖြုတ်ပါ။"},"th":{"prompt":"แก้สมการ: 3x + 5 = 38 x เท่ากับเท่าไร","explanation":"ขั้นแรกลบ 5 ทั้งสองข้าง: 3x = 38 − 5 = 33 แล้วหารทั้งสองข้างด้วย 3: x = 33 ÷ 3 = 11 ตรวจ: 3 × 11 + 5 = 38","hint":"ย้อน + 5 ก่อน แล้วย้อน × 3"}}'::jsonb),
  ('0ff833be-23e1-4725-b564-358c192d346b', 'ee175789-43e1-4c82-918a-4b0346c8d77c', 'numeric', 'Solve: x + 8 = 16. What is x?', null, '{"value":"8"}'::jsonb, null, 'Subtract 8 from both sides to get x on its own: x = 16 − 8 = 8. Check: 8 + 8 = 16.', 'Do the opposite of adding.', 2, 10, 4, true, '{"my":{"prompt":"ဖြေရှင်းပါ - x + 8 = 16။ x က ဘာလဲ။","explanation":"x တစ်ခုတည်း ကျန်အောင် နှစ်ဘက်လုံးကနေ 8 နုတ်ပါ - x = 16 − 8 = 8။ စစ်ကြည့်ပါ - 8 + 8 = 16။","hint":"ပေါင်းခြင်းရဲ့ ဆန့်ကျင်ဘက်ကို လုပ်ပါ။"},"th":{"prompt":"แก้สมการ: x + 8 = 16 x เท่ากับเท่าไร","explanation":"ลบ 8 ทั้งสองข้างเพื่อให้เหลือ x ตัวเดียว: x = 16 − 8 = 8 ตรวจ: 8 + 8 = 16","hint":"ทำสิ่งตรงข้ามกับการบวก"}}'::jsonb),
  ('12f83877-1ce1-4c20-b464-33f91e2d3c4a', 'ee175789-43e1-4c82-918a-4b0346c8d77c', 'numeric', 'Solve: 6x + 1 = 43. What is x?', null, '{"value":"7"}'::jsonb, null, 'First subtract 1 from both sides: 6x = 43 − 1 = 42. Then divide both sides by 6: x = 42 ÷ 6 = 7. Check: 6 × 7 + 1 = 43.', 'Undo the + 1 first, then undo the × 6.', 2, 10, 5, true, '{"my":{"prompt":"ဖြေရှင်းပါ - 6x + 1 = 43။ x က ဘာလဲ။","explanation":"အရင်ဆုံး နှစ်ဘက်လုံးကနေ 1 နုတ်ပါ - 6x = 43 − 1 = 42။ ပြီးရင် နှစ်ဘက်လုံးကို 6 နဲ့ စားပါ - x = 42 ÷ 6 = 7။ စစ်ကြည့်ပါ - 6 × 7 + 1 = 43။","hint":"+ 1 ကို အရင်ဖြုတ်ပြီး × 6 ကို ဖြုတ်ပါ။"},"th":{"prompt":"แก้สมการ: 6x + 1 = 43 x เท่ากับเท่าไร","explanation":"ขั้นแรกลบ 1 ทั้งสองข้าง: 6x = 43 − 1 = 42 แล้วหารทั้งสองข้างด้วย 6: x = 42 ÷ 6 = 7 ตรวจ: 6 × 7 + 1 = 43","hint":"ย้อน + 1 ก่อน แล้วย้อน × 6"}}'::jsonb),
  ('03c00f25-1af6-4288-8651-dd1ff6180c9a', 'a71c0567-02dd-4d66-8368-3db11a369328', 'numeric', 'Tickets cost $4 each. Kai buys 3 tickets and pays with $20. How many dollars of change does Kai get?', null, '{"value":"8"}'::jsonb, null, 'Step 1: total cost = 3 × $4 = $12. Step 2: change = $20 − $12 = $8.', 'First find the total cost of the tickets.', 3, 10, 1, true, '{"my":{"prompt":"လက်မှတ်တစ်စောင် $4 ကျတယ်။ ကောင်း က လက်မှတ် 3 စောင် ဝယ်ပြီး $20 ပေးတယ်။ ကောင်း ပြန်အမ်းငွေ ဘယ်နှဒေါ်လာ ရလဲ။","explanation":"အဆင့် 1 - စုစုပေါင်း ကုန်ကျငွေ = 3 × $4 = $12။ အဆင့် 2 - ပြန်အမ်းငွေ = $20 − $12 = $8။","hint":"လက်မှတ်တွေရဲ့ စုစုပေါင်း ကုန်ကျငွေကို အရင်ရှာပါ။"},"th":{"prompt":"ตั๋วราคาใบละ $4 โอ๊ตซื้อตั๋ว 3 ใบ และจ่าย $20 โอ๊ตได้เงินทอนกี่ดอลลาร์","explanation":"ขั้นที่ 1: ราคารวม = 3 × $4 = $12 ขั้นที่ 2: เงินทอน = $20 − $12 = $8","hint":"หาราคารวมของตั๋วก่อน"}}'::jsonb),
  ('02c00d92-1bf6-441b-8551-db8cf7180e2d', 'a71c0567-02dd-4d66-8368-3db11a369328', 'numeric', 'Lily saves $8 every week for 5 weeks, then spends $34 on a book. How many dollars does Lily have left?', null, '{"value":"6"}'::jsonb, null, 'Step 1: savings = 5 × $8 = $40. Step 2: after buying the book, $40 − $34 = $6.', 'First find how much was saved altogether.', 3, 10, 2, true, '{"my":{"prompt":"လှိုင် က အပတ်တိုင်း $8 စီ 5 ပတ် စုပြီး စာအုပ်တစ်အုပ်အတွက် $34 သုံးတယ်။ လှိုင် မှာ ဘယ်နှဒေါ်လာ ကျန်လဲ။","explanation":"အဆင့် 1 - စုငွေ = 5 × $8 = $40။ အဆင့် 2 - စာအုပ်ဝယ်ပြီးနောက် $40 − $34 = $6။","hint":"စုစုပေါင်း ဘယ်လောက် စုခဲ့လဲ အရင်ရှာပါ။"},"th":{"prompt":"น้ำเก็บเงินสัปดาห์ละ $8 เป็นเวลา 5 สัปดาห์ แล้วซื้อหนังสือ $34 น้ำเหลือเงินกี่ดอลลาร์","explanation":"ขั้นที่ 1: เงินออม = 5 × $8 = $40 ขั้นที่ 2: หลังซื้อหนังสือ $40 − $34 = $6","hint":"หาก่อนว่าเก็บเงินได้ทั้งหมดเท่าไร"}}'::jsonb),
  ('01c00bff-1cf6-45ae-8851-e045f4180974', 'a71c0567-02dd-4d66-8368-3db11a369328', 'numeric', 'Ava saves $3 every week for 7 weeks, then spends $12 on a book. How many dollars does Ava have left?', null, '{"value":"9"}'::jsonb, null, 'Step 1: savings = 7 × $3 = $21. Step 2: after buying the book, $21 − $12 = $9.', 'First find how much was saved altogether.', 3, 10, 3, true, '{"my":{"prompt":"သီရိ က အပတ်တိုင်း $3 စီ 7 ပတ် စုပြီး စာအုပ်တစ်အုပ်အတွက် $12 သုံးတယ်။ သီရိ မှာ ဘယ်နှဒေါ်လာ ကျန်လဲ။","explanation":"အဆင့် 1 - စုငွေ = 7 × $3 = $21။ အဆင့် 2 - စာအုပ်ဝယ်ပြီးနောက် $21 − $12 = $9။","hint":"စုစုပေါင်း ဘယ်လောက် စုခဲ့လဲ အရင်ရှာပါ။"},"th":{"prompt":"ฝนเก็บเงินสัปดาห์ละ $3 เป็นเวลา 7 สัปดาห์ แล้วซื้อหนังสือ $12 ฝนเหลือเงินกี่ดอลลาร์","explanation":"ขั้นที่ 1: เงินออม = 7 × $3 = $21 ขั้นที่ 2: หลังซื้อหนังสือ $21 − $12 = $9","hint":"หาก่อนว่าเก็บเงินได้ทั้งหมดเท่าไร"}}'::jsonb),
  ('00c00a6c-1df6-4741-8751-deb2f5180b07', 'a71c0567-02dd-4d66-8368-3db11a369328', 'numeric', 'Noah saves $8 every week for 5 weeks, then spends $37 on a book. How many dollars does Noah have left?', null, '{"value":"3"}'::jsonb, null, 'Step 1: savings = 5 × $8 = $40. Step 2: after buying the book, $40 − $37 = $3.', 'First find how much was saved altogether.', 3, 10, 4, true, '{"my":{"prompt":"ကျော် က အပတ်တိုင်း $8 စီ 5 ပတ် စုပြီး စာအုပ်တစ်အုပ်အတွက် $37 သုံးတယ်။ ကျော် မှာ ဘယ်နှဒေါ်လာ ကျန်လဲ။","explanation":"အဆင့် 1 - စုငွေ = 5 × $8 = $40။ အဆင့် 2 - စာအုပ်ဝယ်ပြီးနောက် $40 − $37 = $3။","hint":"စုစုပေါင်း ဘယ်လောက် စုခဲ့လဲ အရင်ရှာပါ။"},"th":{"prompt":"ภูมิเก็บเงินสัปดาห์ละ $8 เป็นเวลา 5 สัปดาห์ แล้วซื้อหนังสือ $37 ภูมิเหลือเงินกี่ดอลลาร์","explanation":"ขั้นที่ 1: เงินออม = 5 × $8 = $40 ขั้นที่ 2: หลังซื้อหนังสือ $40 − $37 = $3","hint":"หาก่อนว่าเก็บเงินได้ทั้งหมดเท่าไร"}}'::jsonb),
  ('ffc008d9-1ef6-48d4-8251-d6d3f218064e', 'a71c0567-02dd-4d66-8368-3db11a369328', 'numeric', 'Tickets cost $8 each. Zara buys 5 tickets and pays with $50. How many dollars of change does Zara get?', null, '{"value":"10"}'::jsonb, null, 'Step 1: total cost = 5 × $8 = $40. Step 2: change = $50 − $40 = $10.', 'First find the total cost of the tickets.', 3, 10, 5, true, '{"my":{"prompt":"လက်မှတ်တစ်စောင် $8 ကျတယ်။ နန္ဒာ က လက်မှတ် 5 စောင် ဝယ်ပြီး $50 ပေးတယ်။ နန္ဒာ ပြန်အမ်းငွေ ဘယ်နှဒေါ်လာ ရလဲ။","explanation":"အဆင့် 1 - စုစုပေါင်း ကုန်ကျငွေ = 5 × $8 = $40။ အဆင့် 2 - ပြန်အမ်းငွေ = $50 − $40 = $10။","hint":"လက်မှတ်တွေရဲ့ စုစုပေါင်း ကုန်ကျငွေကို အရင်ရှာပါ။"},"th":{"prompt":"ตั๋วราคาใบละ $8 แพรวซื้อตั๋ว 5 ใบ และจ่าย $50 แพรวได้เงินทอนกี่ดอลลาร์","explanation":"ขั้นที่ 1: ราคารวม = 5 × $8 = $40 ขั้นที่ 2: เงินทอน = $50 − $40 = $10","hint":"หาราคารวมของตั๋วก่อน"}}'::jsonb)
